INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(5401, 151, 'Which cloud service model provides virtualized computing resources such as virtual machines, storage and networking that the customer configures and manages?', 'IaaS', 'PaaS', 'SaaS', 'FaaS', 'A', 'IaaS (Infrastructure as a Service) delivers raw compute, storage and network resources that the customer manages.', 'BEGINNER', 1, 'MCQ', 1),
(5402, 151, 'Which cloud service model gives developers a managed platform where they deploy and run applications without managing the underlying servers?', 'IaaS', 'PaaS', 'SaaS', 'DaaS', 'B', 'PaaS (Platform as a Service) supplies a managed runtime and tooling so developers focus on application code.', 'BEGINNER', 1, 'MCQ', 1),
(5403, 151, 'Which cloud service model delivers fully ready-to-use software applications to end users over the internet?', 'IaaS', 'PaaS', 'SaaS', 'BaaS', 'C', 'SaaS (Software as a Service) provides complete applications such as web mail that users access with no installation.', 'BEGINNER', 1, 'MCQ', 1),
(5404, 151, 'Which cloud deployment model makes computing resources available to the general public on a pay-as-you-go basis?', 'private cloud', 'hybrid cloud', 'edge cloud', 'public cloud', 'D', 'A public cloud is operated by a provider and offered openly to any customer over the internet.', 'BEGINNER', 1, 'MCQ', 1),
(5405, 151, 'Which cloud deployment model uses infrastructure dedicated exclusively to a single organization?', 'private cloud', 'hybrid cloud', 'multi-cloud', 'public cloud', 'A', 'A private cloud is hosted on infrastructure reserved for one organization only.', 'BEGINNER', 1, 'MCQ', 1),
(5406, 151, 'Which deployment model combines on-premises infrastructure with public cloud resources to balance control and scale?', 'public cloud', 'hybrid cloud', 'sovereign cloud', 'serverless', 'B', 'A hybrid cloud links private and public environments so workloads can move between them.', 'BEGINNER', 1, 'MCQ', 1),
(5407, 151, 'Which deployment model describes an organization using more than one cloud provider at the same time?', 'single cloud', 'community cloud', 'multi-cloud', 'fog cloud', 'C', 'Multi-cloud means deliberately using several independent public cloud providers.', 'BEGINNER', 1, 'MCQ', 1),
(5408, 151, 'Which NIST cloud characteristic lets customers provision resources automatically without requiring human interaction with the provider?', 'measured service', 'resource pooling', 'rapid elasticity', 'on-demand self-service', 'D', 'On-demand self-service allows users to request resources through a self-service interface without manual provider action.', 'BEGINNER', 1, 'MCQ', 1),
(5409, 151, 'Which NIST cloud characteristic means capabilities are available over the network through standard mechanisms?', 'broad network access', 'resource pooling', 'rapid elasticity', 'measured service', 'A', 'Broad network access describes resources reachable over the network using standard protocols from various devices.', 'BEGINNER', 1, 'MCQ', 1),
(5410, 151, 'Which NIST cloud characteristic allows computing resources to scale out and in automatically to match demand?', 'resource pooling', 'rapid elasticity', 'measured service', 'on-demand self-service', 'B', 'Rapid elasticity lets capacity grow and shrink elastically, often automatically.', 'BEGINNER', 1, 'MCQ', 1),
(5411, 151, 'A startup needs virtual machines where it controls the operating system, patches and installed software. Which model should it choose?', 'IaaS', 'PaaS', 'SaaS', 'serverless', 'A', 'IaaS gives the customer full control over the VM including its operating system and software.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5412, 151, 'A team wants to deploy a web app using only a preconfigured runtime and database service, ignoring server administration. Which model fits best?', 'IaaS', 'PaaS', 'SaaS', 'bare metal', 'B', 'PaaS abstracts away servers and provides managed runtimes and databases for application deployment.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5413, 151, 'An HR department needs a payroll application available immediately with no internal hosting or upgrades. Which model is most suitable?', 'IaaS', 'PaaS', 'SaaS', 'DaaS', 'C', 'SaaS delivers the finished payroll product over the internet with all maintenance handled by the vendor.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5414, 151, 'A bank keeps customer records on-premises for compliance but wants to burst web traffic to the public cloud during peaks. Which deployment fits?', 'public cloud only', 'private cloud only', 'community cloud', 'hybrid cloud', 'D', 'A hybrid cloud keeps sensitive data in the private environment while scaling overflow to the public cloud.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5415, 151, 'A retailer deliberately runs workloads on AWS, Azure and GCP to avoid depending on one vendor. Which strategy is this?', 'multi-cloud', 'hybrid cloud', 'private cloud', 'fog computing', 'A', 'Using several public providers at once is the definition of a multi-cloud strategy.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5416, 151, 'Compared with IaaS virtual machines, what is the main advantage of a serverless function service?', 'full OS control', 'no infrastructure and server management with pay-per-invocation billing', 'guaranteed zero latency', 'fixed capacity planning', 'B', 'Serverless removes server administration and bills only for the compute consumed during each invocation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5417, 151, 'Which statement correctly distinguishes Function as a Service (FaaS) from other compute models?', 'it runs long-lived virtual machines', 'it requires dedicated servers', 'it executes single functions in response to events', 'it only works with on-premises hardware', 'C', 'FaaS runs event-driven functions that spin up on demand and scale automatically.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5418, 151, 'In a SaaS arrangement, where does the customer responsibility for the underlying infrastructure end?', 'the customer manages the servers', 'the customer manages the OS', 'the customer manages the network', 'the customer manages only its data and users', 'D', 'With SaaS the provider manages everything below the data, so the customer is responsible only for its data and access.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5419, 151, 'Under the shared responsibility model for IaaS, who is responsible for patching the guest operating system of a virtual machine?', 'the customer', 'the cloud provider', 'the hardware vendor', 'the network operator', 'A', 'For IaaS the customer owns the guest OS and must apply its patches, while the provider protects the host.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5420, 151, 'Which service model places the least operational management burden on the customer?', 'IaaS', 'SaaS', 'PaaS', 'managed hosting only', 'B', 'SaaS shifts nearly all management to the provider, leaving the customer with the least operational work.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5421, 151, 'A healthcare company faces strict data residency regulations and must keep patient data inside its own country. Which approach best satisfies this?', 'use a dedicated private cloud or a cloud region located in that country', 'use only public cloud in any region', 'store data on employee laptops', 'outsource to the cheapest provider', 'A', 'A private cloud or a region physically located in the required country meets residency rules while still giving cloud benefits.', 'ADVANCED', 3, 'MCQ', 1),
(5422, 151, 'An organization runs 24x7 workloads yet its cloud bill keeps rising because VMs sit idle outside business hours. Which measure addresses this waste?', 'adding more instances', 'right-sizing and stopping idle instances during off-peak periods', 'moving everything to a single big VM', 'disabling monitoring', 'B', 'Right-sizing instances and shutting down idle ones reduces cost without losing capacity when needed.', 'ADVANCED', 3, 'MCQ', 1),
(5423, 151, 'A company has a predictable baseline workload plus occasional massive demand spikes. Which architecture is most cost-effective?', 'provision for peak capacity permanently', 'use only on-premises hardware', 'keep a baseline and scale elastically for the spikes', 'disable auto scaling', 'C', 'Elastic scaling lets the baseline run efficiently and adds capacity only during spikes.', 'ADVANCED', 3, 'MCQ', 1),
(5424, 151, 'Which scenario best justifies adopting a multi-cloud architecture despite its higher complexity?', 'a single app with trivial uptime needs', 'eliminating all security controls', 'reducing the number of cloud skills needed', 'avoiding vendor lock-in and meeting provider-specific regulatory requirements', 'D', 'Multi-cloud reduces dependence on one vendor and can satisfy regulations that vary by provider.', 'ADVANCED', 3, 'MCQ', 1),
(5425, 151, 'A company must run periodic batch analytics that produce sudden, short-lived CPU spikes. Which compute choice is most efficient?', 'serverless or elastic burst compute for the short jobs', 'always-on dedicated servers', 'a single oversized VM', 'manual batch execution at night', 'A', 'Serverless or burst compute charges only for the short period of activity, suiting spiky batch jobs.', 'ADVANCED', 3, 'MCQ', 1),
(5426, 151, 'Under the shared responsibility model for an IaaS virtual machine, which item is the provider responsible for?', 'physical security of the data center', 'patching the guest OS', 'securing customer passwords', 'installing the customer application', 'B', 'The provider owns the physical infrastructure, including data center security, hosts and the network.', 'ADVANCED', 3, 'MCQ', 1),
(5427, 151, 'A company migrates a legacy monolith to a managed PaaS platform. What is the primary benefit it gains?', 'more server control', 'guaranteed identical performance', 'reduced infrastructure operations so it can focus on application code', 'removal of all security duties', 'C', 'PaaS removes platform administration, letting the team concentrate on developing and deploying the application.', 'ADVANCED', 3, 'MCQ', 1),
(5428, 151, 'Which factor most directly causes slower response times in a cold serverless function start?', 'larger disk quota', 'the number of database rows', 'the DNS TTL', 'initialization time when no warm instance exists', 'D', 'A cold start delays the response because the platform must initialize the runtime before handling the request.', 'ADVANCED', 3, 'MCQ', 1),
(5429, 151, 'A fintech firm must keep core ledger workloads on its own hardware but use the public cloud for analytics. Which deployment model does this describe?', 'hybrid cloud', 'pure public cloud', 'pure private cloud', 'edge computing', 'A', 'Hybrid cloud spans private and public environments, letting the firm keep core workloads on-premises while using the cloud.', 'ADVANCED', 3, 'MCQ', 1),
(5430, 151, 'A customer wants to protect against a single cloud provider outage without rearchitecting to multi-cloud. What is the simplest mitigation?', 'disable redundancy', 'store data only on-premises', 'remove all backups', 'use multiple regions and availability zones of the same provider', 'B', 'Spreading workloads across regions and zones of one provider guards against localized failures without multi-cloud complexity.', 'ADVANCED', 3, 'MCQ', 1),
(5431, 152, 'Which AWS service provides resizable virtual servers in the cloud?', 'EC2', 'S3', 'Lambda', 'RDS', 'A', 'Amazon EC2 offers resizable virtual machines that customers launch with chosen instance types.', 'BEGINNER', 1, 'MCQ', 1),
(5432, 152, 'Which AWS service is a highly durable object storage service for files and media?', 'EBS', 'S3', 'EFS', 'Glacier only', 'B', 'Amazon S3 stores unlimited objects and is AWS''s core object storage service.', 'BEGINNER', 1, 'MCQ', 1),
(5433, 152, 'Which AWS service provides managed relational databases such as MySQL and PostgreSQL?', 'DynamoDB', 'EC2', 'RDS', 'Redshift', 'C', 'Amazon RDS is a managed relational database service supporting engines like MySQL and PostgreSQL.', 'BEGINNER', 1, 'MCQ', 1),
(5434, 152, 'Which AWS service runs code in response to events without provisioning servers?', 'EC2', 'Elastic Beanstalk', 'CloudFront', 'Lambda', 'D', 'AWS Lambda is the serverless compute service that executes functions triggered by events.', 'BEGINNER', 1, 'MCQ', 1),
(5435, 152, 'Which AWS service lets you manage users, groups, roles and permissions securely?', 'IAM', 'CloudWatch', 'Route 53', 'SQS', 'A', 'AWS Identity and Access Management (IAM) controls access to AWS resources.', 'BEGINNER', 1, 'MCQ', 1),
(5436, 152, 'Which AWS service provides an isolated virtual network where you define subnets and routes?', 'Direct Connect', 'VPC', 'CloudFront', 'S3', 'B', 'Amazon VPC creates a logically isolated section of the AWS cloud for your networking.', 'BEGINNER', 1, 'MCQ', 1),
(5437, 152, 'Which AWS service is a content delivery network that caches content close to users?', 'Route 53', 'EC2', 'CloudFront', 'SNS', 'C', 'Amazon CloudFront is AWS''s CDN that accelerates content delivery via edge locations.', 'BEGINNER', 1, 'MCQ', 1),
(5438, 152, 'Which AWS service translates domain names into IP addresses?', 'CloudWatch', 'IAM', 'ElastiCache', 'Route 53', 'D', 'Amazon Route 53 is the AWS DNS and domain registration service.', 'BEGINNER', 1, 'MCQ', 1),
(5439, 152, 'Which AWS service is a fully managed NoSQL database built for key-value and document workloads?', 'DynamoDB', 'Aurora', 'Redshift', 'RDS', 'A', 'Amazon DynamoDB is a managed NoSQL database offering consistent single-digit millisecond access.', 'BEGINNER', 1, 'MCQ', 1),
(5440, 152, 'Which S3 storage class is the default for frequently accessed data?', 'S3 Standard', 'S3 Glacier Deep Archive', 'S3 One Zone-IA', 'S3 Reduced Redundancy', 'B', 'S3 Standard is designed for frequently accessed data with low latency and high durability.', 'BEGINNER', 1, 'MCQ', 1),
(5441, 152, 'A team needs full control over the operating system, kernel and installed software of its compute instances. Which AWS service should it use?', 'Elastic Beanstalk', 'EC2', 'Lambda', 'Fargate', 'A', 'EC2 gives customers full control over the instance including the OS and kernel.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5442, 152, 'Which AWS setup is best for hosting a static website with high availability and low latency?', 'a single EC2 instance', 'S3 bucket with CloudFront in front', 'DynamoDB table', 'a VPC without internet access', 'B', 'S3 serves static files durably and CloudFront caches them at edge locations for speed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5443, 152, 'A web app expects variable traffic and needs instances added and removed automatically. Which AWS feature provides this?', 'Route 53 failover', 'S3 lifecycle rules', 'EC2 Auto Scaling', 'VPC peering', 'C', 'EC2 Auto Scaling launches and terminates instances based on demand and configured policies.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5444, 152, 'A company wants a fully managed PostgreSQL database with automated backups and failover. Which service fits best?', 'DynamoDB', 'ElastiCache', 'S3', 'RDS', 'D', 'Amazon RDS manages the database engine, backups, patching and failover.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5445, 152, 'Which AWS service is best for decoupling microservices so producers and consumers can process messages independently?', 'SQS', 'CloudFront', 'Route 53', 'EFS', 'A', 'Amazon SQS is a managed message queue that decouples application components.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5446, 152, 'Where should an application store database credentials and API keys securely?', 'in the source code', 'AWS Secrets Manager or Parameter Store', 'an S3 public bucket', 'a README file', 'B', 'Secrets Manager keeps credentials encrypted and centrally managed instead of exposing them in code.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5447, 152, 'Which AWS service monitors resources and raises alarms based on metrics such as CPU utilization?', 'IAM', 'Direct Connect', 'CloudWatch', 'Route 53', 'C', 'CloudWatch collects metrics and triggers alarms when thresholds are crossed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5448, 152, 'An organization must archive old files that are rarely accessed at the lowest cost. Which S3 feature should it use?', 'S3 Transfer Acceleration', 'S3 versioning only', 'S3 cross-region replication only', 'S3 lifecycle rules moving objects to Glacier', 'D', 'Lifecycle policies automatically transition infrequently used objects to cheaper archival classes like Glacier.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5449, 152, 'In a VPC, what distinguishes a public subnet from a private subnet?', 'a public subnet has a route to the internet gateway', 'a public subnet has more CPUs', 'a public subnet stores objects', 'a public subnet cannot launch EC2 instances', 'A', 'The presence of an internet gateway route makes a subnet public; without it the subnet is private.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5450, 152, 'Why would you choose EBS volume storage over an EC2 instance store?', 'instance store is cheaper per second', 'EBS data persists independently of the instance lifecycle', 'EBS cannot be snapshotted', 'instance store stores more data', 'B', 'EBS volumes are network-attached and persist across instance stops and terminations, unlike ephemeral instance stores.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5451, 152, 'A company runs a steady 24x7 workload and wants to cut compute cost. Which purchasing option is most effective?', 'Reserved Instances or Savings Plans', 'on-demand instances', 'spot instances for the baseline', 'increasing instance size', 'A', 'Reserved Instances and Savings Plans trade commitment for significantly lower hourly rates on steady workloads.', 'ADVANCED', 3, 'MCQ', 1),
(5452, 152, 'To protect a stateless web tier against a single availability zone failure, which design is correct?', 'place all instances in one AZ', 'run instances in multiple availability zones behind a load balancer', 'disable load balancing', 'use only one large instance', 'B', 'Spreading instances across AZs with a load balancer keeps the tier available if one AZ fails.', 'ADVANCED', 3, 'MCQ', 1),
(5453, 152, 'Which AWS feature protects an S3 bucket against accidental deletion of data?', 'S3 Transfer Acceleration', 'CloudFront cache', 'S3 versioning', 'VPC flow logs', 'C', 'Versioning keeps previous versions of objects so accidental overwrites or deletes can be restored.', 'ADVANCED', 3, 'MCQ', 1),
(5454, 152, 'Which architecture provides a fully serverless REST API on AWS?', 'EC2 instances with an ELB', 'a bare-metal server', 'CloudFront with only static files', 'API Gateway with Lambda functions backed by DynamoDB', 'D', 'API Gateway handles routing and auth while Lambda runs the logic and DynamoDB stores the data.', 'ADVANCED', 3, 'MCQ', 1),
(5455, 152, 'What is the main benefit of configuring reserved concurrency on a Lambda function?', 'it caps concurrent invocations to control throttling and costs', 'it increases the memory of every function', 'it removes the need for IAM', 'it speeds up cold starts indefinitely', 'A', 'Reserved concurrency limits how many instances run at once, preventing runaway scaling and cost.', 'ADVANCED', 3, 'MCQ', 1),
(5456, 152, 'Which statement correctly describes an AWS security group?', 'it is a stateless network ACL for subnets', 'it is a stateful instance-level firewall', 'it encrypts all traffic', 'it replaces IAM', 'B', 'Security groups are stateful firewalls applied at the instance level; return traffic is allowed automatically.', 'ADVANCED', 3, 'MCQ', 1),
(5457, 152, 'Which option is the most effective way to reduce data egress costs when serving a global user base?', 'make the S3 bucket public', 'increase EC2 instance sizes', 'serve content through CloudFront edge caches', 'use more AZs in one region', 'C', 'CloudFront caches content at edge locations, so most requests are served without reaching the origin.', 'ADVANCED', 3, 'MCQ', 1),
(5458, 152, 'How do you scale read-heavy database workloads on Amazon RDS?', 'stop the database at night', 'disable query logging', 'add more AZs to the same instance', 'create Read Replicas to offload SELECT traffic', 'D', 'Read Replicas are asynchronous copies that serve read traffic, reducing load on the primary database.', 'ADVANCED', 3, 'MCQ', 1),
(5459, 152, 'Which combination is best for a cost-aware, fault-tolerant static asset delivery architecture?', 'S3 Standard with S3 Replication and CloudFront', 'a single EC2 instance with a public IP', 'an on-premises FTP server', 'a Lambda function per request', 'A', 'S3 gives durability, replication adds DR protection and CloudFront provides fast, cheap distribution.', 'ADVANCED', 3, 'MCQ', 1),
(5460, 152, 'Under IAM best practices, what does the principle of least privilege mean?', 'grant every user admin rights', 'grant only the permissions needed to perform required tasks', 'share one root account', 'never use roles', 'B', 'Least privilege limits access to exactly what each user or role needs, reducing blast radius.', 'ADVANCED', 3, 'MCQ', 1),
(5461, 153, 'Which Azure service provides resizable virtual machines similar to AWS EC2?', 'Azure Virtual Machines', 'Azure Blob Storage', 'Azure Functions', 'Azure SQL Database', 'A', 'Azure Virtual Machines offers on-demand Windows and Linux virtual machines.', 'BEGINNER', 1, 'MCQ', 1),
(5462, 153, 'Which Azure service is the equivalent of AWS S3 for storing unstructured objects and blobs?', 'Azure Table', 'Azure Blob Storage', 'Azure DNS', 'Azure VNet', 'B', 'Azure Blob Storage stores large amounts of unstructured data such as files and images.', 'BEGINNER', 1, 'MCQ', 1),
(5463, 153, 'Which Azure service provides a managed relational database for SQL Server?', 'Azure Cosmos DB', 'Azure Redis', 'Azure SQL Database', 'Azure Files', 'C', 'Azure SQL Database is a fully managed relational database based on SQL Server.', 'BEGINNER', 1, 'MCQ', 1),
(5464, 153, 'Which Azure service runs serverless code in response to events?', 'Azure Virtual Machines', 'Azure Front Door', 'Azure CDN', 'Azure Functions', 'D', 'Azure Functions is the serverless compute service for event-driven functions.', 'BEGINNER', 1, 'MCQ', 1),
(5465, 153, 'Which Azure service manages identities and access for users and applications?', 'Microsoft Entra ID (Azure AD)', 'Azure Monitor', 'Azure Storage', 'Azure DNS', 'A', 'Microsoft Entra ID, formerly Azure Active Directory, provides identity and access management.', 'BEGINNER', 1, 'MCQ', 1),
(5466, 153, 'Which GCP service provides virtual machines that you can resize as needed?', 'Cloud Functions', 'Compute Engine', 'BigQuery', 'App Engine', 'B', 'Google Compute Engine offers resizable virtual machines on Google Cloud.', 'BEGINNER', 1, 'MCQ', 1),
(5467, 153, 'Which GCP service stores unstructured objects such as images and backups?', 'Cloud SQL', 'Cloud Spanner', 'Cloud Storage', 'BigQuery', 'C', 'Google Cloud Storage is GCP''s scalable object storage service.', 'BEGINNER', 1, 'MCQ', 1),
(5468, 153, 'Which GCP service is the serverless compute option for event-driven functions?', 'Compute Engine', 'Kubernetes Engine', 'Cloud Run only', 'Cloud Functions', 'D', 'Cloud Functions executes single-purpose functions in response to events.', 'BEGINNER', 1, 'MCQ', 1),
(5469, 153, 'Which GCP service provides a fully managed Kubernetes environment?', 'Google Kubernetes Engine (GKE)', 'Cloud SQL', 'Compute Engine', 'Cloud Storage', 'A', 'GKE is Google''s managed Kubernetes service for running containerized workloads.', 'BEGINNER', 1, 'MCQ', 1),
(5470, 153, 'What is an Azure region?', 'a single server in a data center', 'a geographic area containing one or more data centers', 'a virtual machine', 'a type of network', 'B', 'An Azure region is a set of data centers located within a geographic boundary.', 'BEGINNER', 1, 'MCQ', 1),
(5471, 153, 'A company runs flexible batch jobs in GCP that can be interrupted. Which instance type is most cost-effective?', 'preemptible (spot) VMs', 'sole-tenant nodes', 'GPU instances for every job', 'memory-optimized instances', 'A', 'Preemptible VMs are significantly cheaper and fine for interruptible, stateless batch work.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5472, 153, 'Which Azure service is best for hosting a web app while the platform manages scaling and patching?', 'Azure Virtual Machines', 'Azure App Service', 'Azure Blob Storage', 'Azure DNS', 'B', 'Azure App Service is a PaaS for hosting web apps with built-in scaling and management.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5473, 153, 'Which GCP service is a serverless, fully managed data warehouse for petabyte-scale analytics?', 'Cloud SQL', 'Datastore', 'BigQuery', 'Cloud Storage', 'C', 'BigQuery is a serverless data warehouse with SQL analytics at massive scale.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5474, 153, 'Which Azure service provides CI/CD pipelines for building and deploying applications?', 'Azure Front Door', 'Azure Monitor', 'Azure DNS', 'Azure DevOps', 'D', 'Azure DevOps includes pipelines for continuous integration and continuous delivery.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5475, 153, 'Which GCP service runs containerized applications in a fully managed serverless environment?', 'Cloud Run', 'Compute Engine', 'Cloud Functions only', 'Cloud Storage', 'A', 'Cloud Run executes stateless containers that scale automatically without managing servers.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5476, 153, 'What is the purpose of an Azure resource group?', 'a type of virtual machine', 'a logical container for grouping related Azure resources', 'a DNS zone', 'a firewall rule', 'B', 'Resource groups group related resources so they can be managed, monitored and deleted together.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5477, 153, 'Which statement about GCP VPC networking is correct?', 'VPCs exist only inside one zone', 'VPCs cannot be shared', 'a single VPC network is global and spans all regions', 'each VM gets its own private cloud', 'C', 'GCP VPC networks are global, letting the same network span regions with subnets in each.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5478, 153, 'What do Azure availability zones provide?', 'a global content delivery network', 'a DNS service', 'an identity service', 'isolated data centers within a region for fault tolerance', 'D', 'Availability zones are physically separate locations within a region that protect against datacenter failures.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5479, 153, 'Which GCP service provides managed MySQL and PostgreSQL databases?', 'Cloud SQL', 'BigQuery', 'Cloud Spanner', 'Firestore', 'A', 'Cloud SQL offers fully managed relational databases compatible with MySQL and PostgreSQL.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5480, 153, 'Which Azure service is a globally distributed NoSQL database with multiple consistency options?', 'Azure SQL Database', 'Azure Cosmos DB', 'Azure Table', 'Azure Cache for Redis', 'B', 'Cosmos DB is a multi-model, globally distributed NoSQL database service.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5481, 153, 'A company runs steady GCP workloads 24x7 and wants to lower cost. Which GCP pricing benefit applies automatically?', 'sustained use discounts for running VMs for a large fraction of the month', 'no billing for data egress', 'free GPU instances', 'paying only for memory', 'A', 'Sustained use discounts automatically reduce the cost of VMs run for most of a billing month.', 'ADVANCED', 3, 'MCQ', 1),
(5482, 153, 'Which Azure feature lets customers reuse existing Windows Server licenses to reduce VM cost?', 'Azure Spot VMs', 'Azure Hybrid Benefit', 'Azure Savings Plans only', 'Azure Reserved IP', 'B', 'Azure Hybrid Benefit applies existing on-premises Windows Server licenses to discounted Azure VM pricing.', 'ADVANCED', 3, 'MCQ', 1),
(5483, 153, 'Which GCP mechanism enforces restrictions such as allowing only certain regions for a project?', 'Cloud CDN', 'Cloud SQL', 'organization policies', 'preemptible VMs', 'C', 'Organization policies apply constraints across GCP resources, such as restricting allowed regions.', 'ADVANCED', 3, 'MCQ', 1),
(5484, 153, 'Which Azure tooling enforces corporate compliance by defining and auditing policy rules across subscriptions?', 'Azure CDN', 'Azure Cosmos DB', 'Azure Traffic Manager only', 'Azure Policy with Azure Blueprints', 'D', 'Azure Policy evaluates resources against defined rules, and Blueprints bundle reusable governance definitions.', 'ADVANCED', 3, 'MCQ', 1),
(5485, 153, 'Which GCP database provides strongly consistent global relational storage for a financial services app?', 'Cloud Spanner', 'Firestore', 'Bigtable', 'Cloud Storage', 'A', 'Cloud Spanner is a globally distributed relational database offering strong consistency at scale.', 'ADVANCED', 3, 'MCQ', 1),
(5486, 153, 'Which Azure networking pattern centralizes shared services with spoke workloads connecting to a hub?', 'a single flat subnet', 'hub-and-spoke with VNet peering', 'direct internet connections only', 'Azure DNS zones only', 'B', 'Hub-and-spoke uses VNet peering to route spokes through a central hub for shared security and services.', 'ADVANCED', 3, 'MCQ', 1),
(5487, 153, 'Which GKE feature automatically adds or removes nodes based on pending pod demand?', 'node pool versioning', 'Cloud CDN', 'cluster autoscaler', 'preemptible billing', 'C', 'The GKE cluster autoscaler resizes node pools so capacity matches current pod requirements.', 'ADVANCED', 3, 'MCQ', 1),
(5488, 153, 'Which Azure Blob Storage access tier is intended for data that is accessed rarely and kept for years?', 'Hot', 'Cool', 'Premium only', 'Archive', 'D', 'The Archive tier stores rarely accessed data at the lowest cost with delayed retrieval.', 'ADVANCED', 3, 'MCQ', 1),
(5489, 153, 'Which GCP networking feature lets a network team centrally manage subnets shared by many projects?', 'Shared VPC', 'Cloud Interconnect', 'Cloud NAT', 'VPC flow logs', 'A', 'Shared VPC allows a central host project to share its networking with multiple service projects.', 'ADVANCED', 3, 'MCQ', 1),
(5490, 153, 'Which Azure construct provides a standardized foundation of policy, security and networking for new workloads?', 'a single resource group', 'Azure Landing Zones', 'Azure Blob containers', 'Azure Spot VMs', 'B', 'Landing Zones are prescriptive reference architectures that give enterprise governance and networking at scale.', 'ADVANCED', 3, 'MCQ', 1),
(5491, 154, 'What type of storage does Amazon S3 provide?', 'object storage', 'block storage', 'file storage', 'in-memory cache', 'A', 'S3 stores data as objects in buckets, which is the object storage model.', 'BEGINNER', 1, 'MCQ', 1),
(5492, 154, 'Which storage type is attached to a virtual machine and behaves like a raw disk?', 'object storage', 'block storage', 'file storage', 'DNS storage', 'B', 'Block storage such as EBS presents raw volumes that a VM formats and mounts like a disk.', 'BEGINNER', 1, 'MCQ', 1),
(5493, 154, 'Which AWS storage service provides a shared file system mountable by multiple instances?', 'S3', 'DynamoDB', 'EFS', 'CloudFront', 'C', 'Amazon EFS is a managed file system that many EC2 instances can mount concurrently.', 'BEGINNER', 1, 'MCQ', 1),
(5494, 154, 'What distinguishes a relational database from a NoSQL database?', 'NoSQL databases always require SQL', 'relational databases cannot store data', 'NoSQL databases are always slower', 'relational databases use tables with defined schemas and SQL', 'D', 'Relational databases organize data into tables with schemas and query it with SQL.', 'BEGINNER', 1, 'MCQ', 1),
(5495, 154, 'What is a primary key in a relational database?', 'a column that uniquely identifies each row', 'a column with duplicate values', 'a type of index on every table', 'a database backup', 'A', 'A primary key uniquely identifies every row in a table, preventing duplicates.', 'BEGINNER', 1, 'MCQ', 1),
(5496, 154, 'What is the main difference between a database and a data warehouse?', 'a data warehouse stores only text files', 'a data warehouse is optimized for analytics on large historical datasets', 'a database cannot store numbers', 'a warehouse runs the application code', 'B', 'Data warehouses are designed for analytical queries across large, consolidated datasets.', 'BEGINNER', 1, 'MCQ', 1),
(5497, 154, 'What is the purpose of a database backup?', 'to speed up queries', 'to encrypt passwords', 'to restore data after loss or corruption', 'to create new databases', 'C', 'Backups capture data so it can be recovered after failures or accidental deletion.', 'BEGINNER', 1, 'MCQ', 1),
(5498, 154, 'What is database replication?', 'deleting old records', 'renaming tables', 'compressing the database', 'copying data to additional servers for availability and reads', 'D', 'Replication maintains copies of data on other servers, improving availability and read performance.', 'BEGINNER', 1, 'MCQ', 1),
(5499, 154, 'Which language is used to query relational databases?', 'SQL', 'HTML', 'JSON', 'YAML', 'A', 'SQL (Structured Query Language) is the standard language for querying relational databases.', 'BEGINNER', 1, 'MCQ', 1),
(5500, 154, 'Which type of NoSQL database stores data as JSON-like documents?', 'relational databases', 'document databases such as MongoDB', 'data warehouses', 'columnar OLAP only', 'B', 'Document databases store flexible, JSON-like documents rather than fixed table rows.', 'BEGINNER', 1, 'MCQ', 1),
(5501, 154, 'Which combination of S3 features best protects against accidental object deletion and manages data age?', 'versioning plus lifecycle rules', 'only bucket encryption', 'only a public bucket', 'S3 Transfer Acceleration', 'A', 'Versioning preserves deleted versions while lifecycle rules automatically archive or expire old objects.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5502, 154, 'Which storage choice is correct when multiple application servers need to read and write the same files?', 'an S3 private bucket used as a disk', 'a shared file system such as EFS', 'a single EBS volume attached to one instance', 'an in-memory cache', 'B', 'EFS is a shared file system, whereas an EBS volume can normally attach to only one instance at a time.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5503, 154, 'For a high-throughput key-value lookup with predictable low latency, which database fits best?', 'a relational database with joins', 'a data warehouse', 'DynamoDB', 'a static S3 site', 'C', 'DynamoDB is a NoSQL key-value database built for consistent low-latency lookups.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5504, 154, 'Why does adding an index to a table usually speed up queries?', 'it duplicates every row', 'it removes the primary key', 'it disables caching', 'it lets the database find rows without scanning the whole table', 'D', 'An index is a sorted structure that lets the engine locate rows quickly instead of scanning everything.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5505, 154, 'What does the ACID acronym describe?', 'transaction properties: Atomicity, Consistency, Isolation, Durability', 'a type of disk', 'a storage class', 'an encryption algorithm', 'A', 'ACID defines the reliability guarantees that relational transactions should provide.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5506, 154, 'Which technique reduces load on a primary database by serving read queries from copies?', 'primary key reuse', 'read replicas', 'deleting indexes', 'disabling the cache', 'B', 'Read replicas are asynchronous copies that absorb SELECT traffic, protecting the primary.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5507, 154, 'Why do applications typically use a connection pool?', 'it encrypts all data', 'it creates backups automatically', 'reusing database connections avoids the overhead of opening new ones', 'it shrinks the database', 'C', 'Connection pooling reuses established connections, cutting the cost of repeated setup and teardown.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5508, 154, 'Which S3 storage class is the cheapest for data that is accessed at most once per year?', 'S3 Standard', 'S3 Intelligent-Tiering', 'S3 One Zone-IA', 'S3 Glacier Deep Archive', 'D', 'Glacier Deep Archive offers the lowest storage price for rarely accessed archival data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5509, 154, 'Why should data be encrypted at rest in cloud storage?', 'it protects the data if physical media or access controls are compromised', 'it makes the data faster', 'it reduces storage costs', 'it is required for public buckets only', 'A', 'Encryption at rest ensures that stored data stays unreadable without keys even if storage is breached.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5510, 154, 'What does a backup retention policy control?', 'the number of CPUs', 'how long backup copies are kept before they are removed', 'the database schema', 'the query language', 'B', 'Retention rules define how long backups remain available for restore before expiring.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5511, 154, 'To guarantee database availability when an entire availability zone fails, which design is correct for RDS?', 'deploy Multi-AZ with automatic failover to a standby replica', 'run the database on one EC2 instance', 'disable automated backups', 'put the DB in a single AZ', 'A', 'Multi-AZ RDS maintains a standby in another AZ and fails over automatically.', 'ADVANCED', 3, 'MCQ', 1),
(5512, 154, 'Which statement about S3 consistency is correct today?', 'S3 is eventually consistent only', 'S3 provides strong read-after-write consistency for all objects', 'S3 never guarantees reads', 'S3 consistency depends on the bucket name', 'B', 'Since 2020, S3 offers strong read-after-write consistency for both new and overwritten objects.', 'ADVANCED', 3, 'MCQ', 1),
(5513, 154, 'How would you enable fast queries on a non-key attribute in DynamoDB?', 'add a second table with no key', 'run full scans on every request', 'create a global secondary index on that attribute', 'disable the primary key', 'C', 'A global secondary index lets you query by other attributes with its own key schema.', 'ADVANCED', 3, 'MCQ', 1),
(5514, 154, 'When a single database table grows too large for one node, which technique distributes rows across multiple nodes?', 'adding more columns', 'turning off indexes', 'storing data as JSON', 'sharding (horizontal partitioning)', 'D', 'Sharding splits rows across shards so each node stores only a subset of the data.', 'ADVANCED', 3, 'MCQ', 1),
(5515, 154, 'Which AWS option is most cost-effective for storing rarely accessed compliance records that must be kept for 7 years?', 'S3 Glacier with lifecycle transitions from Standard', 'S3 Standard only', 'EC2 instance storage', 'an EBS volume per record', 'A', 'Lifecycle rules move old objects to Glacier, giving cheap long-term archival storage.', 'ADVANCED', 3, 'MCQ', 1),
(5516, 154, 'A search-heavy application returns the same results repeatedly. Which pattern reduces database load?', 'querying without indexes', 'cache-aside with a cache such as ElastiCache', 'storing cache in the database', 'disabling the primary key', 'B', 'Cache-aside stores frequent query results in a cache and checks it before hitting the database.', 'ADVANCED', 3, 'MCQ', 1),
(5517, 154, 'Which pattern updates a data store automatically whenever a new object is uploaded to S3?', 'a cron job that polls manually', 'RDS read replicas', 'S3 event notifications triggering a Lambda function', 'VPC flow logs', 'C', 'S3 can publish events to Lambda on object creation, enabling event-driven data pipelines.', 'ADVANCED', 3, 'MCQ', 1),
(5518, 154, 'When running heavy analytics on terabytes of transactional history, which storage choice is most appropriate?', 'a transactional OLTP database', 'a single CSV file', 'an in-memory key-value cache', 'a columnar data warehouse such as Redshift or BigQuery', 'D', 'Columnar warehouses are optimized for scanning large analytical datasets efficiently.', 'ADVANCED', 3, 'MCQ', 1),
(5519, 154, 'What trade-off must be considered with cross-region database replication?', 'replication latency and cost versus faster regional recovery', 'there are no trade-offs', 'it reduces durability', 'it prevents reads entirely', 'A', 'Cross-region replication improves disaster recovery but adds latency and cost for copying data.', 'ADVANCED', 3, 'MCQ', 1),
(5520, 154, 'To serve billions of records with queries on multiple fields while keeping low latency, which database choice is sound?', 'a single-row relational table', 'DynamoDB with secondary indexes or a globally distributed NoSQL database', 'an FTP server', 'a data warehouse for online traffic', 'B', 'A NoSQL database with secondary indexes scales to large datasets while keeping query latency low.', 'ADVANCED', 3, 'MCQ', 1),
(5521, 155, 'What is a microservice?', 'a small, independently deployable service that performs one function', 'a single huge application', 'a type of virtual machine', 'a load balancer', 'A', 'Microservices are small, independently deployable services that each handle a focused business function.', 'BEGINNER', 1, 'MCQ', 1),
(5522, 155, 'What is the main purpose of a load balancer?', 'storing backups', 'distributing traffic across multiple servers', 'compiling code', 'encrypting the database', 'B', 'A load balancer spreads incoming requests across healthy instances to share load and improve availability.', 'BEGINNER', 1, 'MCQ', 1),
(5523, 155, 'What does auto scaling allow a system to do?', 'scale only up to one server', 'delete all backups', 'automatically add or remove resources based on demand', 'reduce monitoring', 'C', 'Auto scaling adjusts capacity automatically to match current demand.', 'BEGINNER', 1, 'MCQ', 1),
(5524, 155, 'What is fault tolerance?', 'the speed of a hard disk', 'the size of the database', 'the number of users', 'the ability to keep operating correctly when some components fail', 'D', 'A fault-tolerant system continues to work even when part of it fails.', 'BEGINNER', 1, 'MCQ', 1),
(5525, 155, 'What does high availability (HA) mean?', 'systems remain accessible with minimal downtime over long periods', 'a server with more RAM', 'a public IP address', 'a faster network', 'A', 'High availability keeps services reachable by minimizing downtime, usually through redundancy.', 'BEGINNER', 1, 'MCQ', 1),
(5526, 155, 'What is the Recovery Time Objective (RTO)?', 'the number of backups', 'the maximum acceptable time to restore a service after a disaster', 'the size of a server', 'the cost of a VM', 'B', 'RTO defines how quickly a system must be restored after a disruption.', 'BEGINNER', 1, 'MCQ', 1),
(5527, 155, 'What is a Content Delivery Network (CDN)?', 'a database engine', 'a virtual private network', 'a distributed network of servers that caches content near users', 'a type of firewall', 'C', 'A CDN serves cached copies of content from edge servers close to the user for lower latency.', 'BEGINNER', 1, 'MCQ', 1),
(5528, 155, 'What is the main role of an API gateway?', 'a data warehouse', 'a disk type', 'a load balancer only for websites', 'a single entry point that routes, secures and throttles API requests', 'D', 'An API gateway fronts backend services, handling routing, authentication, rate limiting and monitoring.', 'BEGINNER', 1, 'MCQ', 1),
(5529, 155, 'What is monitoring in a cloud architecture?', 'collecting and analyzing metrics, logs and alerts about system health', 'backing up the source code', 'building the application', 'paying the bill', 'A', 'Monitoring gathers metrics and logs so operators can detect and react to problems.', 'BEGINNER', 1, 'MCQ', 1),
(5530, 155, 'What is the goal of cloud cost management?', 'spending as much as possible', 'optimizing spending while maintaining required performance and availability', 'hiding costs', 'removing all resources', 'B', 'Cost management aims to get the required performance for the lowest reasonable spend.', 'BEGINNER', 1, 'MCQ', 1),
(5531, 155, 'Why should application services be designed to be stateless?', 'stateless services scale horizontally because any instance can serve any request', 'they cannot handle failures', 'they are harder to deploy', 'they require a database on every node', 'A', 'Stateless services keep no local state, so any instance can handle any request, enabling simple horizontal scaling.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5532, 155, 'Which approach scales a web tier to handle 10x traffic?', 'increasing RAM on one server', 'horizontal scaling by adding more instances behind a load balancer', 'deleting instances', 'disabling the load balancer', 'B', 'Horizontal scaling adds instances and balances load across them, giving near-linear capacity growth.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5533, 155, 'What is the purpose of autoscaling in a cloud architecture?', 'it automatically adds and removes compute capacity based on demand', 'it permanently runs the largest possible fleet of servers', 'it replaces the load balancer', 'it keeps every instance in a single availability zone', 'A', 'Autoscaling monitors utilization metrics and adjusts the number of instances so capacity matches demand without manual intervention.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5534, 155, 'Which deployment strategy runs the new version alongside the old one and shifts traffic gradually?', 'in-place restart', 'deleting the old version', 'manual FTP upload', 'blue-green deployment', 'D', 'Blue-green deployment keeps two environments and shifts traffic between them for low-risk releases.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5535, 155, 'Why do distributed systems use retries with exponential backoff?', 'it retries failed calls with increasing delays to avoid overwhelming a recovering service', 'it retries instantly forever', 'it gives up immediately', 'it duplicates all requests', 'A', 'Exponential backoff spreads retries out, giving the failing service time to recover without adding load.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5536, 155, 'What is the purpose of a circuit breaker in a microservice architecture?', 'it encrypts all traffic', 'it stops calls to a failing dependency to prevent cascading failures', 'it caches static files', 'it renames services', 'B', 'A circuit breaker opens when a dependency fails, rejecting calls quickly so failures do not cascade.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5537, 155, 'What makes an API operation idempotent?', 'it can never fail', 'it always deletes data', 'repeating the same request produces the same result as a single call', 'it returns random values', 'C', 'Idempotent operations return the same result no matter how many times they are retried, which is key for retries.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5538, 155, 'Which practice directly reduces cloud spend for consistently over-provisioned instances?', 'buying the largest instances', 'adding more monitoring alarms', 'removing cost reports', 'right-sizing instances to match actual utilization', 'D', 'Right-sizing matches instance size to real usage so you stop paying for unused capacity.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5539, 155, 'Why are cloud resources typically tagged?', 'tags group resources by cost center, environment or owner for tracking and billing', 'tags speed up the CPU', 'tags replace security groups', 'tags are mandatory for encryption', 'A', 'Tagging lets organizations allocate cost, manage environments and enforce policies by resource metadata.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5540, 155, 'How do budgets and alerts help control cloud costs?', 'they delete all resources', 'they warn teams before spending exceeds set thresholds', 'they block internet access', 'they slow the network', 'B', 'Budgets notify stakeholders when spending approaches limits so corrective action can be taken early.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5541, 155, 'Which set of principles forms the AWS Well-Architected Framework?', 'Operational Excellence, Security, Reliability, Performance Efficiency and Cost Optimization', 'Speed, Memory and Storage only', 'a single design pattern', 'one cloud provider only', 'A', 'The five pillars guide architects in building secure, reliable and cost-efficient systems.', 'ADVANCED', 3, 'MCQ', 1),
(5542, 155, 'How should capacity be planned for a workload with a stable base and seasonal spikes?', 'reserve everything at peak', 'buy nothing and hope', 'run only spot instances', 'use reserved capacity for the base and on-demand or spot for the spikes', 'B', 'Reserving the predictable base and flexing the spikes with on-demand or spot keeps cost low and availability high.', 'ADVANCED', 3, 'MCQ', 1),
(5543, 155, 'Which architecture provides the lowest recovery time for a globally distributed application?', 'a single region with nightly backups', 'one instance in one AZ', 'active-active multi-region with automatic failover', 'manual restoration from tape', 'C', 'Active-active deployment serves traffic from multiple regions so failover is immediate when one region fails.', 'ADVANCED', 3, 'MCQ', 1),
(5544, 155, 'What is chaos engineering?', 'deleting the database by accident', 'a compliance rule', 'a backup strategy', 'deliberately injecting failures in production to test resilience', 'D', 'Chaos engineering intentionally introduces failures so teams discover and fix weaknesses before real outages.', 'ADVANCED', 3, 'MCQ', 1),
(5545, 155, 'For a workload with highly unpredictable, short-lived spikes, which compute choice usually offers the lowest cost?', 'serverless functions that scale to zero between invocations', 'always-on large instances', 'a dedicated physical server', 'a permanently running cluster', 'A', 'Serverless scales to zero when idle, so there is no cost between bursts of activity.', 'ADVANCED', 3, 'MCQ', 1),
(5546, 155, 'What is an error budget in SRE?', 'the cost of errors', 'the allowed amount of downtime defined by a reliability target', 'a security policy', 'the number of developers', 'B', 'An error budget is the acceptable failure margin implied by an SLO, guiding when to release versus focus on stability.', 'ADVANCED', 3, 'MCQ', 1),
(5547, 155, 'Which technique most directly reduces data egress costs for a media-heavy global application?', 'removing all caches', 'streaming from a single origin', 'caching content at edge locations with a CDN', 'increasing instance sizes', 'C', 'A CDN serves the bulk of requests from edge caches, drastically cutting origin egress traffic and cost.', 'ADVANCED', 3, 'MCQ', 1),
(5548, 155, 'Which migration strategy incrementally replaces parts of a legacy monolith with microservices?', 'a full rewrite overnight', 'switching to a database without code', 'disabling the legacy app', 'the strangler fig pattern', 'D', 'The strangler fig pattern gradually routes functionality to new services until the monolith is replaced.', 'ADVANCED', 3, 'MCQ', 1),
(5549, 155, 'What is the difference between showback and chargeback in FinOps?', 'showback reports costs to teams without billing them, while chargeback bills them directly', 'they are the same thing', 'showback deletes cost data', 'chargeback hides costs', 'A', 'Showback increases cost awareness by reporting, whereas chargeback actually transfers the cost to the consuming team.', 'ADVANCED', 3, 'MCQ', 1),
(5550, 155, 'An organization defines RPO as 15 minutes for its core database. What must the architecture guarantee?', 'the database must be restored in 15 minutes', 'no more than 15 minutes of data can be lost in a disaster', '15 backups must exist', 'the RTO is also 15 minutes', 'B', 'RPO is the maximum acceptable data loss, so replication or frequent backups must keep losses within 15 minutes.', 'ADVANCED', 3, 'MCQ', 1),
(5551, 156, 'Which three properties form the core of the CIA security triad?', 'Confidentiality, Integrity, Availability', 'Confidentiality, Isolation, Authentication', 'Centralization, Integrity, Availability', 'Confidentiality, Integrity, Authorization', 'A', 'The CIA triad consists of Confidentiality, Integrity and Availability, the three core goals of information security.', 'BEGINNER', 1, 'MCQ', 1),
(5552, 156, 'Which CIA goal ensures information cannot be modified by unauthorized parties?', 'Integrity', 'Confidentiality', 'Authentication', 'Non-repudiation', 'A', 'Integrity guarantees that data has not been altered or tampered with by unauthorized users.', 'BEGINNER', 1, 'MCQ', 1),
(5553, 156, 'Which technique is most commonly used to protect the confidentiality of data at rest?', 'Encryption', 'A firewall', 'A honeypot', 'A load balancer', 'A', 'Encryption transforms plaintext into ciphertext so that data at rest remains unreadable without the correct key.', 'BEGINNER', 1, 'MCQ', 1),
(5554, 156, 'Which principle grants users only the permissions required to perform their job?', 'Least privilege', 'Separation of duties', 'Defense in depth', 'Fail open', 'B', 'The principle of least privilege limits each user to the minimum access needed for their role.', 'BEGINNER', 1, 'MCQ', 1),
(5555, 156, 'What is the relationship between a threat and a vulnerability?', 'A threat is a weakness and a vulnerability is the attacker', 'A threat is a potential danger that can exploit a vulnerability, which is a weakness', 'They are the same concept', 'A vulnerability is always accidental while a threat is always intentional', 'B', 'A threat is a potential source of harm, while a vulnerability is a weakness that the threat can exploit.', 'BEGINNER', 1, 'MCQ', 1),
(5556, 156, 'Which strategy layers multiple independent security controls so that a single failure does not compromise the system?', 'Defense in depth', 'Single point of failure', 'Least privilege', 'Fail closed', 'B', 'Defense in depth uses overlapping controls so that even if one layer fails, other layers still protect the asset.', 'BEGINNER', 1, 'MCQ', 1),
(5557, 156, 'In risk management, which term refers to anything of value that requires protection?', 'An asset', 'A threat actor', 'A control', 'An incident', 'C', 'An asset is any resource of value to the organization, such as data, hardware, or reputation, that needs protection.', 'BEGINNER', 1, 'MCQ', 1),
(5558, 156, 'Which network device filters traffic based on rules such as source IP, port, and protocol?', 'A firewall', 'A switch', 'A repeater', 'An access point', 'C', 'A firewall inspects network traffic and allows or blocks it according to a defined set of security rules.', 'BEGINNER', 1, 'MCQ', 1),
(5559, 156, 'If risk is calculated as likelihood multiplied by impact, which action most directly reduces the risk score?', 'Reduce the likelihood or impact of a loss', 'Increase the number of users', 'Add more network bandwidth', 'Disable logging', 'D', 'Lowering either the likelihood or the impact of a negative event directly reduces the resulting risk score.', 'BEGINNER', 1, 'MCQ', 1),
(5560, 156, 'Which pair of terms best describes verifying who a user is versus what they are allowed to do?', 'Authentication and authorization', 'Encryption and hashing', 'Detection and response', 'Auditing and logging', 'D', 'Authentication verifies a user''s identity, while authorization determines what actions that identity may perform.', 'BEGINNER', 1, 'MCQ', 1),
(5561, 156, 'A hospital must keep patient records private but also available to doctors during outages. Which additional control best addresses availability without weakening confidentiality?', 'Redundant power, networking, and backup systems', 'Deleting older patient records', 'Sharing a single password among doctors', 'Removing all audit logs', 'A', 'Redundancy and reliable backups keep records available during outages while the data remains encrypted and private.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5562, 156, 'An analyst finds that a terminated employee still has an active email account. Which control should have prevented this?', 'Promptly disabling accounts when an employee leaves', 'Increasing the password length', 'Adding more servers', 'Using a stronger encryption algorithm', 'A', 'Account lifecycle management, including immediate deprovisioning on termination, removes access when it is no longer needed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5563, 156, 'A company stores unencrypted backup tapes containing financial data. Which control best addresses this confidentiality risk?', 'Encrypt the tapes before storing them', 'Label the tapes clearly', 'Keep the tapes near the servers', 'Delete the data after backing up', 'A', 'Encrypting the tapes ensures that the financial data is unreadable even if the physical media is lost or stolen.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5564, 156, 'A web application allows any user to view another user''s profile by changing an ID in the URL. Which principle was violated?', 'Authorization and least privilege', 'Authentication only', 'Availability', 'Encryption strength', 'B', 'The application fails to check whether the logged-in user is authorized to access the requested profile, violating authorization.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5565, 156, 'Which order correctly reflects the typical phases of a risk management process?', 'Identify, assess, treat, monitor', 'Monitor, treat, assess, identify', 'Assess, identify, monitor, treat', 'Treat, monitor, identify, assess', 'B', 'Risk management begins by identifying risks, then assessing them, then treating them, and finally monitoring the results.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5566, 156, 'A security team implements biometrics, smart cards, and passphrases. Which security goal are they most directly strengthening?', 'Authentication of identities', 'Network performance', 'Data compression', 'Physical cooling', 'B', 'Requiring multiple verification factors strengthens authentication because an attacker must defeat each factor.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5567, 156, 'A legacy server cannot be patched but must remain online. Which compensating control is most appropriate?', 'Isolate it behind a firewall segment and restrict allowed traffic', 'Remove its audit logs', 'Give every user administrative rights', 'Connect it directly to the internet', 'C', 'Isolating an unpatched system limits its exposure so an attacker who exploits it cannot easily reach the rest of the network.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5568, 156, 'Which of the following is the best example of defense in depth?', 'A firewall, an intrusion detection system, host-based controls, and encryption used together', 'A single strong password', 'One antivirus product only', 'Relying on a single firewall rule', 'C', 'Defense in depth combines network, host, and data-layer controls so that multiple independent layers must be defeated.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5569, 156, 'What is the primary purpose of a risk register?', 'To document identified risks, their likelihood, impact, and treatment plans', 'To store backup tapes', 'To log every keystroke', 'To block phishing emails', 'D', 'A risk register is a central document that records each identified risk and how the organization plans to manage it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5570, 156, 'A data breach occurred because backups were stored in the same building as the servers. Which part of the CIA triad was most affected?', 'Availability', 'Confidentiality', 'Integrity', 'Non-repudiation', 'D', 'Storing backups in the same location as the servers means a single disaster destroys both, threatening availability of data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5571, 156, 'An organization must comply with GDPR while operating in a public cloud. Which design choice best supports data minimization and the right to erasure?', 'Storing only necessary personal data and designing deletion workflows', 'Storing all data forever for analysis', 'Copying data to many regions', 'Encrypting data with a lost key', 'A', 'Data minimization and deletion workflows ensure only required personal data is kept and can be removed on request.', 'ADVANCED', 3, 'MCQ', 1),
(5572, 156, 'An analyst values an asset at $500,000 with a 10% likelihood of loss in a year. What is the annualized loss expectancy (ALE)?', '$50,000', '$5,000', '$500,000', '$500,000,000', 'A', 'The ALE is calculated as the single loss expectancy multiplied by the annualized rate of occurrence, here $500,000 times 0.10 = $50,000.', 'ADVANCED', 3, 'MCQ', 1),
(5573, 156, 'Which approach best balances security and usability when implementing multi-factor authentication for a large workforce?', 'Phishing-resistant authenticators combined with self-service backup methods', 'Requiring only passwords', 'Using the same OTP for every site', 'Forcing everyone to carry hardware tokens with no recovery', 'A', 'Phishing-resistant authenticators with a practical recovery path provide strong security without making legitimate access impossible.', 'ADVANCED', 3, 'MCQ', 1),
(5574, 156, 'A zero-trust architecture differs from a traditional perimeter model primarily because it:', 'Assumes no implicit trust based on network location and verifies every request', 'Trusts anything inside the office network', 'Removes all authentication', 'Relies only on a VPN at the edge', 'B', 'Zero trust abandons the assumption that internal networks are safe and instead verifies every access request continuously.', 'ADVANCED', 3, 'MCQ', 1),
(5575, 156, 'Which statement best describes the shared responsibility model in cloud security?', 'The provider secures the infrastructure while the customer secures what they put in the cloud', 'The provider secures everything', 'The customer secures the physical datacenter', 'No party has any security responsibilities', 'B', 'Under the shared responsibility model, the provider protects the cloud itself while the customer protects workloads and data inside it.', 'ADVANCED', 3, 'MCQ', 1),
(5576, 156, 'Why might a security architect choose a fail-closed access control over fail-open?', 'To prevent unauthorized access when a control cannot verify a request', 'To maximize convenience for users', 'To reduce hardware costs', 'To avoid maintaining logs', 'B', 'Fail-closed denies access by default when verification fails, prioritizing confidentiality and security over convenience.', 'ADVANCED', 3, 'MCQ', 1),
(5577, 156, 'Which metric is most useful for measuring the effectiveness of a security awareness program?', 'The percentage of users who pass simulated phishing tests over time', 'The number of servers', 'The total network bandwidth', 'The company''s stock price', 'C', 'Tracking simulated phishing failure rates over time shows whether user awareness and behavior are actually improving.', 'ADVANCED', 3, 'MCQ', 1),
(5578, 156, 'When designing a business continuity plan, which sequence is most appropriate?', 'Identify critical assets, define RTO and RPO, test and rehearse', 'Test first, then define assets', 'Buy insurance before identifying assets', 'Document nothing until a disaster occurs', 'C', 'A sound plan first identifies what must be protected, sets recovery time and point objectives, and then validates through testing.', 'ADVANCED', 3, 'MCQ', 1),
(5579, 156, 'A threat actor targets the confidentiality of data in transit. Which control is designed to counter this specific threat?', 'Transport layer encryption such as TLS', 'Adding more RAM', 'Using a longer hostname', 'Defragmenting the disk', 'D', 'Transport layer encryption such as TLS protects data while it travels across the network from interception or tampering.', 'ADVANCED', 3, 'MCQ', 1),
(5580, 156, 'Which statement correctly describes the relationship between risk and security controls?', 'Controls are implemented to reduce residual risk to an acceptable level', 'Controls always eliminate all risk', 'Risk is independent of controls', 'Controls increase risk by adding complexity without benefit', 'D', 'Controls manage risk by reducing likelihood or impact, leaving a manageable residual risk rather than eliminating risk entirely.', 'ADVANCED', 3, 'MCQ', 1),
(5581, 157, 'What is phishing?', 'A social engineering attack that uses deceptive messages to trick victims into revealing information', 'A hardware failure', 'A type of encryption', 'A backup strategy', 'A', 'Phishing deceives users into divulging sensitive data such as passwords by sending messages that appear legitimate.', 'BEGINNER', 1, 'MCQ', 1),
(5582, 157, 'Which attack aims to make a service unavailable by overwhelming it with requests?', 'Denial-of-service', 'SQL injection', 'Phishing', 'Man-in-the-middle', 'A', 'A denial-of-service attack floods a service with traffic or requests until it can no longer respond to legitimate users.', 'BEGINNER', 1, 'MCQ', 1),
(5583, 157, 'What is a vulnerability in the context of cybersecurity?', 'A weakness that can be exploited to compromise a system', 'A type of firewall', 'A strong password', 'A backup tape', 'A', 'A vulnerability is a flaw or weakness in a system, process, or configuration that an attacker could exploit.', 'BEGINNER', 1, 'MCQ', 1),
(5584, 157, 'What is social engineering?', 'Manipulating people into performing actions or divulging information', 'Designing user interfaces', 'Compiling source code', 'Encoding data', 'B', 'Social engineering exploits human psychology rather than technical flaws to get people to reveal information or take harmful actions.', 'BEGINNER', 1, 'MCQ', 1),
(5585, 157, 'Which attack involves injecting malicious SQL code into an application query?', 'SQL injection', 'ARP poisoning', 'Smurf attack', 'Teardrop attack', 'B', 'SQL injection inserts malicious SQL into an application''s query so the database executes unintended commands.', 'BEGINNER', 1, 'MCQ', 1),
(5586, 157, 'What is an exploit?', 'Code or a technique that takes advantage of a vulnerability', 'A firewall rule', 'An encryption key', 'A type of backup', 'B', 'An exploit is a specific piece of code or method that leverages a vulnerability to compromise a system.', 'BEGINNER', 1, 'MCQ', 1),
(5587, 157, 'Which attack is performed from many compromised machines at once?', 'A distributed denial-of-service attack', 'A brute force attack on one host', 'A phishing email', 'A single packet sniffing session', 'C', 'A DDoS attack uses a large number of compromised devices to flood a target with traffic from many sources simultaneously.', 'BEGINNER', 1, 'MCQ', 1),
(5588, 157, 'What is a zero-day vulnerability?', 'A vulnerability unknown to the vendor with no available patch', 'A bug fixed on release day', 'A misconfigured server', 'An outdated firewall', 'C', 'A zero-day is a vulnerability that is exploited before the vendor knows about it or can issue a fix.', 'BEGINNER', 1, 'MCQ', 1),
(5589, 157, 'What is a botnet?', 'A collection of compromised computers controlled remotely by an attacker', 'A single infected laptop', 'A type of firewall', 'A wireless router', 'D', 'A botnet is a network of infected machines that an attacker controls remotely, often used to launch DDoS attacks.', 'BEGINNER', 1, 'MCQ', 1),
(5590, 157, 'Which type of attack secretly intercepts and relays communication between two parties?', 'Man-in-the-middle', 'Phishing', 'Spam', 'Key logging', 'D', 'A man-in-the-middle attack positions the attacker between two parties so they can read and alter the traffic.', 'BEGINNER', 1, 'MCQ', 1),
(5591, 157, 'An employee receives an email that appears to be from the CEO requesting urgent wire transfers. Which attack is this?', 'Business email compromise', 'A distributed denial-of-service', 'A man-in-the-middle', 'A port scan', 'A', 'Business email compromise impersonates a senior figure to trick staff into transferring money or data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5592, 157, 'A website stores passwords in plaintext and an attacker dumps the database. Which weakness was directly exploited?', 'The failure to hash stored passwords', 'The use of TLS', 'The length of the URL', 'The size of the database', 'A', 'Storing passwords as plaintext means a database breach instantly reveals every account''s password to the attacker.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5593, 157, 'An attacker changes a website''s DNS record so users reach a malicious copy. Which attack is this?', 'DNS hijacking', 'SQL injection', 'Phishing via SMS', 'Credential stuffing', 'A', 'DNS hijacking redirects users to a fake site by tampering with the DNS resolution records.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5594, 157, 'Which of the following is the best indicator that an email may be phishing?', 'The sender address differs slightly from the legitimate domain', 'The email is sent during business hours', 'The message contains a company logo', 'The email was received from a colleague', 'B', 'A sender address that differs subtly from the real domain, such as a misspelling, is a common sign of phishing.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5595, 157, 'An attacker submits more data than a buffer can hold to run malicious code. Which attack is this?', 'A buffer overflow', 'A ping sweep', 'A DNS spoof', 'A spear phishing email', 'B', 'A buffer overflow occurs when data written past a buffer''s boundary overwrites adjacent memory and can execute code.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5596, 157, 'Which activity best describes a threat hunter''s main task?', 'Proactively searching for signs of compromise in the environment', 'Installing new firewalls', 'Designing the company logo', 'Writing end-user documentation', 'B', 'Threat hunting actively looks for indicators of compromise that automated tools may have missed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5597, 157, 'A log review shows requests containing the string OR 1=1. Which attack was likely attempted?', 'SQL injection', 'A buffer overflow', 'A DDoS flood', 'A man-in-the-middle', 'C', 'SQL injection payloads often manipulate WHERE clauses with expressions such as OR 1=1 to bypass logic.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5598, 157, 'Which vulnerability class allows an attacker to inject scripts into web pages viewed by other users?', 'Cross-site scripting (XSS)', 'Denial of service', 'DNS hijacking', 'Physical tampering', 'C', 'XSS lets an attacker inject client-side scripts that run in the browser of other users who view the affected page.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5599, 157, 'An attacker exploits a flaw on one host and then uses that foothold to reach other systems. Which term describes this movement?', 'Lateral movement', 'Phishing', 'Egress filtering', 'Data minimization', 'D', 'Lateral movement is the technique of moving from one compromised system to others inside the network.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5600, 157, 'Which sequence best represents the phases of a typical cyber kill chain?', 'Reconnaissance, weaponization, delivery, exploitation, and command and control', 'Exploitation, patching, backup, recovery', 'Delivery, design, testing, launch', 'Coding, compiling, linking, executing', 'D', 'The cyber kill chain describes an attack as progressing through reconnaissance, weaponization, delivery, exploitation, and command and control.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5601, 157, 'A zero-day exploit is being used in the wild while no patch exists. Which response is most appropriate?', 'Deploy compensating controls such as behavior detection and network segmentation', 'Wait for the next software release', 'Disable all user accounts', 'Increase the password expiration period', 'A', 'Without a patch, compensating controls reduce exposure by detecting the exploit''s behavior and containing affected systems.', 'ADVANCED', 3, 'MCQ', 1),
(5602, 157, 'Which analysis technique examines the structure and behavior of a suspicious file without executing it?', 'Static analysis', 'Dynamic analysis', 'Fuzzing', 'Packet capture', 'A', 'Static analysis inspects a file''s structure, strings, and code without running it, avoiding the risk of infection.', 'ADVANCED', 3, 'MCQ', 1),
(5603, 157, 'An attacker uses a compromised account to gain domain admin rights. Which controls would most directly limit this?', 'Privileged access management and monitoring of high-privilege accounts', 'Shortening all passwords', 'Removing the firewall', 'Disabling audit logging', 'A', 'Managing and monitoring privileged accounts prevents attackers from silently gaining and abusing elevated rights.', 'ADVANCED', 3, 'MCQ', 1),
(5604, 157, 'Which best practice most reduces the impact of a credential-stuffing attack?', 'Enforcing unique passwords and enabling multi-factor authentication', 'Using the same password everywhere', 'Increasing login timeout', 'Deleting all user sessions hourly', 'B', 'Unique passwords stop reused credentials from working across sites, and MFA blocks even valid passwords from being used alone.', 'ADVANCED', 3, 'MCQ', 1),
(5605, 157, 'A threat actor profiles a target using publicly available information. Which phase of the attack lifecycle does this represent?', 'Reconnaissance', 'Exploitation', 'Installation', 'Action on objectives', 'B', 'Reconnaissance is the early phase where attackers gather public information about a target to plan the attack.', 'ADVANCED', 3, 'MCQ', 1),
(5606, 157, 'Which of the following is an example of a supply chain attack?', 'Compromising a software update to distribute malware to downstream customers', 'Phishing the CEO', 'Port scanning a website', 'Stealing a laptop', 'B', 'A supply chain attack infects a trusted vendor or product, then spreads to every customer who uses that software or update.', 'ADVANCED', 3, 'MCQ', 1),
(5607, 157, 'Which MITRE ATT&CK technique is commonly used by attackers to maintain persistence on a host?', 'Creating scheduled tasks or registry run keys', 'Changing the wallpaper', 'Defragmenting the disk', 'Renaming the computer', 'C', 'Scheduled tasks and run keys survive reboots and restart the malicious code automatically, providing persistence.', 'ADVANCED', 3, 'MCQ', 1),
(5608, 157, 'Which detection method is most effective against previously unknown malware?', 'Behavior-based detection and sandboxing', 'Signature matching only', 'Reading the file extension', 'Counting open ports', 'C', 'Behavior-based detection and sandboxing observe what code does rather than matching known signatures, catching novel threats.', 'ADVANCED', 3, 'MCQ', 1),
(5609, 157, 'An attacker encrypts files and demands payment. Which two terms best describe this incident?', 'Ransomware and extortion', 'Phishing and smishing', 'DoS and DDoS', 'Spoofing and sniffing', 'D', 'Ransomware encrypts victim files and the attacker extorts payment to decrypt them.', 'ADVANCED', 3, 'MCQ', 1),
(5610, 157, 'Which control is most effective at preventing lateral movement within a network?', 'Micro-segmentation combined with least privilege across segments', 'Removing antivirus', 'A single shared admin account', 'Allowing unrestricted internal traffic', 'D', 'Micro-segmentation splits the network into small zones and enforces least privilege, so a breach cannot easily spread.', 'ADVANCED', 3, 'MCQ', 1),
(5611, 158, 'What is authentication?', 'The process of verifying who a user is', 'The process of backing up data', 'The process of compressing files', 'The process of encrypting email', 'A', 'Authentication confirms a user''s identity by checking evidence such as passwords, tokens, or biometrics.', 'BEGINNER', 1, 'MCQ', 1),
(5612, 158, 'What is authorization?', 'Determining what actions an authenticated user may perform', 'Creating new user accounts', 'Renewing a TLS certificate', 'Scanning for malware', 'A', 'Authorization decides which resources and actions an authenticated identity is permitted to access.', 'BEGINNER', 1, 'MCQ', 1),
(5613, 158, 'What is multi-factor authentication?', 'Requiring two or more independent types of evidence to verify identity', 'Using one very long password', 'Logging in twice a day', 'Sharing passwords with coworkers', 'A', 'MFA requires evidence from two or more categories, such as knowledge, possession, and inherence, to verify identity.', 'BEGINNER', 1, 'MCQ', 1),
(5614, 158, 'Which of the following is an example of a strong password policy?', 'Long, unique, and unpredictable passphrases', 'Using your birth date', 'Reusing the same password for all sites', 'A four-digit PIN only', 'B', 'Long and unique passphrases resist guessing and cannot be reused across accounts.', 'BEGINNER', 1, 'MCQ', 1),
(5615, 158, 'A password is a factor belonging to which category?', 'Something you know', 'Something you have', 'Something you are', 'Somewhere you are', 'B', 'Knowledge factors such as passwords and PINs are classified as something the user knows.', 'BEGINNER', 1, 'MCQ', 1),
(5616, 158, 'A fingerprint scan is a factor belonging to which category?', 'Something you are', 'Something you know', 'Something you have', 'Something you remember', 'B', 'Biometrics such as fingerprints belong to the inherence category, described as something you are.', 'BEGINNER', 1, 'MCQ', 1),
(5617, 158, 'A hardware security key is a factor belonging to which category?', 'Something you have', 'Something you know', 'Something you are', 'Something you want', 'C', 'Physical devices such as security keys fall under the possession category, something you have.', 'BEGINNER', 1, 'MCQ', 1),
(5618, 158, 'What is single sign-on (SSO)?', 'Authenticating once to gain access to multiple related systems', 'Logging in with multiple passwords', 'Signing documents digitally', 'Sharing one account among users', 'C', 'SSO lets a user authenticate a single time and then access multiple systems without re-entering credentials.', 'BEGINNER', 1, 'MCQ', 1),
(5619, 158, 'What is an access control list (ACL)?', 'A list of permissions attached to a resource', 'A list of employees', 'A network diagram', 'A backup schedule', 'D', 'An ACL specifies which subjects can access a resource and what operations they are allowed to perform.', 'BEGINNER', 1, 'MCQ', 1),
(5620, 158, 'What is an identity provider (IdP)?', 'A service that authenticates users and issues identity assertions', 'A password manager', 'A hardware firewall', 'A load balancer', 'D', 'An identity provider verifies users and issues claims or tokens that other applications trust.', 'BEGINNER', 1, 'MCQ', 1),
(5621, 158, 'Which standard enables a user to log in to many sites using an existing identity such as Google or Microsoft?', 'OpenID Connect', 'FTP', 'SMTP', 'RDP', 'A', 'OpenID Connect builds on OAuth 2.0 to let relying parties verify a user''s identity through an external provider.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5622, 158, 'A user must enter a one-time code from a mobile app to log in. Which MFA factor does the phone app represent?', 'Something you have', 'Something you know', 'Something you are', 'Someone you trust', 'A', 'A code generated on a device the user possesses demonstrates the possession factor.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5623, 158, 'Which attack is most directly prevented by multi-factor authentication?', 'A stolen password being used alone to log in', 'A power outage', 'A slow network', 'Disk space exhaustion', 'A', 'Even if a password is stolen, MFA blocks login because the attacker does not possess the additional factor.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5624, 158, 'An employee is transferred between departments. Which IAM action must occur?', 'Update role memberships and adjust entitlements', 'Delete the employee''s records', 'Reboot the server', 'Change the department''s email domain', 'B', 'Role memberships and entitlements must be updated so the employee has access appropriate to the new department.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5625, 158, 'Which term describes periodically verifying that a user''s access is still needed?', 'Access recertification', 'Password rotation', 'Log retention', 'Traffic shaping', 'B', 'Access recertification reviews users and their entitlements to remove access that is no longer required.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5626, 158, 'After a successful login, which mechanism carries the user''s identity and attributes to the target application?', 'An identity token or assertion', 'A network cable', 'A MAC address', 'A cookie from the browser cache only', 'B', 'Tokens or assertions issued by the identity provider convey identity claims to the application after login.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5627, 158, 'What is the primary purpose of single sign-on in an enterprise?', 'To reduce password fatigue and centralize authentication', 'To encrypt all network traffic', 'To block phishing emails', 'To monitor disk usage', 'C', 'SSO centralizes authentication so users remember fewer credentials and the organization can enforce consistent policies.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5628, 158, 'Which concept requires two different people to be involved in approving a sensitive action?', 'Separation of duties', 'Single sign-on', 'Load balancing', 'Password hashing', 'C', 'Separation of duties spreads critical actions across multiple people to reduce fraud and accidental abuse.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5629, 158, 'Which IAM practice automatically removes accounts when employees leave the company?', 'Automated deprovisioning', 'Password expiration', 'Session pooling', 'Log archiving', 'D', 'Automated deprovisioning revokes an ex-employee''s accounts and entitlements promptly, preventing continued access.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5630, 158, 'What does a session token represent after a successful login?', 'Proof that the user was authenticated for the current session', 'The user''s home address', 'The server''s IP address', 'The user''s search history', 'D', 'A session token proves the user already authenticated and lets the application recognize them during the session.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5631, 158, 'Which scenario best demonstrates privilege escalation?', 'A standard user exploits a flaw to gain administrative rights', 'A user changes their own password', 'An admin installs a printer', 'A user views their own files', 'A', 'Privilege escalation occurs when an attacker or user obtains more privileges than they are entitled to.', 'ADVANCED', 3, 'MCQ', 1),
(5632, 158, 'When designing a role-based access control model, what is the correct first step?', 'Identify roles based on job functions, then assign permissions', 'Assign permissions randomly', 'Create every account as admin', 'Remove all access control', 'A', 'RBAC starts by defining roles from job functions and then grants each role the permissions its function needs.', 'ADVANCED', 3, 'MCQ', 1),
(5633, 158, 'Which attack involves using previously stolen username and password pairs against many websites?', 'Credential stuffing', 'Man-in-the-middle', 'DNS spoofing', 'Port scanning', 'A', 'Credential stuffing reuses leaked username and password combinations across many sites, exploiting password reuse.', 'ADVANCED', 3, 'MCQ', 1),
(5634, 158, 'Which MFA implementation is most resistant to phishing?', 'FIDO2/WebAuthn hardware authenticators', 'SMS one-time codes', 'Email one-time codes', 'Security questions', 'B', 'FIDO2/WebAuthn devices bind authentication to the specific site, so phishing sites cannot relay or replay the factor.', 'ADVANCED', 3, 'MCQ', 1),
(5635, 158, 'Which technique prevents password reuse across accounts while maintaining usability?', 'A password manager generating unique passwords', 'Using the same password everywhere', 'Writing passwords on sticky notes', 'Shortening passwords to save time', 'B', 'A password manager creates and stores a unique strong password per account, removing the need to remember each one.', 'ADVANCED', 3, 'MCQ', 1),
(5636, 158, 'In OAuth 2.0, what does the authorization code flow primarily protect against?', 'Exposing the access token to the browser and malicious scripts', 'Slow network latency', 'Disk corruption', 'CPU overheating', 'B', 'The authorization code flow keeps the access token away from the browser, so page scripts cannot steal it.', 'ADVANCED', 3, 'MCQ', 1),
(5637, 158, 'Which IAM design principle most reduces the blast radius of a compromised service account?', 'Scoping service accounts to least privilege and rotating their credentials', 'Giving service accounts full admin rights', 'Sharing one service account across all apps', 'Never rotating credentials', 'C', 'Least-privilege scoping limits what a stolen service account can do, and rotation shortens the window of misuse.', 'ADVANCED', 3, 'MCQ', 1),
(5638, 158, 'Which control prevents an attacker with a stolen admin session from acting indefinitely?', 'Session timeouts, reauthentication, and token revocation', 'Longer passwords', 'More memory', 'A larger monitor', 'C', 'Short session lifetimes, reauthentication, and revocation limit how long a stolen session token remains useful.', 'ADVANCED', 3, 'MCQ', 1),
(5639, 158, 'Which policy best enforces least privilege when granting cloud permissions?', 'Use fine-grained policies with a deny-by-default model', 'Grant every user full admin access', 'Allow all permissions to everyone', 'Use a single shared root account', 'D', 'Fine-grained, deny-by-default policies ensure users receive exactly the permissions required and nothing more.', 'ADVANCED', 3, 'MCQ', 1),
(5640, 158, 'Which approach correctly enforces separation of duties for wire transfers?', 'Require different users to initiate and approve each transfer', 'Let one person do both steps', 'Allow anyone to approve transfers', 'Remove the approval step entirely', 'D', 'Requiring different users for initiating and approving transfers prevents a single person from committing fraud.', 'ADVANCED', 3, 'MCQ', 1),
(5641, 159, 'What is malware?', 'Software designed to harm or exploit systems', 'A hardware upgrade', 'A backup utility', 'A network cable', 'A', 'Malware is any software intentionally created to damage, disrupt, or gain unauthorized access to systems.', 'BEGINNER', 1, 'MCQ', 1),
(5642, 159, 'What is a computer virus?', 'Malware that replicates by infecting files or programs', 'A self-replicating worm', 'A firewall rule', 'A type of encryption', 'A', 'A virus attaches itself to legitimate files or programs and spreads when those hosts are executed.', 'BEGINNER', 1, 'MCQ', 1),
(5643, 159, 'What is a worm?', 'Self-replicating malware that spreads without user action', 'A type of antivirus', 'A password cracker', 'A browser plugin', 'A', 'A worm replicates itself across networks automatically, without needing to attach to a host file or be opened.', 'BEGINNER', 1, 'MCQ', 1),
(5644, 159, 'What is ransomware?', 'Malware that encrypts files and demands payment', 'Software that blocks pop-ups', 'A type of firewall', 'A secure browser', 'B', 'Ransomware encrypts the victim''s data and demands a ransom payment to provide the decryption key.', 'BEGINNER', 1, 'MCQ', 1),
(5645, 159, 'What is a Trojan horse?', 'Malware disguised as legitimate software', 'A hardware keylogger', 'A router', 'An encryption algorithm', 'B', 'A Trojan disguises itself as a legitimate program to trick users into installing it, then performs malicious actions.', 'BEGINNER', 1, 'MCQ', 1),
(5646, 159, 'What is a rootkit?', 'Malware that hides its presence and allows continued access', 'An ad blocker', 'A packet filter', 'A disk defragmenter', 'B', 'A rootkit conceals its own presence and can grant attackers persistent privileged access to a system.', 'BEGINNER', 1, 'MCQ', 1),
(5647, 159, 'What is spyware?', 'Malware that secretly collects information about a user', 'A firewall', 'A VPN', 'A password manager', 'C', 'Spyware covertly monitors user activity and gathers information such as keystrokes and browsing habits.', 'BEGINNER', 1, 'MCQ', 1),
(5648, 159, 'What is adware?', 'Software that displays unwanted advertisements', 'A type of backup', 'A secure messaging app', 'An email filter', 'C', 'Adware bombards the user with unwanted ads and often tracks behavior to target those ads.', 'BEGINNER', 1, 'MCQ', 1),
(5649, 159, 'What is the main purpose of antivirus software?', 'To detect and remove malware', 'To speed up the CPU', 'To compress video files', 'To manage printers', 'D', 'Antivirus software scans for, detects, and removes malicious software to keep systems protected.', 'BEGINNER', 1, 'MCQ', 1),
(5650, 159, 'What is signature-based malware detection?', 'Matching files against a database of known malware patterns', 'Analyzing disk fragmentation', 'Measuring network speed', 'Monitoring battery life', 'D', 'Signature-based detection compares file content against a database of fingerprints of known malware.', 'BEGINNER', 1, 'MCQ', 1);
INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(5651, 159, 'Which malware type spreads automatically across a network without attaching to a host file?', 'A worm', 'A file infector virus', 'A logic bomb', 'A rootkit', 'A', 'Worms self-propagate over networks on their own, unlike viruses that require a host file or user action.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5652, 159, 'Which defense most reliably stops ransomware from encrypting backups?', 'Immutable or air-gapped backups', 'Longer filenames', 'A faster network card', 'More RAM', 'A', 'Immutable or air-gapped backups cannot be modified by ransomware, so data can always be restored.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5653, 159, 'A program hides deep in the operating system to evade detection and keep access open. Which malware is this?', 'A rootkit', 'Adware', 'A screen saver', 'A browser cookie', 'A', 'Rootkits operate at privileged levels of the OS to hide their presence and maintain attacker access.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5654, 159, 'Which technique do modern email gateways use to inspect suspicious attachments safely?', 'Sandboxing attachments in an isolated environment', 'Printing them for review', 'Renaming them', 'Deleting them instantly', 'B', 'Sandboxing executes attachments in an isolated environment to observe their behavior without risking the real network.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5655, 159, 'Which of the following is the most effective user-level defense against malware?', 'Regular patching combined with security awareness', 'Downloading software from any website', 'Disabling the firewall', 'Sharing passwords', 'B', 'Patching closes vulnerabilities that malware exploits, while awareness prevents users from falling for malicious downloads.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5656, 159, 'What does an endpoint detection and response (EDR) tool provide beyond traditional antivirus?', 'Continuous monitoring, behavioral analysis, and response capabilities', 'Faster internet', 'Better graphics', 'More storage', 'B', 'EDR continuously monitors endpoints, analyzes behavior, and enables investigation and response beyond signature scanning.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5657, 159, 'Which behavior strongly suggests a host is part of a botnet?', 'Frequent outbound connections to a known command-and-control server', 'A fast login screen', 'Low CPU usage', 'A quiet fan', 'C', 'Regular connections to a command-and-control server are a hallmark of a machine participating in a botnet.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5658, 159, 'Which defense is most effective against fileless attacks that run in memory?', 'Application whitelisting and monitoring of scripting engines', 'Signature scanning of files on disk', 'Defragmenting the disk', 'Increasing swap space', 'C', 'Fileless attacks leave no malicious file on disk, so allowlisting applications and monitoring script hosts stop them.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5659, 159, 'Which step is the highest priority when responding to a ransomware infection?', 'Isolate affected hosts from the network', 'Format the hard drive', 'Email all employees', 'Install a new browser', 'D', 'Isolating infected hosts immediately limits how far the ransomware can spread to other systems and data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5660, 159, 'Which technique limits what fileless malware can do through PowerShell?', 'Restricting and logging PowerShell with Constrained Language Mode', 'Deleting PowerShell', 'Granting all users admin rights', 'Disabling the firewall', 'D', 'Constrained Language Mode restricts PowerShell capabilities and logging reveals malicious usage, hampering fileless attacks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5661, 159, 'Which of the following best describes a polymorphic virus?', 'Malware that changes its code signature on every infection to evade detection', 'A virus that never changes', 'A virus that deletes itself', 'A virus that only targets printers', 'A', 'Polymorphic viruses mutate their code with each infection so signature-based detection cannot match them.', 'ADVANCED', 3, 'MCQ', 1),
(5662, 159, 'Which analysis technique runs a suspicious binary in an isolated virtual machine to observe its behavior?', 'Dynamic analysis', 'Static analysis', 'String extraction', 'File renaming', 'A', 'Dynamic analysis executes the sample in a controlled sandbox and records its runtime behavior safely.', 'ADVANCED', 3, 'MCQ', 1),
(5663, 159, 'When building a malware defense strategy, which order best reduces exposure?', 'Patch assets, restrict admin rights, enable application allowlisting, and deploy EDR', 'Deploy EDR last after all malware is present', 'Disable updates first', 'Remove all security tools', 'A', 'Patching and limiting privileges close the main infection routes before detection tools add visibility and response.', 'ADVANCED', 3, 'MCQ', 1),
(5664, 159, 'Which of the following is the strongest evidence that a machine is compromised?', 'A normal process spawning cmd or PowerShell and making network connections', 'A blue desktop wallpaper', 'Low disk usage', 'A recent reboot', 'B', 'Legitimate processes spawning command shells with network activity is a strong indicator of malicious code running.', 'ADVANCED', 3, 'MCQ', 1),
(5665, 159, 'Why is memory forensics important when analyzing an unknown malware sample?', 'It can reveal code and data that never touch the disk, such as decrypted payloads and injected code', 'It is the only way to defragment the hard drive', 'It speeds up the infected computer', 'It replaces the need for network and host logs', 'A', 'Memory forensics inspects a RAM image to recover artifacts like injected code, decrypted payloads, and running process details that never reach the disk.', 'ADVANCED', 3, 'MCQ', 1),
(5666, 159, 'Which technique prevents macro-based malware in Office documents?', 'Blocking macros from running unless signed by a trusted publisher', 'Opening all documents in full screen', 'Storing documents in the cloud', 'Naming documents with .txt extensions', 'B', 'Restricting macros to trusted signed publishers stops macro malware that arrives in ordinary Office files.', 'ADVANCED', 3, 'MCQ', 1),
(5667, 159, 'Which defense most effectively limits damage from a brand-new ransomware strain?', 'Robust offline backups and endpoint isolation capabilities', 'A single antivirus signature', 'Slower internet', 'More monitors', 'C', 'Offline backups let you restore data after encryption, and isolation stops the strain from spreading.', 'ADVANCED', 3, 'MCQ', 1),
(5668, 159, 'In an incident response for a Trojan downloader, which action should come last?', 'Restore from clean backups after containment and eradication', 'Isolate the host', 'Collect forensic evidence', 'Disconnect from the network', 'C', 'Recovery and restoration happen only after the malware is contained, evidence is collected, and it is eradicated.', 'ADVANCED', 3, 'MCQ', 1),
(5669, 159, 'Which detection method is best suited to stop a zero-day exploit chain?', 'Behavioral monitoring and exploit mitigation', 'Updating signatures hourly', 'Scanning filenames', 'Counting running services', 'D', 'Behavioral monitoring and exploit mitigations catch novel attack techniques that signatures cannot identify.', 'ADVANCED', 3, 'MCQ', 1),
(5670, 159, 'Which of these is a characteristic of a true fileless attack?', 'No malicious executable is written to disk; it runs in memory', 'A large virus file is dropped to disk', 'It only spreads by USB', 'It requires administrator installation', 'D', 'Fileless attacks execute directly in memory, leaving little or no trace on disk for signature scanners to find.', 'ADVANCED', 3, 'MCQ', 1),
(5671, 160, 'What is an IT security audit?', 'A systematic review of security controls and compliance', 'A hardware upgrade', 'A marketing campaign', 'A backup rotation', 'A', 'A security audit evaluates whether an organization''s controls, policies, and practices meet requirements.', 'BEGINNER', 1, 'MCQ', 1),
(5672, 160, 'What does compliance mean in cybersecurity?', 'Meeting the laws, regulations, and policies that apply to the organization', 'Avoiding all software updates', 'Using stronger passwords', 'Deleting old logs', 'A', 'Compliance means the organization satisfies the legal, regulatory, and internal security requirements that govern it.', 'BEGINNER', 1, 'MCQ', 1),
(5673, 160, 'What does GDPR primarily regulate?', 'The processing of personal data of individuals in the EU', 'Network cable standards', 'Server room temperature', 'Email server capacity', 'A', 'The General Data Protection Regulation governs how organizations collect, store, and process EU residents'' personal data.', 'BEGINNER', 1, 'MCQ', 1),
(5674, 160, 'What is the purpose of an audit trail?', 'To record who did what and when for accountability', 'To increase internet speed', 'To compress files', 'To block ads', 'B', 'An audit trail provides a chronological record of actions and events so activity can be reviewed and traced.', 'BEGINNER', 1, 'MCQ', 1),
(5675, 160, 'What does HIPAA regulate?', 'The protection of health information in the US', 'Credit card fees', 'Cloud storage pricing', 'Email spam filters', 'B', 'HIPAA establishes requirements for protecting the privacy and security of protected health information in the US.', 'BEGINNER', 1, 'MCQ', 1),
(5676, 160, 'What does PCI DSS govern?', 'The security of cardholder data', 'Server cooling', 'Network cabling', 'Software licensing', 'B', 'The Payment Card Industry Data Security Standard mandates controls for any organization handling cardholder data.', 'BEGINNER', 1, 'MCQ', 1),
(5677, 160, 'What is an audit log?', 'A chronological record of events generated by a system', 'A list of employee names', 'A backup tape', 'A firewall rule', 'C', 'An audit log captures events such as logins, changes, and errors so they can be reviewed later.', 'BEGINNER', 1, 'MCQ', 1),
(5678, 160, 'What does SOX require of public companies?', 'Internal controls over financial reporting', 'Faster backups', 'More employees', 'Shorter passwords', 'C', 'The Sarbanes-Oxley Act requires public companies to establish and maintain effective internal controls over financial reporting.', 'BEGINNER', 1, 'MCQ', 1),
(5679, 160, 'What is a risk assessment?', 'The process of identifying and evaluating risks to the organization', 'A performance review', 'A software install', 'A marketing survey', 'D', 'A risk assessment identifies threats and vulnerabilities and evaluates the likelihood and impact of losses.', 'BEGINNER', 1, 'MCQ', 1),
(5680, 160, 'What does ISO/IEC 27001 specify?', 'Requirements for an information security management system', 'Physical office layouts', 'Recruitment policies', 'Product packaging', 'D', 'ISO/IEC 27001 defines the requirements for establishing, operating, and improving an ISMS.', 'BEGINNER', 1, 'MCQ', 1),
(5681, 160, 'Which audit activity verifies that actual controls match documented policies?', 'Control testing', 'Password resets', 'Server reboots', 'Software installation', 'A', 'Control testing checks that the controls described in policy are actually implemented and working as intended.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5682, 160, 'Which regulation most directly affects how a company stores European customers'' personal data?', 'GDPR', 'HIPAA', 'SOX', 'PCI DSS', 'A', 'GDPR applies to the processing of personal data of EU individuals regardless of where the company is located.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5683, 160, 'Which document defines the rules employees must follow regarding information security?', 'The security policy', 'The marketing plan', 'The employee directory', 'The product roadmap', 'A', 'The security policy sets out the expectations and rules for how information and systems must be protected.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5684, 160, 'Which of the following is an example of an audit finding?', 'A server running unsupported software with known vulnerabilities', 'A printer running low on ink', 'A bright office', 'A fast network', 'B', 'An audit finding is a discovered issue such as unsupported software that must be corrected.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5685, 160, 'Which standard is best suited to certify an organization''s information security management system?', 'ISO/IEC 27001', 'IEEE 802.11', 'RFC 791', 'HTML5', 'B', 'ISO/IEC 27001 is the internationally recognized certification standard for information security management systems.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5686, 160, 'What is the difference between a vulnerability scan and a penetration test?', 'A scan identifies known weaknesses while a pen test actively exploits them to assess real impact', 'They are identical', 'A pen test is faster than a scan', 'A scan requires physical access', 'B', 'Vulnerability scanning finds potential weaknesses, while penetration testing attempts to exploit them to prove impact.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5687, 160, 'Which audit evidence is most reliable?', 'Raw logs with verifiable timestamps generated by the system', 'A colleague''s memory', 'A verbal promise', 'An untracked spreadsheet', 'C', 'System-generated logs with verifiable timestamps are reliable, tamper-evident evidence for an audit.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5688, 160, 'Which control would an auditor most likely expect for handling cardholder data?', 'Encrypting stored card data and restricting access', 'Printing card numbers', 'Posting card numbers on the wall', 'Using no passwords', 'C', 'PCI DSS requires stored cardholder data to be encrypted and access to it restricted to authorized personnel.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5689, 160, 'Which activity is required for ongoing compliance rather than a one-time project?', 'Continuous monitoring and periodic reviews', 'A single annual meeting', 'One-time software purchase', 'A single password reset', 'D', 'Compliance is maintained through continuous monitoring, recurring reviews, and ongoing remediation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5690, 160, 'Which regulation grants individuals the right to request deletion of their personal data?', 'GDPR''s right to erasure', 'SOX', 'PCI DSS', 'HIPAA''s billing rules', 'D', 'Under GDPR, individuals can request that organizations erase their personal data, subject to legal limits.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5691, 160, 'Which of the following best describes a material control deficiency found during an audit?', 'A significant weakness that could allow a material misstatement or serious security failure', 'A typo in a document', 'A slow printer', 'A minor cosmetic issue', 'A', 'A material deficiency is serious enough that it could lead to a significant misstatement or unacceptable security risk.', 'ADVANCED', 3, 'MCQ', 1),
(5692, 160, 'During a penetration test, the client asks the tester to expand scope to the production billing system. What should the tester do first?', 'Confirm the scope change and obtain written authorization before proceeding', 'Attack it immediately', 'Refuse without discussing', 'Ignore the request', 'A', 'Expanding scope requires explicit written authorization so testing stays legal and within agreed boundaries.', 'ADVANCED', 3, 'MCQ', 1),
(5693, 160, 'Which practice best demonstrates evidence of compliance with ISO/IEC 27001?', 'Maintaining documented policies, controls, and audit records reviewed regularly', 'Keeping no documentation', 'Deleting all logs monthly', 'Relying on verbal assurances', 'A', 'ISO/IEC 27001 requires documented policies, implemented controls, and records that prove continuous compliance.', 'ADVANCED', 3, 'MCQ', 1),
(5694, 160, 'Which control best demonstrates that an organization can prove accountability for user actions?', 'Centralized logging with tamper-evident audit trails', 'Deleting logs after a day', 'Sharing accounts among staff', 'Disabling access logs', 'B', 'Tamper-evident, centralized audit trails show exactly who did what, which is essential for accountability.', 'ADVANCED', 3, 'MCQ', 1),
(5695, 160, 'An auditor finds that security patches are applied inconsistently. Which recommendation is most appropriate?', 'Implement a formal patch management program with SLAs and verification', 'Ignore the finding', 'Apply patches only when convenient', 'Disable all updates', 'B', 'A formal patch management program with defined timelines and verification ensures vulnerabilities are fixed consistently.', 'ADVANCED', 3, 'MCQ', 1),
(5696, 160, 'Which GDPR principle is directly supported by encrypting and pseudonymizing personal data?', 'Security of processing, also known as integrity and confidentiality', 'Data portability', 'Storage minimization only', 'Transparency only', 'B', 'Encryption and pseudonymization are technical measures that protect personal data, fulfilling the security-of-processing principle.', 'ADVANCED', 3, 'MCQ', 1),
(5697, 160, 'Which approach best prepares an organization for an external compliance audit?', 'Maintain evidence of continuous monitoring, documented policies, and periodic internal audits', 'Hide all records', 'Delay until the auditor arrives', 'Conduct the audit for them', 'C', 'Continuous monitoring, current documentation, and internal audits build the evidence an external auditor expects to see.', 'ADVANCED', 3, 'MCQ', 1),
(5698, 160, 'In a red team exercise, which outcome provides the most value to an organization?', 'Validated detection and response effectiveness against realistic attack paths', 'A list of employee salaries', 'A faster network', 'A new logo', 'C', 'A red team validates how well defenders detect and respond to realistic attacks, driving real security improvement.', 'ADVANCED', 3, 'MCQ', 1),
(5699, 160, 'Which of the following is the correct order for a typical internal audit?', 'Plan, gather evidence, test controls, report findings, track remediation', 'Report, plan, test, gather, remediate', 'Remediate, plan, report, test, gather', 'Test, remediate, plan, gather, report', 'D', 'An internal audit moves from planning through evidence collection, control testing, reporting, and finally remediation tracking.', 'ADVANCED', 3, 'MCQ', 1),
(5700, 160, 'Which statement about audit logs and legal requirements is correct?', 'Logs supporting compliance must be retained for the period defined by relevant regulations and standards', 'Logs should be deleted immediately', 'Log retention is always one day', 'Logs are never required by law', 'D', 'Regulations such as PCI DSS and GDPR require retaining audit logs for defined periods to support investigations and compliance.', 'ADVANCED', 3, 'MCQ', 1),
(5701, 161, 'What does the acronym CI stand for in DevOps?', 'Continuous Integration', 'Central Information', 'Code Interface', 'Continuous Inference', 'A', 'CI refers to Continuous Integration, the practice of automatically merging and testing code changes frequently.', 'BEGINNER', 1, 'MCQ', 1),
(5702, 161, 'What does the acronym CD stand for in the CI/CD pipeline?', 'Continuous Deployment', 'Code Delivery', 'Central Deployment', 'Continuous Debugging', 'B', 'CD stands for Continuous Deployment (or Continuous Delivery), the automated release of validated code.', 'BEGINNER', 1, 'MCQ', 1),
(5703, 161, 'What is the primary goal of a DevOps culture?', 'reducing collaboration between teams', 'breaking silos between development and operations teams', 'eliminating all testing', 'removing version control', 'C', 'DevOps aims to break down silos and promote collaboration between development and operations teams.', 'BEGINNER', 1, 'MCQ', 1),
(5704, 161, 'What is the main benefit of automated testing in a CI/CD pipeline?', 'It catches defects early before they reach production', 'It removes the need for version control', 'It slows down the build process', 'It replaces the developer''s work entirely', 'A', 'Automated testing runs every time code changes, so defects are found quickly and inexpensively before a release.', 'BEGINNER', 1, 'MCQ', 1),
(5705, 161, 'What is the main purpose of a version control system?', 'tracking changes to files over time', 'compiling source code', 'deploying applications', 'writing documentation', 'A', 'A version control system records changes to files, allowing history tracking and collaboration.', 'BEGINNER', 1, 'MCQ', 1),
(5706, 161, 'What does the term pipeline refer to in DevOps?', 'the sequence of automated steps from code commit to deployment', 'a network cable', 'a database schema', 'a chat channel', 'B', 'A pipeline is the automated sequence of stages such as build, test and deploy that code passes through.', 'BEGINNER', 1, 'MCQ', 1),
(5707, 161, 'Which practice involves automatically building and testing every change pushed to a shared repository?', 'manual deployment', 'continuous integration', 'code review only', 'scheduled maintenance', 'C', 'Continuous integration automatically builds and tests each change merged into the shared repository.', 'BEGINNER', 1, 'MCQ', 1),
(5708, 161, 'Which environment is typically used for running automated integration tests?', 'staging environment', 'production environment', 'a test or staging environment isolated from production', 'the developer laptop only', 'D', 'Integration tests run in dedicated test or staging environments that mirror production but are isolated from it.', 'BEGINNER', 1, 'MCQ', 1),
(5709, 161, 'What is infrastructure as code (IaC)?', 'writing hardware specifications', 'managing infrastructure through machine-readable definition files', 'physically installing servers', 'using a spreadsheet to track servers', 'A', 'Infrastructure as code provisions and manages infrastructure through declarative, version-controlled definition files.', 'BEGINNER', 1, 'MCQ', 1),
(5710, 161, 'Which of the following is a core DevOps principle?', 'automation of repetitive tasks', 'manual error-prone deployments', 'avoiding monitoring', 'discouraging feedback', 'B', 'Automating repetitive tasks is a core DevOps principle that improves speed, consistency and reliability.', 'BEGINNER', 1, 'MCQ', 1),
(5711, 161, 'A developer pushes a change to the main branch. In a proper CI setup, what should happen automatically?', 'the code is merged into production instantly', 'the change triggers an automated build and test run', 'the change is ignored until the next release', 'the developer must manually compile it', 'A', 'In CI, every push to the shared branch automatically triggers a build and test run to catch problems early.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5712, 161, 'Which stage in a typical CI/CD pipeline catches coding mistakes before deployment?', 'automated testing', 'user acceptance testing only', 'manual release notes', 'database backup', 'B', 'Automated tests run early in the pipeline to detect defects before the code moves toward deployment.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5713, 161, 'What is the main difference between continuous delivery and continuous deployment?', 'deployment to production is fully automated in continuous deployment', 'continuous delivery removes all tests', 'continuous deployment uses no pipeline', 'they are exactly the same thing', 'C', 'Continuous delivery stops at a deployable artifact awaiting a manual release, while continuous deployment pushes every change to production automatically.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5714, 161, 'A build fails in the pipeline. What is the correct response under a DevOps philosophy?', 'the team stops committing to the branch', 'the team fixes the failing build as a priority', 'the failure is ignored for a week', 'the test is deleted from the suite', 'D', 'Fixing the failing build as a priority keeps the main branch green and prevents cascading integration problems.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5715, 161, 'Which of the following best describes a blue-green deployment?', 'two identical environments, one active and one idle, enabling instant rollback', 'painting the servers blue', 'deploying only at night', 'a single environment with no backup', 'A', 'Blue-green deployment runs two identical environments and switches traffic between them for zero-downtime rollback.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5716, 161, 'What is the purpose of a rollback strategy in a deployment pipeline?', 'to revert to the previous known-good version if a release fails', 'to permanently erase old versions', 'to speed up the build', 'to delete the logs', 'B', 'A rollback strategy lets the team quickly restore the previous stable version when a release introduces problems.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5717, 161, 'Why is it important to keep the CI build fast?', 'slow builds discourage frequent integration and delay feedback', 'fast builds consume more electricity', 'fast builds skip testing', 'slow builds are more reliable', 'C', 'A fast build provides quick feedback, encouraging developers to integrate small changes frequently.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5718, 161, 'Which artifact is typically produced by a build stage in CI?', 'a compiled, versioned artifact ready for release', 'a list of users', 'a backup tape', 'a marketing plan', 'D', 'The build stage produces a compiled, versioned artifact that downstream stages can test and deploy.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5719, 161, 'What is a feature flag used for in continuous delivery?', 'toggling features on or off at runtime without redeploying', 'flagging files as read-only', 'highlighting bugs in the IDE', 'naming release branches', 'A', 'Feature flags allow features to be enabled or disabled at runtime, enabling safe progressive rollouts.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5720, 161, 'Which metric best indicates how quickly a change reaches production?', 'deployment frequency', 'the number of coffee breaks', 'the size of the codebase', 'the age of the servers', 'B', 'Deployment frequency measures how often changes are released, a key DevOps delivery metric.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5721, 161, 'A team wants zero-downtime releases for a web service. Which deployment strategy best supports this while allowing instant rollback?', 'a rolling deployment with canary analysis', 'replacing the production server without backups', 'deploying directly over the live server', 'shutting down the service during release', 'A', 'A rolling deployment updates instances gradually, and canary analysis lets traffic shift only while metrics look healthy.', 'ADVANCED', 3, 'MCQ', 1),
(5722, 161, 'Which property makes a CI/CD pipeline most resilient to a failing stage?', 'each stage is idempotent and can be re-run safely', 'stages depend on manual steps', 'the pipeline deletes artifacts on failure', 'stages never produce logs', 'B', 'Idempotent stages that can be safely re-run let teams recover from failures without manual cleanup or rework.', 'ADVANCED', 3, 'MCQ', 1),
(5723, 161, 'A developer commits frequently but the team only integrates with the main branch every month. What problem does this cause?', 'integration conflicts and late discovery of defects', 'faster deployments', 'cleaner commit history', 'fewer build failures', 'C', 'Rare integration causes merge conflicts and delays discovery of integration defects, violating CI best practice.', 'ADVANCED', 3, 'MCQ', 1),
(5724, 161, 'In a shift-left testing strategy, what is the emphasis?', 'catching defects as early as possible in the development lifecycle', 'testing only in production', 'postponing all tests', 'relying solely on manual QA', 'D', 'Shift-left testing moves testing earlier in the lifecycle so defects are found and fixed cheaply.', 'ADVANCED', 3, 'MCQ', 1),
(5725, 161, 'Which approach describes a canary release?', 'rolling out a new version to a small subset of users before full rollout', 'deploying the new version to everyone at once', 'keeping two permanent versions forever', 'releasing only the documentation', 'A', 'A canary release routes a small percentage of traffic to the new version first and expands it as confidence grows.', 'ADVANCED', 3, 'MCQ', 1),
(5726, 161, 'Why is treating servers as cattle rather than pets important in DevOps?', 'servers should be disposable and easily replaced, not hand-configured and irreplaceable', 'cattle are more reliable than servers', 'it reduces the need for automation', 'it makes servers slower', 'B', 'Treating servers as cattle means they are reproducible and disposable, so any instance can be replaced automatically.', 'ADVANCED', 3, 'MCQ', 1),
(5727, 161, 'Which SRE-style SLO consideration is most appropriate for a mission-critical API?', 'an error budget based on a measurable availability target such as 99.9 percent', 'a guarantee of zero downtime with no measurement', 'measuring only the uptime of the marketing site', 'tracking only developer happiness', 'C', 'An SLO defines a quantifiable availability target, and the error budget guides how much unreliability is acceptable.', 'ADVANCED', 3, 'MCQ', 1),
(5728, 161, 'A security check in the CI/CD pipeline reports a vulnerable dependency. What is the correct action?', 'fail the build and require the dependency to be patched before release', 'ship it and fix it later', 'delete the dependency check', 'ignore the warning', 'D', 'A security gate should fail the build so vulnerable dependencies are patched before code reaches production.', 'ADVANCED', 3, 'MCQ', 1),
(5729, 161, 'Which workflow best supports trunk-based development?', 'short-lived feature branches merged into main frequently', 'long-lived branches that never merge', 'one giant release branch per year', 'no branch merging at all', 'A', 'Trunk-based development keeps feature branches short-lived and merges them to main frequently to reduce conflict.', 'ADVANCED', 3, 'MCQ', 1),
(5730, 161, 'Why should deployment credentials be stored in a secrets manager rather than in the repository?', 'committing secrets exposes them to anyone with repository access and increases breach risk', 'secrets are easier to type this way', 'repositories cannot store files', 'it makes builds slower', 'B', 'Storing credentials in a secrets manager keeps them out of version control and restricts access at runtime.', 'ADVANCED', 3, 'MCQ', 1),
(5731, 162, 'Which command creates a new Git repository in the current directory?', 'git init', 'git start', 'git new', 'git create', 'A', 'git init initializes a new Git repository in the current directory.', 'BEGINNER', 1, 'MCQ', 1),
(5732, 162, 'Which command stages changes to be committed?', 'git commit', 'git add', 'git push', 'git status', 'B', 'git add stages changes, moving them into the index so they can be committed.', 'BEGINNER', 1, 'MCQ', 1),
(5733, 162, 'Which command records staged changes into the repository history?', 'git add', 'git push', 'git commit', 'git log', 'C', 'git commit captures the staged changes with a message, creating a permanent entry in history.', 'BEGINNER', 1, 'MCQ', 1),
(5734, 162, 'Which command uploads local commits to a remote repository?', 'git pull', 'git fetch', 'git push', 'git clone', 'D', 'git push transfers local commits to the configured remote repository.', 'BEGINNER', 1, 'MCQ', 1),
(5735, 162, 'What is the default name of the first branch in Git?', 'master', 'dev', 'test', 'feature', 'A', 'Git historically names the default branch master, though main is now also common.', 'BEGINNER', 1, 'MCQ', 1),
(5736, 162, 'Which command shows the working directory and staged changes status?', 'git status', 'git diff', 'git branch', 'git stash', 'B', 'git status displays which files are modified, staged or untracked.', 'BEGINNER', 1, 'MCQ', 1),
(5737, 162, 'What does git clone do?', 'copies a repository into a new local directory', 'deletes a repository', 'merges two branches', 'creates a commit', 'C', 'git clone downloads a full copy of a repository, including its history, into a new directory.', 'BEGINNER', 1, 'MCQ', 1),
(5738, 162, 'Which command fetches and merges changes from the remote into the current branch?', 'git pull', 'git push', 'git add', 'git commit', 'D', 'git pull fetches remote changes and merges them into the current branch.', 'BEGINNER', 1, 'MCQ', 1),
(5739, 162, 'How do you view the commit history in Git?', 'git log', 'git add', 'git init', 'git remote', 'A', 'git log lists the commit history in reverse chronological order.', 'BEGINNER', 1, 'MCQ', 1),
(5740, 162, 'What is a commit in Git?', 'a snapshot of the project at a point in time', 'a deleted file', 'a network request', 'a configuration file', 'B', 'A commit is a snapshot of the tracked files, saved with metadata such as the author and message.', 'BEGINNER', 1, 'MCQ', 1),
(5741, 162, 'After git add app.py, which command records the staged change with the message adding login?', 'git commit -m ''adding login''', 'git push -m ''adding login''', 'git save -m ''adding login''', 'git branch -m ''adding login''', 'A', 'git commit -m records the staged change with the given message in one command.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5742, 162, 'What is the main difference between git merge and git rebase?', 'merge preserves a merge commit; rebase rewrites history by replaying commits', 'merge deletes the branch', 'rebase cannot be undone', 'merge only works offline', 'B', 'git merge creates a merge commit joining histories, while git rebase replays commits onto another base.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5743, 162, 'You started editing config.py, but want to discard the changes. Which command restores it?', 'git checkout -- config.py', 'git commit config.py', 'git push config.py', 'git add config.py', 'C', 'git checkout -- restores the working file to its last committed state, discarding uncommitted edits.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5744, 162, 'Which command creates a new branch named feature and switches to it immediately?', 'git checkout -b feature', 'git branch -d feature', 'git commit -b feature', 'git merge feature', 'D', 'git checkout -b both creates the branch and checks it out in a single step.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5745, 162, 'Two developers both modify the same line and then try to merge. What is the result?', 'a merge conflict', 'the merge always succeeds', 'the file is deleted', 'Git refuses to push forever', 'A', 'Conflicting changes to the same line produce a merge conflict that must be resolved manually.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5746, 162, 'What is the purpose of git stash?', 'saving uncommitted changes temporarily so you can switch work', 'deleting the repository', 'creating a backup server', 'listing remote branches', 'B', 'git stash saves uncommitted changes aside and restores a clean working directory for another task.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5747, 162, 'Which command shows the differences between the working directory and the last commit?', 'git diff', 'git status', 'git add', 'git log', 'C', 'git diff without arguments shows unstaged changes between the working tree and the index.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5748, 162, 'What does git revert HEAD do?', 'creates a new commit that undoes the last commit''s changes', 'deletes the last commit from history', 'rebases the branch', 'pushes the branch', 'D', 'git revert creates a new commit that reverses the changes of the specified commit, preserving history.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5749, 162, 'Which command permanently removes a branch called old-feature?', 'git branch -d old-feature', 'git stash old-feature', 'git log old-feature', 'git fetch old-feature', 'A', 'git branch -d deletes a branch once it has been merged, while -D forces deletion.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5750, 162, 'Which command downloads remote commits into a local tracking branch without merging?', 'git fetch', 'git pull', 'git push', 'git commit', 'B', 'git fetch downloads remote refs and objects but does not merge them into the working branch.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5751, 162, 'A hotfix branch must be based on a released commit that is several commits behind main. Which approach cleanly brings it up to date?', 'git checkout hotfix; git rebase main', 'git push hotfix --force', 'git stash and drop the branch', 'git revert main', 'A', 'Rebasing the hotfix branch onto main replays its commits on top of the latest main for a linear history.', 'ADVANCED', 3, 'MCQ', 1),
(5752, 162, 'A developer pushed a commit containing a secret. What is the safest way to remove it from history?', 'rotate the secret and rewrite history with git filter-repo or filter-branch', 'delete the file locally and commit', 'rename the commit message', 'leave the secret in the history', 'B', 'The exposed secret must be revoked, and history should be rewritten to purge it from all commits.', 'ADVANCED', 3, 'MCQ', 1),
(5753, 162, 'Which situation makes a force push to a shared branch most dangerous?', 'it overwrites commits that other developers may already have', 'it is always harmless', 'it deletes local files', 'it slows the network', 'C', 'Force pushing replaces remote commits, discarding work others may have based on those commits.', 'ADVANCED', 3, 'MCQ', 1),
(5754, 162, 'What is the recommended approach when resolving a merge conflict in a shared feature branch?', 'commit the resolved files, then continue and merge', 'delete the conflicting files', 'force push before merging', 'ignore the conflict and push', 'D', 'The correct flow is to edit the conflicting files, mark them resolved, commit, and then complete the merge.', 'ADVANCED', 3, 'MCQ', 1),
(5755, 162, 'Which Git feature allows several commits on a feature branch to be squashed into one before merging?', 'git rebase -i', 'git status', 'git stash', 'git clone', 'A', 'git rebase -i (interactive) can squash, reorder and edit commits before they are merged.', 'ADVANCED', 3, 'MCQ', 1),
(5756, 162, 'In which scenario is cherry-picking a commit appropriate?', 'applying a specific commit''s change to a different branch', 'deleting all branches', 'renaming a repository', 'compressing the working tree', 'B', 'git cherry-pick applies a single commit''s change to the current branch, useful when the full merge is not wanted.', 'ADVANCED', 3, 'MCQ', 1),
(5757, 162, 'A pull request shows merge conflicts on the target branch. What is the correct first step?', 'merge or rebase the latest target branch into the feature branch', 'force push the feature branch', 'delete the target branch', 'ignore the conflicts', 'C', 'Bringing the feature branch up to date with the target branch resolves most conflicts before review.', 'ADVANCED', 3, 'MCQ', 1),
(5758, 162, 'Which practice best protects the main branch in a team repository?', 'requiring pull request reviews and passing CI before merge', 'allowing direct pushes without review', 'merging untested code', 'disabling branch protection', 'D', 'Branch protection rules that require reviews and green CI prevent broken or unreviewed code from reaching main.', 'ADVANCED', 3, 'MCQ', 1),
(5759, 162, 'Why is amending a commit that has already been pushed to a shared branch problematic?', 'rewriting the pushed commit changes history for all collaborators', 'it deletes the repository', 'it slows down cloning', 'it is perfectly safe always', 'A', 'Amending rewrites the commit, so anyone who already pulled the old version has diverged history.', 'ADVANCED', 3, 'MCQ', 1),
(5760, 162, 'To trace which commit introduced a regression, which Git command is most useful?', 'git bisect', 'git add', 'git remote', 'git init', 'B', 'git bisect performs a binary search over history to find the commit that introduced a bug.', 'ADVANCED', 3, 'MCQ', 1),
(5761, 163, 'What is a Docker container?', 'a lightweight, isolated runtime environment for an application', 'a physical server', 'a database index', 'a network switch', 'A', 'A Docker container packages an application with its dependencies into a lightweight isolated runtime.', 'BEGINNER', 1, 'MCQ', 1),
(5762, 163, 'What is the main purpose of containerization?', 'packaging an application with its dependencies so it runs the same anywhere', 'speeding up the CPU', 'storing large databases', 'replacing the operating system', 'A', 'Containerization bundles an application and its dependencies so it behaves identically across different environments.', 'BEGINNER', 1, 'MCQ', 1),
(5763, 163, 'Which command builds a Docker image from a Dockerfile?', 'docker build', 'docker run', 'docker push', 'docker pull', 'C', 'docker build reads a Dockerfile and produces an image from its instructions.', 'BEGINNER', 1, 'MCQ', 1),
(5764, 163, 'Which command starts a container from an image?', 'docker run', 'docker build', 'docker save', 'docker inspect', 'D', 'docker run starts a container from an image, executing its default command.', 'BEGINNER', 1, 'MCQ', 1),
(5765, 163, 'What is the default registry where Docker images are pulled from?', 'Docker Hub', 'Maven Central', 'PyPI', 'npm Registry', 'A', 'Docker Hub is Docker''s default public image registry for pulling and pushing images.', 'BEGINNER', 1, 'MCQ', 1),
(5766, 163, 'What is a Dockerfile?', 'a text file with instructions to build a Docker image', 'a log of container starts', 'a configuration for the host OS', 'a list of running containers', 'B', 'A Dockerfile is a declarative script whose instructions build a Docker image layer by layer.', 'BEGINNER', 1, 'MCQ', 1),
(5767, 163, 'Which command lists running containers?', 'docker ps', 'docker ls', 'docker show', 'docker list', 'C', 'docker ps lists the containers that are currently running.', 'BEGINNER', 1, 'MCQ', 1),
(5768, 163, 'Which command removes a container?', 'docker rm', 'docker kill', 'docker rmi', 'docker stop', 'D', 'docker rm removes a stopped container, while docker rmi is used to remove images.', 'BEGINNER', 1, 'MCQ', 1),
(5769, 163, 'What is Docker Compose used for?', 'defining and running multi-container applications', 'compiling source code', 'backing up the host', 'monitoring the network', 'A', 'Docker Compose defines multi-container applications in a YAML file and manages them together.', 'BEGINNER', 1, 'MCQ', 1),
(5770, 163, 'What does the EXPOSE instruction in a Dockerfile do?', 'documents the port the container listens on', 'installs software', 'runs a command', 'copies files', 'B', 'EXPOSE declares which ports the container''s application listens on for documentation.', 'BEGINNER', 1, 'MCQ', 1),
(5771, 163, 'In a Dockerfile, which instruction copies files from the build context into the image?', 'COPY', 'RUN', 'CMD', 'WORKDIR', 'A', 'COPY copies files or directories from the build context into the image filesystem.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5772, 163, 'Which Dockerfile instruction runs a command at image build time, such as installing packages?', 'RUN', 'CMD', 'ENTRYPOINT', 'FROM', 'B', 'RUN executes commands while building the image, committing the result as a new layer.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5773, 163, 'Which instruction defines the command executed when a container is started?', 'CMD', 'ADD', 'EXPOSE', 'COPY', 'C', 'CMD specifies the default command executed when a container starts from the image.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5774, 163, 'What is the difference between CMD and ENTRYPOINT in a Dockerfile?', 'CMD sets the default command, while ENTRYPOINT defines the fixed base command that runs', 'they are identical', 'ENTRYPOINT is only for volumes', 'CMD cannot be overridden', 'D', 'CMD provides the default command that can be overridden, while ENTRYPOINT fixes the base command that always runs.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5775, 163, 'Which command publishes a container''s port to the host machine?', 'docker run -p 8080:80 image', 'docker run -d image', 'docker exec -it image', 'docker build image', 'A', 'docker run -p maps a host port to the container port, making the service reachable.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5776, 163, 'What happens to a container''s filesystem when the container is removed?', 'changes are lost unless a volume or image layer preserves them', 'the data is saved automatically', 'the host disk is wiped', 'the container restarts', 'B', 'Container writes are ephemeral, so removed containers lose data unless stored in a volume or committed to an image.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5777, 163, 'Which flag keeps a container running in the background?', 'docker run -d', 'docker run -t', 'docker run -p', 'docker run -e', 'C', 'The -d flag detaches the container, letting it run in the background.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5778, 163, 'Which command enters a running container''s shell?', 'docker exec -it container bash', 'docker start container', 'docker ps container', 'docker pull container', 'D', 'docker exec -it runs an interactive shell inside a running container.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5779, 163, 'Which command uploads a local image to a registry?', 'docker push', 'docker pull', 'docker save', 'docker commit', 'A', 'docker push uploads a tagged image to a configured registry such as Docker Hub.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5780, 163, 'Which Dockerfile instruction changes the working directory for subsequent commands?', 'WORKDIR', 'RUN', 'ENV', 'LABEL', 'B', 'WORKDIR sets the current directory for subsequent RUN, CMD and COPY instructions.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5781, 163, 'A production image must be as small as possible. Which Dockerfile strategy best achieves this?', 'use a multi-stage build that copies only the compiled artifact into a minimal runtime image', 'install everything in one layer', 'use the base OS with all build tools', 'store source code in the image', 'A', 'Multi-stage builds compile in a builder image and copy only the needed artifact into a slim final image.', 'ADVANCED', 3, 'MCQ', 1),
(5782, 163, 'Why is running containers as root a security risk?', 'a compromised container gains full host privileges', 'root users cannot access the network', 'root containers cannot write logs', 'it slows the container', 'B', 'Root inside a container can lead to host compromise, so production images should run with a non-root user.', 'ADVANCED', 3, 'MCQ', 1),
(5783, 163, 'Which practice best preserves database state across container restarts?', 'storing data in a named volume', 'writing data to the container filesystem', 'deleting the volume on restart', 'storing data in the image', 'C', 'Named volumes persist independently of the container, so database data survives restarts and re-creation.', 'ADVANCED', 3, 'MCQ', 1),
(5784, 163, 'A team must keep secrets out of their image. Which approach is correct?', 'pass secrets via environment variables or mounted secret files at runtime', 'hard-code them in the Dockerfile', 'commit them in the image', 'embed them in a config layer', 'D', 'Providing secrets at runtime through environment variables or secret mounts keeps them out of the image layers.', 'ADVANCED', 3, 'MCQ', 1),
(5785, 163, 'Which scenario best justifies using a named volume?', 'persisting database data that must survive container recreation', 'temporary caching only', 'reading the source code', 'storing build artifacts that are disposable', 'A', 'Named volumes persist data independently of the container lifecycle, ideal for database state.', 'ADVANCED', 3, 'MCQ', 1),
(5786, 163, 'A multi-stage build compiles a Go binary. What does the final stage typically contain?', 'only the compiled binary and the minimal runtime needed', 'the full toolchain and sources', 'all build dependencies', 'the entire base image', 'B', 'The final stage includes only the runtime dependencies and the compiled binary, keeping the image small.', 'ADVANCED', 3, 'MCQ', 1),
(5787, 163, 'Why is it important to pin base image versions in a Dockerfile?', 'unpinned tags like latest can change and break builds unexpectedly', 'pinned images are always smaller', 'pinning reduces disk usage', 'it improves the network speed', 'C', 'Pinning an image digest or tag ensures reproducible builds by avoiding unexpected base image changes.', 'ADVANCED', 3, 'MCQ', 1),
(5788, 163, 'What is the main purpose of a container registry vulnerability scan?', 'detecting known vulnerabilities in base images and dependencies', 'increasing the image size', 'renaming containers', 'optimizing the Dockerfile syntax', 'D', 'Registry scans compare image layers against vulnerability databases to surface known CVEs before deployment.', 'ADVANCED', 3, 'MCQ', 1),
(5789, 163, 'Which architecture best describes container orchestration of microservices?', 'managing many containers across hosts with scheduling, scaling and networking', 'running all services in one container', 'deploying only on laptops', 'using a single VM per service', 'A', 'Orchestration platforms schedule, scale and network many containers across a cluster of hosts.', 'ADVANCED', 3, 'MCQ', 1),
(5790, 163, 'Why should you use .dockerignore in a Docker project?', 'to exclude unnecessary files from the build context, shrinking and securing the build', 'to ignore container logs', 'to disable Docker entirely', 'to rename the image', 'B', 'A .dockerignore excludes secrets, build artifacts and caches from the build context, reducing image bloat.', 'ADVANCED', 3, 'MCQ', 1),
(5791, 164, 'What is the role of the control plane in a Kubernetes cluster?', 'it manages and coordinates the worker nodes and maintains the cluster''s desired state', 'it runs all the application workloads', 'it stores container images', 'it provides DNS for the internet', 'A', 'The control plane makes scheduling and cluster-wide decisions and keeps the actual state aligned with the desired state.', 'BEGINNER', 1, 'MCQ', 1),
(5792, 164, 'What is a pod in Kubernetes?', 'the smallest deployable unit that wraps one or more containers', 'a physical server', 'a database table', 'a container registry', 'B', 'A pod is the smallest deployable unit in Kubernetes, wrapping one or more containers sharing resources.', 'BEGINNER', 1, 'MCQ', 1),
(5793, 164, 'What is a Kubernetes node?', 'a worker machine that runs pods', 'a type of container', 'a deployment manifest', 'a secret', 'C', 'A node is a worker machine in the cluster where pods are scheduled and run.', 'BEGINNER', 1, 'MCQ', 1),
(5794, 164, 'Which tool is the command-line interface for interacting with a Kubernetes cluster?', 'kubectl', 'docker', 'git', 'npm', 'D', 'kubectl is the standard command-line tool for talking to the Kubernetes API server.', 'BEGINNER', 1, 'MCQ', 1),
(5795, 164, 'What does a Kubernetes Deployment resource manage?', 'the desired state of stateless application replicas', 'database backups', 'user accounts', 'network switches', 'A', 'A Deployment declares a desired number of replicas and keeps the actual state in line with it.', 'BEGINNER', 1, 'MCQ', 1),
(5796, 164, 'What is a Kubernetes Service used for?', 'providing a stable network endpoint to a set of pods', 'storing secrets', 'scheduling batch jobs', 'backing up the cluster', 'B', 'A Service gives pods a stable virtual IP and DNS name that routes traffic to them.', 'BEGINNER', 1, 'MCQ', 1),
(5797, 164, 'What is a Kubernetes cluster?', 'a set of worker nodes plus a control plane', 'a single container', 'a Docker image', 'a version control branch', 'C', 'A cluster combines a control plane and worker nodes that together run containerized workloads.', 'BEGINNER', 1, 'MCQ', 1),
(5798, 164, 'Which command deploys a manifest to the cluster?', 'kubectl apply -f manifest.yaml', 'kubectl delete -f manifest.yaml', 'kubectl get pods', 'kubectl describe node', 'D', 'kubectl apply sends the resource defined in the manifest to the cluster.', 'BEGINNER', 1, 'MCQ', 1),
(5799, 164, 'Which command lists the pods running in the default namespace?', 'kubectl get pods', 'kubectl run pods', 'kubectl exec pods', 'kubectl apply pods', 'A', 'kubectl get pods lists the pods in the current namespace.', 'BEGINNER', 1, 'MCQ', 1),
(5800, 164, 'What does Kubernetes do when a pod crashes?', 'restarts or reschedules it to maintain the desired state', 'deletes the whole cluster', 'ignores the failure', 'shuts down the node', 'B', 'Kubernetes controllers detect crashed pods and restart or reschedule them to meet the desired state.', 'BEGINNER', 1, 'MCQ', 1),
(5801, 164, 'A web app is served by 3 replicas behind a Service. What does the Service route traffic to?', 'all healthy pods matching its selector', 'only the first pod created', 'the control plane', 'a random node', 'A', 'A Service uses a label selector to route traffic to all healthy pods that match its selector.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5802, 164, 'How does horizontal pod autoscaling (HPA) decide to add replicas?', 'by comparing observed metrics such as CPU utilization against a target', 'by counting the number of users in the database', 'by the time of day only', 'by random selection', 'B', 'The HPA scales replicas when observed resource usage, like CPU, exceeds a configured target.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5803, 164, 'Which resource maps a container port to a stable cluster-wide address so the app is reachable?', 'a Service of type ClusterIP or LoadBalancer', 'a ConfigMap', 'a Pod', 'a Secret', 'C', 'Services expose pods at stable addresses such as ClusterIP within the cluster or LoadBalancer externally.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5804, 164, 'What is the purpose of a liveness probe in Kubernetes?', 'detecting and restarting a container that is stuck or unhealthy', 'scaling up replicas', 'storing configuration', 'scheduling batch jobs', 'D', 'Liveness probes restart containers that stop responding so unhealthy pods are replaced automatically.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5805, 164, 'What is the purpose of a readiness probe?', 'indicating whether a pod is ready to receive traffic', 'checking the Kubernetes version', 'deleting old replicas', 'backing up logs', 'A', 'Readiness probes tell Kubernetes whether a pod can accept traffic, preventing requests to unready pods.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5806, 164, 'Which command scales a deployment named web to 5 replicas?', 'kubectl scale deployment web --replicas=5', 'kubectl get deployment web', 'kubectl exec web --replicas=5', 'kubectl describe web --replicas=5', 'B', 'kubectl scale changes the replica count of a deployment to the specified number.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5807, 164, 'What is a ConfigMap used for in Kubernetes?', 'storing non-sensitive configuration data separate from containers', 'storing encrypted passwords', 'running cron jobs', 'allocating IP addresses', 'C', 'ConfigMaps hold non-confidential configuration that pods can consume as files or environment variables.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5808, 164, 'What is a Secret resource used for?', 'storing sensitive data such as passwords and tokens', 'storing public logs', 'defining container images', 'managing namespaces', 'D', 'Secrets store sensitive values like passwords and tokens, which pods can consume securely.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5809, 164, 'Which resource creates a stable DNS name for an external database service?', 'an ExternalName or Endpoints Service', 'a Deployment', 'a ReplicaSet', 'a Namespace', 'A', 'An ExternalName service maps a DNS name to an external service, or Endpoints can point at external IPs.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5810, 164, 'What happens during a rolling update of a Deployment?', 'pods are replaced gradually so the app stays available', 'all pods are terminated at once', 'the cluster restarts', 'the manifest is deleted', 'B', 'A rolling update replaces old pods with new ones incrementally, maintaining availability.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5811, 164, 'Why might a pod be stuck in a Pending state?', 'the scheduler could not find a node with enough resources', 'the pod is healthy', 'the image was built locally', 'the pod finished its work', 'A', 'Pending means the pod has not been scheduled, often because no node has sufficient CPU, memory or storage.', 'ADVANCED', 3, 'MCQ', 1),
(5812, 164, 'What does the scheduler do in Kubernetes?', 'chooses which node each unscheduled pod should run on', 'runs the container runtime', 'stores image layers', 'manages DNS records', 'B', 'The scheduler places unscheduled pods onto nodes that satisfy their resource and affinity constraints.', 'ADVANCED', 3, 'MCQ', 1),
(5813, 164, 'A stateful application requires persistent storage and stable identity. Which workload is most appropriate?', 'a StatefulSet', 'a Deployment', 'a DaemonSet', 'a ConfigMap', 'C', 'StatefulSets give pods stable identity and persistent volumes, suited for databases and stateful services.', 'ADVANCED', 3, 'MCQ', 1),
(5814, 164, 'Which resource runs a pod on every node in the cluster, such as a logging agent?', 'a DaemonSet', 'a Job', 'a Service', 'a ReplicaSet', 'D', 'DaemonSets guarantee one pod runs on every (or selected) node, ideal for agents like log collectors.', 'ADVANCED', 3, 'MCQ', 1),
(5815, 164, 'What is the purpose of resource requests and limits in a pod spec?', 'they inform the scheduler about needs and cap the resources a container may use', 'they name the containers', 'they set the image tag', 'they control the namespace', 'A', 'Requests guide scheduling by declaring needs, while limits cap a container''s maximum resource use.', 'ADVANCED', 3, 'MCQ', 1),
(5816, 164, 'Which Kubernetes feature is best for storing a database password consumed by a pod?', 'a Secret mounted as a volume or environment variable', 'a ConfigMap', 'a Service', 'a NodePort', 'B', 'Secrets store sensitive values and can be exposed to pods via volumes or environment variables.', 'ADVANCED', 3, 'MCQ', 1),
(5817, 164, 'How does a HorizontalPodAutoscaler interact with a Deployment?', 'it updates the Deployment''s replica count based on metrics', 'it replaces the Deployment with a pod', 'it deletes old pods', 'it changes the container image', 'C', 'The HPA controller reads metrics and adjusts the Deployment replica count to meet the configured target.', 'ADVANCED', 3, 'MCQ', 1),
(5818, 164, 'An operator wants to run a one-off batch computation to completion. Which workload is correct?', 'a Job', 'a StatefulSet', 'a DaemonSet', 'a Service', 'D', 'Jobs run pods to completion for one-off batch work, unlike long-running workloads.', 'ADVANCED', 3, 'MCQ', 1),
(5819, 164, 'What is the purpose of pod anti-affinity rules?', 'spreading replicas across nodes to increase fault tolerance', 'forcing all replicas onto one node', 'attaching volumes', 'hiding the pod IP', 'A', 'Anti-affinity rules separate replicas across nodes so a node failure does not take down the whole service.', 'ADVANCED', 3, 'MCQ', 1),
(5820, 164, 'During a rollout, a new pod repeatedly fails readiness checks. What does Kubernetes do?', 'stops the rollout and keeps the old version running', 'deletes the whole deployment', 'ignores the failure', 'restarts all nodes', 'B', 'If new pods never become ready, the rolling update stalls, preserving the previous stable revision.', 'ADVANCED', 3, 'MCQ', 1),
(5821, 165, 'What is the main purpose of application monitoring?', 'observing system health, performance and errors in real time', 'editing configuration files', 'compiling source code', 'backing up the database', 'A', 'Monitoring collects metrics, logs and traces to track the health and performance of systems.', 'BEGINNER', 1, 'MCQ', 1),
(5822, 165, 'What is a metric in monitoring?', 'a numeric measurement such as CPU usage or latency', 'a text document', 'a deployment script', 'a container image', 'B', 'Metrics are numeric measurements sampled over time, such as CPU utilization or request latency.', 'BEGINNER', 1, 'MCQ', 1),
(5823, 165, 'Which open-source tool is commonly used for collecting and querying metrics?', 'Prometheus', 'Notepad', 'Excel', 'VLC Player', 'C', 'Prometheus is a popular open-source monitoring and alerting tool for time-series metrics.', 'BEGINNER', 1, 'MCQ', 1),
(5824, 165, 'What is a log in the context of monitoring?', 'a timestamped record of an event or message from a system', 'a network password', 'a configuration file', 'a CPU register', 'D', 'Logs are timestamped records of events, errors and messages produced by applications and systems.', 'BEGINNER', 1, 'MCQ', 1),
(5825, 165, 'Which tool is widely used for centralized log aggregation and searching?', 'Elastic Stack (ELK)', 'Photoshop', 'Windows Notepad', 'GIMP', 'A', 'The Elastic Stack (Elasticsearch, Logstash, Kibana) is commonly used to aggregate and search logs.', 'BEGINNER', 1, 'MCQ', 1),
(5826, 165, 'What does an alert in a monitoring system do?', 'notifies operators when a threshold or condition is met', 'restarts the monitoring server', 'deletes old logs', 'compiles the application', 'B', 'Alerts notify engineers when monitored values cross configured thresholds or conditions.', 'BEGINNER', 1, 'MCQ', 1),
(5827, 165, 'What does the term uptime refer to in monitoring?', 'the percentage of time a service is operational and available', 'the number of log entries', 'the disk space used', 'the number of containers', 'C', 'Uptime measures the proportion of time a service remains available to its users.', 'BEGINNER', 1, 'MCQ', 1),
(5828, 165, 'Which metric typically indicates how fast a web server responds?', 'latency', 'database size', 'login count', 'network subnet', 'D', 'Latency measures the time a server takes to respond, directly reflecting responsiveness.', 'BEGINNER', 1, 'MCQ', 1),
(5829, 165, 'What is a dashboard in a monitoring tool?', 'a visual panel displaying key metrics and graphs', 'a container registry', 'a source file', 'a backup schedule', 'A', 'A dashboard presents live charts and panels so operators can observe metrics at a glance.', 'BEGINNER', 1, 'MCQ', 1),
(5830, 165, 'Which component in the Prometheus architecture periodically pulls metrics from targets?', 'the Prometheus server', 'Kibana', 'the Kubernetes scheduler', 'Grafana only', 'B', 'The Prometheus server scrapes (pulls) metrics from instrumented targets on a schedule.', 'BEGINNER', 1, 'MCQ', 1),
(5831, 165, 'A service''s error rate spikes to 15 percent. Which alert level best matches a severe outage?', 'a critical alert requiring immediate response', 'an info message', 'a debug log', 'a silent ignore', 'A', 'A critical alert fires when an outage-level condition, like a high error rate, needs immediate attention.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5832, 165, 'In Prometheus, which query expression selects all HTTP requests with a status of 500?', 'http_requests_total{status=''500''}', 'SELECT FROM http', 'count(status)', 'status == 500', 'B', 'PromQL label matchers like {status=''500''} filter time series to those with that label value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5833, 165, 'What is the primary difference between logs and metrics?', 'logs are discrete events with detail, while metrics are numeric aggregates over time', 'logs are always secret', 'metrics are text documents', 'there is no difference', 'C', 'Logs capture individual events with rich context, while metrics are numeric measurements aggregated over time.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5834, 165, 'Which tool is commonly paired with Prometheus to build dashboards and charts?', 'Grafana', 'Excel', 'Pandoc', 'WinZip', 'D', 'Grafana is the standard visualization layer paired with Prometheus to build dashboards.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5835, 165, 'What does RED stand for in the RED monitoring method?', 'Rate, Errors, Duration', 'Random, Error, Deploy', 'Restart, Eject, Delete', 'Request, Execute, Debug', 'A', 'RED focuses on Rate, Errors and Duration for monitoring request-driven services.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5836, 165, 'Which metric is the classic four golden signals of Google SRE?', 'latency, traffic, errors and saturation', 'cpu, ram, disk and network', 'uptime, users, costs and tickets', 'builds, tests, commits and merges', 'B', 'The four golden signals are latency, traffic, errors and saturation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5837, 165, 'What is a trace in distributed tracing?', 'the end-to-end path of a request across multiple services', 'a type of log line', 'a metric label', 'a container name', 'C', 'A trace follows a single request through every service it touches, showing timing at each step.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5838, 165, 'What does a histogram metric in Prometheus record?', 'the distribution of observed values across predefined buckets', 'only the maximum value', 'the number of unique users', 'the current log file size', 'D', 'A histogram counts observations into predefined value buckets, capturing the distribution of a metric.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5839, 165, 'Which monitoring approach is best for detecting that a service is fully down?', 'a black-box probe that checks external availability of the service', 'reading the source code', 'counting the pods manually', 'viewing the README', 'A', 'Black-box monitoring probes the service from the outside, detecting outages that internal metrics miss.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5840, 165, 'What is the purpose of a monitoring retention policy?', 'controlling how long metrics and logs are stored', 'increasing storage forever', 'deleting the cluster', 'slowing down queries', 'B', 'Retention policies control storage duration, balancing data availability against disk cost.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5841, 165, 'A dashboard shows average latency is healthy, yet users report slow pages. Why might averages hide the problem?', 'averages mask outliers, such as slow tail latency for a small percentage of requests', 'averages are always wrong', 'the dashboard is broken', 'users are mistaken', 'A', 'Mean latency hides long tail outliers, so percentiles like p95 or p99 expose the real user experience.', 'ADVANCED', 3, 'MCQ', 1),
(5842, 165, 'Why should alerts be based on page-level or user-level signals rather than raw host metrics alone?', 'user-visible signals capture actual impact, while host metrics can miss application-level failures', 'host metrics are useless', 'alerts are always manual', 'page-level data is never collected', 'B', 'User-level signals reflect real impact, while a healthy host can still be serving errors or broken pages.', 'ADVANCED', 3, 'MCQ', 1),
(5843, 165, 'In Prometheus, what is the purpose of recording rules?', 'precomputing expensive queries and storing them as new series', 'storing log files', 'naming containers', 'scheduling pods', 'C', 'Recording rules evaluate complex PromQL queries periodically and store the results as new time series.', 'ADVANCED', 3, 'MCQ', 1),
(5844, 165, 'What is the main risk of alerting on raw CPU thresholds for a web service?', 'noisy false positives that do not reflect user-visible impact', 'alerts always fire correctly', 'the server shuts down', 'metrics are not collected', 'D', 'Raw CPU thresholds often alert on benign spikes while missing application-level failures users actually experience.', 'ADVANCED', 3, 'MCQ', 1),
(5845, 165, 'A service emits thousands of logs per second. Which practice is most appropriate for managing log volume?', 'using structured logging with levels and sampling or filtering at ingestion', 'logging everything twice', 'disabling all logs', 'storing logs in memory only', 'A', 'Structured logging with levels and ingestion filtering keeps log volume manageable while retaining useful detail.', 'ADVANCED', 3, 'MCQ', 1),
(5846, 165, 'Which approach best supports correlating a failing request across many microservices?', 'distributed tracing with a shared trace ID propagated through every service', 'reading each service log independently', 'comparing disk sizes', 'restarting services', 'B', 'A shared trace ID ties the request path together across services, enabling end-to-end correlation.', 'ADVANCED', 3, 'MCQ', 1),
(5847, 165, 'Why should a monitoring system have a separate alerting path from its data storage?', 'alerting must survive the data store going down or being unavailable', 'it is cheaper to share one path', 'storage never fails', 'alerts should reuse dashboards only', 'C', 'An independent alerting path keeps notifications flowing even when metric storage fails or is unreachable.', 'ADVANCED', 3, 'MCQ', 1),
(5848, 165, 'A sudden drop in requests could indicate an outage or a genuine decline in traffic. What is the best way to distinguish these?', 'correlate the drop with upstream traffic, error rates and synthetic probes', 'assume it is an outage', 'ignore the change', 'restart the database', 'D', 'Correlating with other signals distinguishes a real outage from an expected traffic decline.', 'ADVANCED', 3, 'MCQ', 1),
(5849, 165, 'Which metric best detects an overloaded queue where workers cannot keep up?', 'queue depth, which grows when consumption is slower than production', 'the queue name', 'the worker count', 'the queue version', 'A', 'Growing queue depth signals that work is arriving faster than workers can process it.', 'ADVANCED', 3, 'MCQ', 1),
(5850, 165, 'What is the recommended way to handle alerts that fire during a known, scheduled maintenance window?', 'suppress or mute the alerts for that window while ensuring the service is genuinely down as planned', 'ignore alerts forever', 'delete the monitoring system', 'hide the dashboard', 'B', 'Suppressing alerts during a planned maintenance window avoids paging operators for expected downtime.', 'ADVANCED', 3, 'MCQ', 1),
(5851, 166, 'Which cloud service model provides customers with the most direct control over the underlying infrastructure?', 'Infrastructure as a Service (IaaS)', 'Platform as a Service (PaaS)', 'Software as a Service (SaaS)', 'Function as a Service (FaaS)', 'A', 'IaaS gives customers control over virtualized compute, storage and networking resources, while the provider manages only the physical infrastructure.', 'BEGINNER', 1, 'MCQ', 1),
(5852, 166, 'What does the shared responsibility model define?', 'how cloud service bills are calculated', 'which security duties belong to the cloud provider and which belong to the customer', 'how virtual machines are migrated between regions', 'the uptime guarantee in a service level agreement', 'B', 'The shared responsibility model clearly maps the security obligations of the provider against those that remain with the customer.', 'BEGINNER', 1, 'MCQ', 1),
(5853, 166, 'Under the shared responsibility model, which of the following is typically the cloud customer''s responsibility?', 'physical security of the data center', 'patching the underlying hypervisor', 'managing access to its own data and identities', 'maintaining the storage hardware', 'C', 'Customers control and remain responsible for their own data, identities and access configuration, regardless of the service model.', 'BEGINNER', 1, 'MCQ', 1),
(5854, 166, 'What does the abbreviation CSP stand for in the context of cloud computing?', 'Cloud Security Protocol', 'Centralized Service Platform', 'Certified Security Practitioner', 'Cloud Service Provider', 'D', 'CSP is the standard abbreviation for Cloud Service Provider, the organization that delivers cloud services over the internet.', 'BEGINNER', 1, 'MCQ', 1),
(5855, 166, 'What is a multi-tenant cloud environment?', 'a single customer renting several cloud regions', 'shared infrastructure securely isolated so that multiple customers use it simultaneously', 'a cloud account with many administrator users', 'a network with multiple virtual firewalls', 'A', 'Multi-tenancy lets many customers share the same physical resources while keeping their workloads and data logically isolated.', 'BEGINNER', 1, 'MCQ', 1),
(5856, 166, 'Which term describes data that is stored and not currently moving across a network?', 'data in motion', 'data at rest', 'data in use', 'data in transit', 'B', 'Data at rest refers to data stored on disks, databases or backups, and it needs encryption and access controls to stay protected.', 'BEGINNER', 1, 'MCQ', 1),
(5857, 166, 'Which term describes data that is actively moving between systems over a network?', 'data at rest', 'data on disk', 'data in transit', 'data archived', 'C', 'Data in transit is information traveling across networks, which should be protected with protocols such as TLS.', 'BEGINNER', 1, 'MCQ', 1),
(5858, 166, 'What is a security group in a cloud virtual network?', 'a physical firewall appliance in the data center', 'a group of users with shared permissions', 'a backup schedule for virtual machines', 'a virtual firewall that controls inbound and outbound traffic for resources', 'D', 'A security group acts as a virtual firewall, allowing or denying traffic to and from cloud resources based on rules.', 'BEGINNER', 1, 'MCQ', 1),
(5859, 166, 'Which of the following is a common benefit of cloud computing?', 'on-demand scalability of resources', 'guaranteed immunity to all attacks', 'elimination of all security responsibilities', 'permanent storage that can never fail', 'A', 'Cloud platforms can scale resources up and down on demand, which is a core advantage over fixed on-premises capacity.', 'BEGINNER', 1, 'MCQ', 1),
(5860, 166, 'What is a virtual machine (VM) in the cloud?', 'a physical server purchased by the customer', 'a software emulation of a computer running on shared physical hardware', 'a type of container that shares the host kernel', 'a managed database service', 'B', 'A virtual machine is a software-emulated computer that runs its own operating system on top of virtualized physical hardware.', 'BEGINNER', 1, 'MCQ', 1),
(5861, 166, 'A company uses a SaaS application and a user account is compromised. Under the shared responsibility model, who is primarily responsible for responding?', 'the SaaS provider, because it owns the software', 'the hardware vendor', 'the customer, because account and access management is its responsibility', 'nobody, because SaaS is automatically secure', 'C', 'With SaaS the provider secures the application platform, but the customer is responsible for its own accounts, credentials and user access.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5862, 166, 'Under an IaaS deployment, which security task typically remains the responsibility of the cloud provider?', 'patching the guest operating system', 'hardening the customer''s application', 'managing user passwords', 'protecting the physical hosts and the hypervisor', 'D', 'In IaaS the provider owns the physical data center and hypervisor layer, while the customer secures the guest OS and everything above it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5863, 166, 'A web server VM only needs to accept HTTPS traffic from the internet. Which change reduces its attack surface most directly?', 'restrict the security group to allow inbound port 443 only', 'increase the number of CPUs', 'enlarge the boot disk', 'enable the admin console for the VM', 'A', 'Restricting inbound rules to only port 443 removes all other exposed services, shrinking the VM''s attack surface.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5864, 166, 'What is the purpose of cloud identity and access management (IAM) policies?', 'to allocate more storage to users', 'to define which users and roles can perform which actions on which resources', 'to monitor billing for the account', 'to encrypt data in transit', 'B', 'IAM policies are JSON documents that grant or deny specific actions on specific cloud resources to identities.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5865, 166, 'A developer asks for permissions to only the buckets she manages. Granting exactly those permissions demonstrates which principle?', 'defense in depth', 'separation of duties', 'least privilege', 'non-repudiation', 'C', 'Least privilege means granting only the minimum permissions required to perform a job, limiting the damage of a compromise.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5866, 166, 'Which control is most effective at preventing unauthorized access when a cloud user''s password has been stolen?', 'a longer username', 'stronger password storage', 'disabling the account', 'multi-factor authentication (MFA)', 'D', 'MFA requires a second factor in addition to the password, so a stolen password alone is no longer sufficient to sign in.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5867, 166, 'What does a virtual private cloud (VPC) provide within a public cloud?', 'an isolated virtual network where resources are launched with private addressing', 'a public web address for every server', 'a managed antivirus service', 'a dedicated physical server', 'A', 'A VPC gives customers their own logically isolated section of the cloud network with full control over subnets and routing.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5868, 166, 'An organization must encrypt objects stored in a cloud object storage bucket. Which term describes this requirement?', 'encryption in transit', 'encryption at rest', 'encryption of logs', 'encryption of metadata', 'B', 'Encrypting stored objects protects data at rest, ensuring that even stolen storage media cannot be read without the keys.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5869, 166, 'A team deploys a virtual machine from a public image that still has the vendor''s default password. What is the most serious consequence if not changed?', 'the VM runs slower', 'the VM cannot connect to the network', 'anyone who knows the default password may gain full access', 'the VM automatically encrypts its own data', 'C', 'Default credentials are publicly documented, so leaving them in place allows attackers to log in and compromise the instance.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5870, 166, 'A security engineer needs to log every API call that changes cloud resources. Which service capability should be enabled?', 'load balancing', 'auto scaling', 'content delivery network', 'cloud audit logging', 'D', 'Cloud audit logging records every API action, providing the trail needed to detect and investigate unauthorized changes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5871, 166, 'A large enterprise manages many cloud accounts. Which architecture best reduces risk around the administrative accounts?', 'a centralized management account with strong MFA, short-lived credentials and central logging', 'one shared admin account used by every team', 'giving every developer owner access', 'storing admin passwords in a shared spreadsheet', 'A', 'Centralizing privileged access in a dedicated account with MFA, short-lived credentials and logging limits exposure and improves auditability.', 'ADVANCED', 3, 'MCQ', 1),
(5872, 166, 'An incident reveals that a cloud storage bucket was configured as publicly readable and contained customer data. What is the first remediation?', 'delete the billing account', 'block public access and remove the overly permissive bucket policy', 'reboot the object storage service', 'increase the bucket''s storage class', 'B', 'Immediately restricting public access and fixing the bucket policy stops the ongoing exposure of customer data.', 'ADVANCED', 3, 'MCQ', 1),
(5873, 166, 'What is the primary purpose of a cloud access security broker (CASB)?', 'to encrypt the physical hard drives in data centers', 'to replace the cloud provider''s firewalls', 'to enforce security policies between users and cloud applications', 'to back up virtual machines nightly', 'C', 'A CASB sits between users and cloud services to enforce access, data and visibility policies across SaaS, PaaS and IaaS.', 'ADVANCED', 3, 'MCQ', 1),
(5874, 166, 'A company must allow staff to use the same identities across on-premises Active Directory and cloud services. Which approach best supports this securely?', 'recreate every account manually in the cloud', 'share password hashes publicly', 'email the on-premises password to each user', 'use federated identity with single sign-on (SSO)', 'D', 'Federation with SSO lets the on-premises directory authenticate users and issue trusted tokens for cloud services.', 'ADVANCED', 3, 'MCQ', 1),
(5875, 166, 'A business stores customer PII in a cloud database. Which combination provides defense in depth for data at rest?', 'encryption with managed keys, strict access policies and monitoring of data access', 'storing data in plaintext for speed', 'removing all database backups', 'granting every employee database access', 'A', 'Layering encryption, access control and monitoring protects stored data even if one control fails.', 'ADVANCED', 3, 'MCQ', 1),
(5876, 166, 'An application is vulnerable to a server-side request forgery (SSRF). In a public cloud, what is the most dangerous capability this gives an attacker?', 'reading the hypervisor firmware', 'retrieving temporary credentials from the instance metadata service', 'changing the machine''s IP address', 'deleting the security group', 'B', 'SSRF can make the server query the instance metadata endpoint, which may leak temporary IAM credentials that grant broader cloud access.', 'ADVANCED', 3, 'MCQ', 1),
(5877, 166, 'Which practice is the strongest alternative to embedding long-lived static access keys in cloud applications?', 'hardcoding the keys in source code', 'putting the keys in environment variables only', 'using short-lived tokens or IAM roles assumed by the application', 'sharing one key among all teams', 'C', 'IAM roles and short-lived tokens expire and auto-rotate, so leaked credentials are far less valuable than static keys.', 'ADVANCED', 3, 'MCQ', 1),
(5878, 166, 'Cloud audit logs show a new administrator account was created from an unknown external IP during the night. What is the first step?', 'ignore it because admins work late', 'notify the whole company', 'restart the management console', 'disable the suspicious account and investigate the full audit trail', 'D', 'Disabling the unauthorized account immediately stops further abuse while the audit trail is used to determine how it was created.', 'ADVANCED', 3, 'MCQ', 1),
(5879, 166, 'In many cloud platforms, security groups are described as stateful. What does that mean?', 'return traffic for an allowed connection is automatically permitted', 'rules must be configured separately for replies', 'security groups automatically encrypt traffic', 'security groups only inspect outbound traffic', 'A', 'A stateful security group automatically allows the reply traffic for an outbound or inbound connection that was already permitted.', 'ADVANCED', 3, 'MCQ', 1),
(5880, 166, 'What is the primary risk of assigning an IAM role a wildcard policy that grants * on all resources?', 'the role becomes read-only', 'any compromise of that role gives the attacker unrestricted control', 'the role can no longer be used by services', 'wildcards are always safer than specific grants', 'B', 'A wildcard grant means a single compromised identity can perform any action on any resource, maximizing blast radius.', 'ADVANCED', 3, 'MCQ', 1),
(5881, 167, 'What is the primary purpose of TLS (Transport Layer Security) for web traffic?', 'to provide confidentiality and integrity of data in transit', 'to speed up web page loading', 'to block all pop-up advertisements', 'to compress images for download', 'A', 'TLS encrypts the connection and detects tampering, protecting the confidentiality and integrity of data as it travels.', 'BEGINNER', 1, 'MCQ', 1),
(5882, 167, 'What does HTTPS add to normal HTTP?', 'a faster compression algorithm', 'a TLS-encrypted layer for secure communication', 'a second domain name', 'automatic page translation', 'B', 'HTTPS is HTTP layered over TLS, so all requests and responses are encrypted between client and server.', 'BEGINNER', 1, 'MCQ', 1),
(5883, 167, 'What is the role of a digital certificate in a TLS connection?', 'to store the user''s browsing history', 'to increase the server''s processing speed', 'to verify the server''s identity and carry its public key', 'to translate web pages into other languages', 'C', 'A digital certificate binds a public key to an identity, letting the client verify who it is really talking to.', 'BEGINNER', 1, 'MCQ', 1),
(5884, 167, 'What does a certificate authority (CA) do?', 'hosts web servers for small businesses', 'blocks malicious websites for all browsers', 'encrypts the public internet backbone', 'issues and digitally signs certificates that vouch for identity', 'D', 'A CA signs certificates so clients can trust the identity claims they contain through the chain of trust.', 'BEGINNER', 1, 'MCQ', 1),
(5885, 167, 'Which protocol is the standard method for secure remote command-line access to a server?', 'SSH', 'FTP', 'Telnet', 'SMTP', 'A', 'SSH encrypts the session and authenticates both ends, making it the standard for secure remote administration.', 'BEGINNER', 1, 'MCQ', 1),
(5886, 167, 'What is a virtual private network (VPN)?', 'a public Wi-Fi hotspot', 'an encrypted tunnel that carries traffic securely over a public network', 'a firewall that blocks all traffic', 'a backup of a private network', 'B', 'A VPN encrypts and tunnels traffic between endpoints across an untrusted network such as the internet.', 'BEGINNER', 1, 'MCQ', 1),
(5887, 167, 'What is encryption?', 'deleting data to save space', 'compressing data for storage', 'transforming readable plaintext into unreadable ciphertext', 'making data available to everyone', 'C', 'Encryption converts plaintext into ciphertext using an algorithm and key so only authorized parties can recover it.', 'BEGINNER', 1, 'MCQ', 1),
(5888, 167, 'In symmetric-key cryptography, how many keys are needed?', 'one private key for each user and one public key', 'a key pair per user', 'at least three keys', 'a single shared key used for both encryption and decryption', 'D', 'Symmetric encryption uses one shared key for both encrypting and decrypting, so all parties must keep it secret.', 'BEGINNER', 1, 'MCQ', 1),
(5889, 167, 'What is the defining feature of asymmetric (public-key) cryptography?', 'a key pair in which the public key encrypts and the private key decrypts', 'using the same key for every operation', 'no keys are required', 'keys that never expire', 'A', 'Asymmetric cryptography uses a mathematically linked public and private key pair for encryption and digital signatures.', 'BEGINNER', 1, 'MCQ', 1),
(5890, 167, 'What is a cryptographic hash primarily used for?', 'encrypting large files', 'detecting changes to data through a fixed-length digest', 'compressing video streams', 'authenticating users with passwords only', 'B', 'A hash produces a fixed-size digest, and any change in the input changes the digest, enabling integrity checks.', 'BEGINNER', 1, 'MCQ', 1),
(5891, 167, 'During a TLS handshake, which item does the server send first to prove its identity?', 'the session encryption key', 'the user''s password', 'its digital certificate', 'its IP address', 'C', 'The server presents its certificate so the client can verify its identity and obtain the public key for key exchange.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5892, 167, 'Why does perfect forward secrecy improve the security of a TLS session?', 'it makes the handshake faster', 'it removes the need for certificates', 'it lets the server see all plaintext', 'ephemeral session keys mean past sessions stay secret even if the long-term key leaks', 'D', 'Perfect forward secrecy derives each session key with ephemeral parameters, so leaking a long-term key does not decrypt past traffic.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5893, 167, 'A user visits a site whose certificate has expired. What is the main risk?', 'the client cannot reliably verify the server''s identity, enabling possible impersonation', 'the site will load faster', 'the site''s content becomes unreadable to everyone', 'the connection becomes unencrypted but still verified', 'A', 'An expired certificate fails validation, so the client cannot confirm who operates the site, raising man-in-the-middle risk.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5894, 167, 'Which method is the most appropriate for securely copying files between two servers?', 'plain FTP', 'SFTP or SCP over SSH', 'emailing the files', 'sharing a public file server', 'B', 'SFTP and SCP run over SSH, encrypting both the data and authentication during transfer.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5895, 167, 'An attacker captures and modifies an email while it travels between mail servers. Which security property of the message has been violated?', 'confidentiality', 'availability', 'integrity', 'non-repudiation', 'C', 'Integrity is violated because the content was altered in transit without detection by the recipient.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5896, 167, 'Which mechanism can protect email in transit between two mail servers?', 'HTTPS on the web', 'DNSSEC', 'IPSec site-to-site tunnels', 'STARTTLS to upgrade the SMTP connection to TLS', 'D', 'STARTTLS upgrades an SMTP connection to an encrypted TLS channel between mail servers.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5897, 167, 'What does DNSSEC provide for DNS traffic?', 'authenticity and integrity of DNS responses', 'encryption of all web traffic', 'faster DNS resolution', 'blocking all malicious domains', 'A', 'DNSSEC signs DNS records so resolvers can verify they were not tampered with in transit.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5898, 167, 'A user connects to an open Wi-Fi hotspot where an attacker can capture traffic. What protects the user''s web traffic?', 'HTTP links', 'TLS-encrypted HTTPS connections', 'the browser''s cache', 'the hotspot''s login page', 'B', 'HTTPS/TLS encrypts the traffic, so an eavesdropper on the network cannot read the content.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5899, 167, 'After the TLS handshake, what is the shared session key used for?', 'for the certificate validation only', 'to compress the web page', 'to encrypt the application data symmetrically and efficiently', 'to sign the server''s certificate', 'C', 'Once both sides agree on a session key, it is used with symmetric ciphers for fast bulk data encryption.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5900, 167, 'Which cipher family is commonly used for bulk data encryption in modern TLS, such as TLS 1.3?', 'DES', 'RC4', 'SHA-256', 'AES-GCM', 'D', 'AES-GCM is an authenticated encryption cipher widely used in modern TLS deployments, including TLS 1.3.', 'INTERMEDIATE', 2, 'MCQ', 1);
INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(5901, 167, 'A security engineer must ensure a web server only negotiates strong TLS. Which configuration change achieves this best?', 'disable legacy protocols and weak ciphers and require TLS 1.2 or 1.3', 'allow all ciphers for compatibility', 'turn off certificate validation', 'use HTTP for all internal pages', 'A', 'Disabling old protocols and weak ciphers forces clients to use modern, secure TLS versions and algorithms.', 'ADVANCED', 3, 'MCQ', 1),
(5902, 167, 'An attacker presents a self-signed certificate to intercept a session. Which client-side control most directly defeats the attack?', 'disabling the browser''s certificate checks', 'proper certificate validation against a trusted certificate store', 'adding the site to the browser''s cache', 'using a shared password for the site', 'B', 'Validating the certificate against trusted roots rejects the self-signed certificate and blocks the impersonation.', 'ADVANCED', 3, 'MCQ', 1),
(5903, 167, 'Why is TLS 1.0 now widely considered unsafe?', 'it encrypts traffic too strongly', 'it requires hardware tokens', 'it relies on weak ciphers and known weaknesses such as BEAST and weak CBC modes', 'it does not use certificates at all', 'C', 'TLS 1.0 supports outdated ciphers and has documented cryptographic weaknesses, so modern standards require TLS 1.2 or newer.', 'ADVANCED', 3, 'MCQ', 1),
(5904, 167, 'What is a man-in-the-middle (MITM) attack against TLS primarily mitigated by?', 'stronger passwords', 'larger file uploads', 'faster internet connections', 'verifying the server''s identity through trusted certificates', 'D', 'Certificate validation lets the client confirm the server''s identity, making it impossible for the interceptor to pose as the server.', 'ADVANCED', 3, 'MCQ', 1),
(5905, 167, 'A team must transfer a very large database backup securely between two data centers while verifying the file is unchanged. Which approach best meets both goals?', 'SFTP/SCP transfer followed by comparing SHA-256 hashes', 'plain HTTP download', 'FTP with no encryption', 'sending the file by email', 'A', 'SSH-based transfer provides encryption, and comparing cryptographic hashes verifies integrity of the transferred file.', 'ADVANCED', 3, 'MCQ', 1),
(5906, 167, 'Two branch offices must communicate securely across the public internet. Which solution is most appropriate?', 'public DNS', 'a site-to-site VPN between the offices'' gateways', 'a shared email account', 'open telnet sessions', 'B', 'A site-to-site VPN encrypts all traffic flowing between the two office networks over the untrusted internet.', 'ADVANCED', 3, 'MCQ', 1),
(5907, 167, 'What is the purpose of the Online Certificate Status Protocol (OCSP)?', 'to encrypt the certificate', 'to generate new certificates', 'to check in real time whether a certificate has been revoked', 'to assign IP addresses', 'C', 'OCSP lets clients query a responder to confirm a certificate is still valid and has not been revoked.', 'ADVANCED', 3, 'MCQ', 1),
(5908, 167, 'Why is the HTTP Strict Transport Security (HSTS) header recommended for secure websites?', 'it speeds up page rendering', 'it adds extra storage', 'it logs all user activity', 'it forces browsers to use HTTPS and prevents protocol downgrade attacks', 'D', 'HSTS instructs browsers to only ever use HTTPS for a domain, blocking downgrades to insecure HTTP.', 'ADVANCED', 3, 'MCQ', 1),
(5909, 167, 'The private key of a widely trusted certificate authority is compromised. What is the most serious consequence?', 'attackers can issue fraudulent certificates that clients will trust', 'all web traffic becomes unreadable', 'browsers permanently lose all connectivity', 'the CA can no longer be hacked again', 'A', 'With the CA''s private key, an attacker can mint valid certificates for any domain, breaking the chain of trust.', 'ADVANCED', 3, 'MCQ', 1),
(5910, 167, 'What is the main benefit of TLS session resumption?', 'it weakens encryption for speed', 'it skips part of the handshake so repeated connections are faster while remaining secure', 'it lets servers see plaintext traffic', 'it removes the need for certificates', 'B', 'Session resumption reuses agreed session parameters, reducing handshake latency for repeat connections without weakening security.', 'ADVANCED', 3, 'MCQ', 1),
(5911, 168, 'What is the primary function of the Nmap tool?', 'network discovery and port scanning', 'compiling C programs', 'managing database backups', 'rendering web pages', 'A', 'Nmap scans networks to discover hosts and open ports, revealing what services are exposed.', 'BEGINNER', 1, 'MCQ', 1),
(5912, 168, 'Which type of tool is designed to discover open ports and running services on a host?', 'a packet analyzer', 'a port scanner', 'a source code editor', 'a load balancer', 'B', 'A port scanner probes a target''s ports to identify which services are listening and reachable.', 'BEGINNER', 1, 'MCQ', 1),
(5913, 168, 'Which tool is commonly used to intercept and modify web application traffic during testing?', 'Wireshark', 'Nmap', 'Burp Suite', 'Ping', 'C', 'Burp Suite acts as an intercepting proxy, letting testers view and modify HTTP requests and responses.', 'BEGINNER', 1, 'MCQ', 1),
(5914, 168, 'What does a vulnerability scanner do?', 'encrypts the hard drive', 'automatically detects known vulnerabilities and misconfigurations in systems', 'blocks all incoming email', 'speeds up the network', 'D', 'A vulnerability scanner checks systems against a database of known weaknesses and reports the findings.', 'BEGINNER', 1, 'MCQ', 1),
(5915, 168, 'What is Wireshark primarily used for?', 'capturing and analyzing network packets', 'performing SQL queries', 'backing up files to the cloud', 'testing CPU speed', 'A', 'Wireshark captures packets on a network interface and lets analysts inspect their contents.', 'BEGINNER', 1, 'MCQ', 1),
(5916, 168, 'Why do attackers and defenders perform port scans?', 'to increase network bandwidth', 'to identify which network services are open and potentially exposed', 'to fix hardware failures', 'to compress log files', 'B', 'Port scans reveal listening services, which are the entry points that may be probed for weaknesses.', 'BEGINNER', 1, 'MCQ', 1),
(5917, 168, 'Which tool is commonly used to audit password strength by attempting to crack password hashes?', 'John the Ripper', 'Nmap', 'Wireshark', 'Netstat', 'C', 'John the Ripper tests password hashes against wordlists and attack modes to reveal weak passwords.', 'BEGINNER', 1, 'MCQ', 1),
(5918, 168, 'What does a Security Information and Event Management (SIEM) system do?', 'detects physical intruders', 'manages virtual machines', 'performs port scans', 'collects and correlates logs and events from many sources', 'D', 'A SIEM aggregates security logs and events so analysts can detect patterns and respond to threats.', 'BEGINNER', 1, 'MCQ', 1),
(5919, 168, 'Which Linux command-line tool is most commonly used to scan for open ports?', 'nmap', 'grep', 'ls', 'mkdir', 'A', 'nmap is the standard command-line port scanner available on Linux and other platforms.', 'BEGINNER', 1, 'MCQ', 1),
(5920, 168, 'What does an intrusion detection system (IDS) do?', 'encrypts all traffic', 'monitors network or system activity for suspicious behavior and alerts', 'rebuilds operating systems', 'allocates disk space', 'B', 'An IDS inspects activity for signs of attack and raises alerts when suspicious behavior is detected.', 'BEGINNER', 1, 'MCQ', 1),
(5921, 168, 'A scan reports that port 22 is open on a server. Which service most likely runs on it?', 'HTTP', 'DNS', 'SSH', 'SMTP', 'C', 'Port 22 is the well-known port for SSH, used for secure remote administration.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5922, 168, 'A web application test indicates a possible SQL injection. Which tool is designed to confirm and automate exploitation of such flaws in a controlled lab?', 'John the Ripper', 'Wireshark', 'Nessus', 'sqlmap', 'D', 'sqlmap automates detection and exploitation of SQL injection vulnerabilities against database-backed applications.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5923, 168, 'Which Nmap scan is used to discover which hosts on a subnet are up?', 'a ping sweep such as nmap -sP', 'a full database scan', 'an SSL cipher check', 'a source code review', 'A', 'A ping sweep probes hosts for responses, quickly identifying which addresses are alive on the network.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5924, 168, 'Which framework provides a standard severity score for vulnerabilities found during scanning?', 'TCP/IP', 'CVSS', 'OWASP Top 10', 'Wireshark', 'B', 'The Common Vulnerability Scoring System (CVSS) assigns numerical scores that rank vulnerability severity.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5925, 168, 'An analyst captured traffic and wants to view only HTTP requests. Which Wireshark display filter achieves this?', 'tcp.port == 443', 'dns', 'http', 'ip.addr == 192.168.1.1', 'C', 'The display filter http shows only packets belonging to HTTP application traffic.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5926, 168, 'Which tool is commonly used to test SSH logins by trying many username and password combinations?', 'Wireshark', 'Hydra', 'Nmap', 'OpenSSL', 'D', 'Hydra is a network login cracker that can brute-force credentials for protocols such as SSH.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5927, 168, 'A SIEM raises an alert because a host logged many failed password attempts in a few minutes. What is this pattern called?', 'a brute-force attack', 'a denial of service', 'a phishing campaign', 'an SQL injection', 'A', 'Rapid repeated login failures are the classic signature of a brute-force attack guessing credentials.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5928, 168, 'Which scan sends a SYN packet and only completes the handshake if the port is open?', 'a full TCP connect scan', 'a SYN or half-open scan', 'an XMAS scan of UDP', 'a ping sweep', 'B', 'A SYN scan sends SYN and watches for SYN-ACK, never finishing the handshake, which is stealthier and faster.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5929, 168, 'What is the key difference between an IDS and an IPS?', 'they are identical in function', 'an IDS can block traffic', 'an IDS detects and alerts while an IPS can actively block malicious traffic', 'an IPS only records traffic', 'C', 'An IDS is passive and alerts, while an IPS sits inline and can block or drop malicious packets in real time.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5930, 168, 'Which category of tool analyzes source code for security flaws without running the program?', 'dynamic application security testing (DAST)', 'fuzzing', 'port scanning', 'static application security testing (SAST)', 'D', 'SAST tools parse source code and look for patterns that indicate vulnerabilities before the application runs.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5931, 168, 'An enterprise must continuously identify unpatched vulnerabilities across 5000 endpoints. Which approach is most scalable and reliable?', 'deploy agent-based vulnerability scanning with centralized reporting', 'ask each employee to run manual scans monthly', 'scan the endpoints only once a year', 'rely on antivirus signatures alone', 'A', 'Agent-based scanners report continuously to a central console, giving complete, up-to-date coverage across thousands of endpoints.', 'ADVANCED', 3, 'MCQ', 1),
(5932, 168, 'A scanner flags a service whose version has no known CVE. What is the best next step?', 'ignore the finding permanently', 'verify the version and configuration manually and monitor for future advisories', 'uninstall the service immediately', 'decrease scan frequency to once a year', 'B', 'Without a CVE, the finding needs manual verification and ongoing monitoring because new vulnerabilities may be disclosed later.', 'ADVANCED', 3, 'MCQ', 1),
(5933, 168, 'A vulnerability scanner produces many false positives. How should the team respond?', 'delete the scanner', 'triple the scan frequency', 'triage each alert, verify findings manually and tune the scanner''s rules', 'block all traffic from the scanner', 'C', 'Triaging and verifying alerts reduces false positives, and tuning scanner configuration improves future accuracy.', 'ADVANCED', 3, 'MCQ', 1),
(5934, 168, 'Which scanning technique can help evade a network firewall that filters complete packets?', 'scanning during business hours only', 'using only TCP connect scans', 'scanning a single port', 'sending fragmented packets that the firewall fails to inspect completely', 'D', 'Fragmentation splits packets into pieces that some firewalls cannot reassemble and inspect, helping the scan slip through.', 'ADVANCED', 3, 'MCQ', 1),
(5935, 168, 'A tester wants to verify an insecure direct object reference (IDOR) in a web application. Which approach is most effective?', 'manual testing with two accounts and a proxy such as Burp Suite', 'running a port scan', 'checking TLS certificates', 'measuring network latency', 'A', 'IDOR testing compares responses across two accounts while manipulating object identifiers, which a proxy makes easy.', 'ADVANCED', 3, 'MCQ', 1),
(5936, 168, 'What is the primary purpose of a honeypot?', 'to speed up production traffic', 'to deceive attackers and collect intelligence about their methods', 'to replace the company firewall', 'to store backups', 'B', 'A honeypot is a decoy system designed to attract attackers so defenders can observe their techniques.', 'ADVANCED', 3, 'MCQ', 1),
(5937, 168, 'Which type of tool continuously checks cloud configurations for risky misconfigurations such as publicly open buckets?', 'a CASB only', 'a web application firewall', 'a cloud security posture management (CSPM) tool', 'a network load balancer', 'C', 'CSPM tools assess cloud accounts against best-practice benchmarks and flag misconfigurations and compliance drift.', 'ADVANCED', 3, 'MCQ', 1),
(5938, 168, 'How does DAST differ from SAST in application security testing?', 'DAST analyzes source code, SAST tests the running app', 'they are the same', 'DAST is only for mobile apps', 'DAST tests the running application over its interfaces while SAST analyzes source code', 'D', 'DAST exercises a deployed application like an attacker would, whereas SAST reviews code statically without execution.', 'ADVANCED', 3, 'MCQ', 1),
(5939, 168, 'Which framework is commonly used by red teams to develop, test and deliver exploits against targets?', 'Metasploit', 'Wireshark', 'OpenVPN', 'Tripwire', 'A', 'Metasploit provides modules and payloads that red teams use to simulate realistic attacks during authorized testing.', 'ADVANCED', 3, 'MCQ', 1),
(5940, 168, 'A team''s scans overload the network during business hours. Which mitigation balances coverage and stability?', 'stop scanning entirely', 'schedule scans during maintenance windows and throttle scan rate', 'scan only one endpoint', 'run scans every hour at full speed', 'B', 'Scheduling scans in off-peak windows and throttling the rate reduces impact while still providing coverage.', 'ADVANCED', 3, 'MCQ', 1),
(5941, 169, 'What is a security incident?', 'a security event that harms or threatens the confidentiality, integrity or availability of an asset', 'any routine system update', 'a scheduled maintenance task', 'a normal user login', 'A', 'A security incident is an event with negative impact, such as an intrusion or breach, that requires a response.', 'BEGINNER', 1, 'MCQ', 1),
(5942, 169, 'Which phase comes first in the incident response lifecycle?', 'eradication', 'recovery', 'preparation', 'containment', 'B', 'Preparation comes first: policies, tools and trained teams are readied before any incident occurs.', 'BEGINNER', 1, 'MCQ', 1),
(5943, 169, 'What does containment mean during incident response?', 'deleting all logs', 'preventing the incident from spreading further', 'shutting down the business', 'hiding the incident from management', 'C', 'Containment limits the scope and damage of an incident by isolating affected systems and stopping the spread.', 'BEGINNER', 1, 'MCQ', 1),
(5944, 169, 'What does eradication involve?', 'restoring backups', 'removing the threat and its root cause from the environment', 'notifying the press', 'archiving logs', 'D', 'Eradication removes malware, backdoors and the root cause so the environment is clean.', 'BEGINNER', 1, 'MCQ', 1),
(5945, 169, 'What is the goal of the recovery phase?', 'returning systems to normal, verified operation', 'finding who caused the incident', 'deleting evidence', 'rewriting the security policy', 'A', 'Recovery restores affected services and verifies they operate normally and safely before going back into production.', 'BEGINNER', 1, 'MCQ', 1),
(5946, 169, 'What is a security event?', 'an incident that always causes damage', 'any observable occurrence that is relevant to the security of a system', 'a scheduled backup', 'a hardware purchase', 'B', 'A security event is any observable occurrence that might relate to security, which may or may not become an incident.', 'BEGINNER', 1, 'MCQ', 1),
(5947, 169, 'What is the purpose of an incident response plan?', 'to increase network speed', 'to document employee salaries', 'to define roles, procedures and communication for handling incidents', 'to replace the firewall', 'C', 'An IR plan lays out who does what, the steps to follow and how to communicate during an incident.', 'BEGINNER', 1, 'MCQ', 1),
(5948, 169, 'What is an incident response playbook?', 'a list of employee holidays', 'a hardware inventory', 'a marketing strategy', 'a predefined procedure for handling a specific type of incident', 'D', 'Playbooks give responders repeatable step-by-step procedures tailored to incident types such as phishing or ransomware.', 'BEGINNER', 1, 'MCQ', 1),
(5949, 169, 'During an incident, who should typically be notified first?', 'the designated incident response team or on-call contact', 'every employee at once', 'the company''s social media followers', 'external attackers', 'A', 'The IR team must be engaged first so a trained group can triage and coordinate the response.', 'BEGINNER', 1, 'MCQ', 1),
(5950, 169, 'Why is preserving evidence important during an incident?', 'to make the systems faster', 'to keep evidence intact for analysis and any legal proceedings', 'to hide the incident', 'to reduce storage costs', 'B', 'Preserving evidence in a defensible way ensures analysis is accurate and evidence may be admissible in court.', 'BEGINNER', 1, 'MCQ', 1),
(5951, 169, 'An alert shows malware running on a production server. What is the first action the responder should take?', 'format the entire server immediately', 'announce the breach publicly', 'isolate the host to contain the spread', 'delete the company firewall logs', 'C', 'Isolating the infected host stops the malware from moving to other systems while evidence is preserved.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5952, 169, 'Why must an incident responder maintain a documented chain of custody?', 'to improve network speed', 'to track who pays for tools', 'to shorten the investigation', 'to prove that evidence was not altered or mishandled', 'D', 'A documented chain of custody shows who handled evidence and that it remained unchanged, which is essential if it is used in court.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5953, 169, 'For a compromised Linux server, which evidence is most valuable for understanding the attack while it may still be running?', 'a memory image and system logs', 'only the marketing files', 'the screen resolution settings', 'a list of installed fonts', 'A', 'A memory image captures running processes and connections, and logs record system activity, together revealing attacker behavior.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5954, 169, 'Ransomware begins encrypting files on several shared drives. Which immediate action best limits the damage?', 'pay the ransom immediately', 'disconnect affected systems and shares from the network', 'continue working to watch what happens', 'email every employee asking them to click attachments', 'B', 'Disconnecting the affected systems stops the encryption from spreading to additional files and shares.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5955, 169, 'What is the key difference between a security event and a security incident?', 'an event never involves security', 'an incident is always caused by an insider', 'an incident is an event with a negative impact that requires a response', 'they are identical terms', 'C', 'Every incident is an event, but an incident specifically has adverse security impact requiring a formal response.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5956, 169, 'A phishing email leads to a user''s credentials being stolen. What is the most direct containment step?', 'buy a new laptop', 'change nothing and wait', 'train only new employees', 'reset the credentials and revoke active sessions', 'D', 'Resetting the password and terminating active sessions invalidates the stolen credentials immediately.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5957, 169, 'What is the purpose of a lessons learned review after an incident?', 'to identify improvements to processes and prevent recurrence', 'to assign blame publicly', 'to delete incident data', 'to increase system load', 'A', 'Lessons learned capture what worked and what failed so future detection and response improve.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5958, 169, 'Which metric measures how long it takes to restore service after an incident begins?', 'MTTD', 'MTTR', 'CPU usage', 'Uptime of the firewall', 'B', 'Mean Time To Recover (MTTR) tracks the duration from incident start to restored service.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5959, 169, 'When should an organization notify affected customers about a breach?', 'never, to avoid attention', 'after deleting all evidence', 'according to its incident plan and legal or regulatory obligations after assessing the impact', 'only if a reporter asks', 'C', 'Notification timing follows the organization''s plan and applicable laws, which often require prompt, accurate disclosure.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5960, 169, 'Which artifact most directly reveals when a file was created, modified or accessed on a compromised workstation?', 'the printer queue', 'file system timestamps', 'the wallpaper image', 'the keyboard language', 'D', 'File system timestamps record creation, modification and access times, which help reconstruct attacker activity.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5961, 169, 'An organization fears an advanced persistent threat (APT) and wants to improve its response capability. Which preparation is most effective?', 'develop detection playbooks, consume threat intelligence and run a trained, rehearsed IR team', 'buy more monitors for the SOC', 'increase the number of coffee machines', 'keep a single expert on call 24/7 with no plan', 'A', 'Playbooks, threat intel and rehearsed teams let responders detect and react to APT activity quickly and consistently.', 'ADVANCED', 3, 'MCQ', 1),
(5962, 169, 'A cloud instance has been compromised to mine cryptocurrency. What is the most appropriate response?', 'keep the instance running to watch it', 'make a forensic snapshot, terminate the instance and rotate any credentials it used', 'simply reboot the instance', 'leave the mining process running', 'B', 'Preserving a snapshot for forensics, terminating the infected instance and rotating credentials removes the compromise and secures the account.', 'ADVANCED', 3, 'MCQ', 1),
(5963, 169, 'An attacker is actively operating inside a network during incident response. Why might the team deliberately avoid immediately killing the attacker''s process?', 'to reduce electric bills', 'to keep the network slow', 'to observe the attacker''s techniques and gather intelligence before eviction', 'because process names cannot be stopped', 'C', 'Observing the attacker''s tools and movements reveals their TTPs, improving detection and preventing recurrence after eviction.', 'ADVANCED', 3, 'MCQ', 1),
(5964, 169, 'A worm is spreading laterally between network segments. Which containment priority is correct?', 'eradicate first, then isolate', 'isolate infected segments first to stop the spread, then eradicate the worm', 'leave all segments connected', 'disable all monitoring', 'D', 'Stopping the spread through network isolation comes first, because eradication is far harder while the worm keeps infecting.', 'ADVANCED', 3, 'MCQ', 1),
(5965, 169, 'An insider is suspected of stealing customer data. Which evidence is most probative for confirming the exfiltration?', 'access logs showing downloads of large volumes of sensitive files', 'the employee''s meeting schedules', 'the color of the employee''s badge', 'the number of years of employment', 'A', 'Access logs that link the insider''s account to bulk downloads of sensitive files directly demonstrate the exfiltration.', 'ADVANCED', 3, 'MCQ', 1),
(5966, 169, 'A legitimate user account is used in a phishing campaign to send malicious internal emails. How should the team detect and contain this?', 'ask employees to forward the emails to everyone', 'disable the account, inspect mailbox rules and look for auto-forwarding or abuse', 'delete all mailboxes', 'do nothing because the sender is legitimate', 'B', 'Disabling the account and checking for forwarding rules stops the abuse and reveals how the attacker controls the mailbox.', 'ADVANCED', 3, 'MCQ', 1),
(5967, 169, 'In cloud incident response, why are immutable snapshots particularly valuable?', 'they cost nothing', 'they speed up the network', 'they preserve evidence in a state that cannot be altered', 'they replace the need for logs', 'C', 'Immutable snapshots cannot be modified, so they provide trustworthy evidence that attackers cannot tamper with.', 'ADVANCED', 3, 'MCQ', 1),
(5968, 169, 'Before an organization can declare recovery complete after containing a breach, which step must happen?', 'delete the forensic images', 'rehire the IR team', 'turn off all monitoring', 'verify eradication, restore from clean backups and monitor for signs of reinfection', 'D', 'Recovery is complete only after the threat is confirmed gone, systems are restored cleanly and monitoring confirms no reinfection.', 'ADVANCED', 3, 'MCQ', 1),
(5969, 169, 'How does the MITRE ATT&CK framework assist incident responders?', 'it maps observed attacker actions to known tactics, techniques and procedures', 'it encrypts all logs', 'it assigns IP addresses', 'it predicts the stock market', 'A', 'ATT&CK catalogs adversary behavior so responders can classify activity, detect patterns and plan responses by technique.', 'ADVANCED', 3, 'MCQ', 1),
(5970, 169, 'Logs show an attacker reached a database using an application account with far more privileges than needed. What is the most likely root cause?', 'the database was too fast', 'over-privileged application credentials were exposed and used', 'the network had too much bandwidth', 'the database had no indices', 'B', 'An over-privileged app account means a single credential compromise yields excessive access, which is the root cause to fix.', 'ADVANCED', 3, 'MCQ', 1),
(5971, 170, 'What does the abbreviation PII stand for?', 'Personally Identifiable Information', 'Private Internet Infrastructure', 'Public Identity Index', 'Personal Identity Image', 'A', 'PII is information that can identify an individual, such as a name, email address or national ID number.', 'BEGINNER', 1, 'MCQ', 1),
(5972, 170, 'What does encrypting data at rest primarily protect against?', 'slow internet speeds', 'unauthorized access to stored data such as disks or backups', 'losing the encryption key', 'users forgetting passwords', 'B', 'Encryption at rest ensures that even if storage media are stolen, the data cannot be read without the key.', 'BEGINNER', 1, 'MCQ', 1),
(5973, 170, 'What is a data breach?', 'a scheduled backup', 'a routine software update', 'unauthorized access, disclosure or theft of data', 'a normal database query', 'C', 'A data breach occurs when protected data is accessed or exposed without authorization.', 'BEGINNER', 1, 'MCQ', 1),
(5974, 170, 'Which regulation is the main law governing personal data protection in the European Union?', 'SOX', 'HIPAA', 'PCI DSS', 'GDPR', 'D', 'The General Data Protection Regulation (GDPR) governs how personal data of EU individuals is processed.', 'BEGINNER', 1, 'MCQ', 1),
(5975, 170, 'What is data classification?', 'assigning sensitivity labels such as public, internal or confidential to data', 'compressing data to save space', 'deleting old data automatically', 'transferring data between servers', 'A', 'Data classification groups data by sensitivity and criticality, guiding how it should be protected.', 'BEGINNER', 1, 'MCQ', 1),
(5976, 170, 'What is data masking?', 'deleting production data', 'replacing sensitive data with realistic but fictitious substitutes', 'encrypting data with a public key', 'storing data on tape', 'B', 'Data masking hides the original values by substituting fake values, allowing safe use in non-production environments.', 'BEGINNER', 1, 'MCQ', 1),
(5977, 170, 'What is tokenization in data protection?', 'breaking data into small packets', 'encrypting data twice', 'replacing sensitive values with non-sensitive placeholders called tokens', 'storing data in the cloud', 'C', 'Tokenization swaps sensitive data for tokens; the original values are stored separately and securely.', 'BEGINNER', 1, 'MCQ', 1),
(5978, 170, 'What is the role of a key management service (KMS)?', 'managing user passwords', 'monitoring network traffic', 'backing up virtual machines', 'centrally creating, storing and rotating encryption keys', 'D', 'A KMS centralizes the lifecycle of encryption keys, including creation, storage, rotation and revocation.', 'BEGINNER', 1, 'MCQ', 1),
(5979, 170, 'What does the principle of data minimization require?', 'collecting only the data that is necessary for a stated purpose', 'collecting as much data as possible', 'deleting all data immediately', 'sharing data with all partners', 'A', 'Data minimization means an organization collects and keeps only what it genuinely needs, reducing risk.', 'BEGINNER', 1, 'MCQ', 1),
(5980, 170, 'What is a privacy policy?', 'a firewall rule', 'a document that explains how an organization collects, uses and protects personal data', 'an encryption algorithm', 'a backup schedule', 'B', 'A privacy policy informs individuals about data collection, usage, storage and their rights.', 'BEGINNER', 1, 'MCQ', 1),
(5981, 170, 'Under GDPR, what must an organization establish before processing personal data?', 'a marketing budget', 'a data center', 'a lawful basis such as consent or legitimate interest', 'permission from competitors', 'C', 'GDPR requires every processing activity to rely on a lawful basis, such as consent, contract or legal obligation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5982, 170, 'How long should an organization keep personal data under GDPR?', 'forever', 'for ten years minimum', 'as long as the employee wants', 'no longer than necessary for the purpose it was collected', 'D', 'GDPR''s storage limitation principle requires deletion once data is no longer needed for its original purpose.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5983, 170, 'A data loss prevention (DLP) tool blocks an email that contains a credit card number. What type of control is this?', 'a data loss prevention control that stops sensitive data leaving the network', 'a firewall rule that blocks websites', 'an antivirus signature', 'a password policy', 'A', 'DLP monitors and blocks transmissions of sensitive data such as card numbers to prevent exfiltration.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5984, 170, 'A developer needs realistic data for testing without exposing real customer PII. Which technique is appropriate?', 'use real production data', 'data masking or desensitization', 'generate random names only', 'store data in plaintext', 'B', 'Data masking substitutes realistic fake values, so testers work with useful data while real PII stays protected.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5985, 170, 'What is the main difference between encryption and hashing?', 'they are identical', 'hashing is reversible with a key', 'encryption is reversible with the correct key while hashing is one-way', 'encryption is only for passwords', 'C', 'Encryption can be reversed with the key, but hashing is a one-way function that cannot be reversed to recover the input.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5986, 170, 'Which practice is the correct way to store user passwords?', 'store them in plaintext', 'store them encrypted with a reversible cipher', 'store unsalted hashes only', 'store salted, slow hashes such as bcrypt or argon2', 'D', 'Salted adaptive hashes resist brute force and rainbow tables, protecting passwords even if the database leaks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5987, 170, 'What does the GDPR ''right to be forgotten'' allow a data subject to do?', 'request deletion of their personal data', 'request free hosting', 'change their email address', 'object to receiving marketing once per year', 'A', 'The right to erasure lets individuals ask organizations to delete their personal data under specified conditions.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5988, 170, 'Why is it a best practice to rotate encryption keys periodically?', 'to make the system slower', 'to limit the amount of data compromised if a key leaks', 'to consume more storage', 'to avoid using KMS', 'B', 'Rotation limits the exposure window of a leaked key, since newer data is protected by fresh keys.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5989, 170, 'A laptop containing customer data is stolen. Which control could have prevented exposure of that data?', 'a longer boot password for the user', 'full-disk encryption on the laptop', 'a privacy policy document', 'an email disclaimer', 'C', 'Full-disk encryption ensures the stolen drive''s data remains unreadable without the encryption key.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5990, 170, 'What is the purpose of an audit log for data access?', 'to speed up queries', 'to hide who accessed data', 'to record who accessed what data and when', 'to compress the database', 'D', 'Audit logs capture a record of data access, enabling accountability and investigation of misuse.', 'INTERMEDIATE', 2, 'MCQ', 1),
(5991, 170, 'An organization must encrypt data in a database while keeping the encryption keys separate from the database administrators. Which approach achieves this?', 'client-side encryption using keys managed by a KMS', 'letting the DB store keys next to the data', 'encrypting only the backups', 'storing keys in the application config file', 'A', 'Client-side encryption with KMS-managed keys keeps encryption separate from the DB, so DBAs cannot read the data or keys.', 'ADVANCED', 3, 'MCQ', 1),
(5992, 170, 'A company must keep customer data within a specific country to satisfy legal requirements. Which concept does this reflect?', 'data masking', 'data sovereignty or data residency', 'data tokenization', 'data analytics', 'B', 'Data sovereignty requires data to remain within the borders of a jurisdiction in line with local laws.', 'ADVANCED', 3, 'MCQ', 1),
(5993, 170, 'A company discovers a breach affecting 200 EU customers'' personal data. Under GDPR, what must it do?', 'nothing unless asked', 'delete the affected accounts and stop', 'notify the supervisory authority within 72 hours if the risk is significant', 'publicly name every customer', 'C', 'GDPR mandates notifying the supervisory authority within 72 hours when a breach poses a risk to individuals.', 'ADVANCED', 3, 'MCQ', 1),
(5994, 170, 'How does envelope encryption work in a KMS?', 'the same key encrypts everything forever', 'each file is stored without a key', 'keys are printed on paper', 'a data key encrypts the data and a master key encrypts that data key', 'D', 'Envelope encryption wraps a data key with a master key, so large data uses efficient data keys while the master key protects them.', 'ADVANCED', 3, 'MCQ', 1),
(5995, 170, 'Which password storage scheme is the strongest for a large user database?', 'a slow adaptive hash such as bcrypt or argon2 with a unique salt per user', 'MD5 with no salt', 'a reversible cipher', 'plaintext in a hidden file', 'A', 'Slow adaptive hashes with unique salts are deliberately expensive to crack, even with large-scale offline attacks.', 'ADVANCED', 3, 'MCQ', 1),
(5996, 170, 'A retailer that stores or processes cardholder data must comply with which industry standard?', 'ISO 27001', 'PCI DSS', 'HIPAA', 'COBIT', 'B', 'The Payment Card Industry Data Security Standard (PCI DSS) governs how cardholder data must be protected.', 'ADVANCED', 3, 'MCQ', 1),
(5997, 170, 'Data that has been de-identified but could be re-linked to individuals with additional information is called what?', 'anonymized data', 'public data', 'pseudonymized data', 'aggregated data', 'C', 'Pseudonymization replaces identifiers with codes that can be re-linked using separate information, so it is not truly anonymous.', 'ADVANCED', 3, 'MCQ', 1),
(5998, 170, 'An analyst must compute statistics on sensitive data without ever viewing individual values. Which privacy technique enables this?', 'publishing the raw dataset', 'sending the raw data by email', 'dropping the analysis entirely', 'differential privacy applied to the analysis', 'D', 'Differential privacy adds calibrated noise so aggregate results are useful while individual records remain hidden.', 'ADVANCED', 3, 'MCQ', 1),
(5999, 170, 'Which control most effectively prevents a cloud storage bucket containing PII from being accidentally exposed publicly?', 'blocking public access at the bucket and organizational level plus enforcing policies', 'naming the bucket with an unusual string', 'storing data in a nested folder', 'setting the bucket to a lower storage tier', 'A', 'Blocking public access at the organization level, combined with policies, stops accidental public exposure of sensitive buckets.', 'ADVANCED', 3, 'MCQ', 1),
(6000, 170, 'What is the purpose of a data retention policy?', 'to store everything forever', 'to define how long data is kept and when it must be deleted, supporting compliance', 'to make backups fail', 'to share data with third parties', 'B', 'Retention policies specify retention periods and deletion schedules so the organization meets legal and business requirements.', 'ADVANCED', 3, 'MCQ', 1),
(6001, 171, 'What is the core idea behind Infrastructure as Code (IaC)?', 'defining and provisioning infrastructure using machine-readable definition files', 'manually configuring each server through a terminal', 'using a GUI console to click through server setup', 'purchasing physical hardware for data centers', 'A', 'IaC treats infrastructure as software by describing it in machine-readable definition files that can be versioned, reviewed, and applied consistently.', 'BEGINNER', 1, 'MCQ', 1),
(6002, 171, 'Which of the following tools is primarily used for Infrastructure as Code?', 'MySQL', 'Terraform', 'Windows Notepad', 'Microsoft Excel', 'B', 'Terraform is a dedicated IaC tool that lets teams define cloud resources in declarative configuration files and apply them automatically.', 'BEGINNER', 1, 'MCQ', 1),
(6003, 171, 'Which of the following is a major benefit of Infrastructure as Code?', 'slower environment provisioning', 'more manual steps per deployment', 'repeatable and consistent infrastructure provisioning', 'hardware costs always decrease', 'C', 'IaC makes provisioning repeatable and consistent because the same definition produces the same environment every time it is applied.', 'BEGINNER', 1, 'MCQ', 1),
(6004, 171, 'How does version control help with Infrastructure as Code?', 'it is not used with IaC', 'it only stores passwords', 'it replaces the need for any tooling', 'it allows infrastructure changes to be reviewed, tracked, and rolled back', 'D', 'Storing IaC definitions in version control records every change, supports peer review, and makes rollbacks straightforward.', 'BEGINNER', 1, 'MCQ', 1),
(6005, 171, 'What does it mean for IaC to be declarative?', 'you state the desired end state and the tool makes it happen', 'you list every exact command to run in order', 'you must reboot servers manually after each step', 'you describe how tasks run instead of what to build', 'A', 'Declarative IaC focuses on the desired end state, leaving the tool to figure out the steps needed to reach that state.', 'BEGINNER', 1, 'MCQ', 1),
(6006, 171, 'Which property ensures that running the same IaC definition again produces the same result?', 'mutability', 'idempotency', 'latency', 'locality', 'B', 'Idempotency means applying the same configuration multiple times converges to the same state without duplicating resources or side effects.', 'BEGINNER', 1, 'MCQ', 1),
(6007, 171, 'In IaC, what is an execution plan?', 'a printed hardware budget', 'a backup of the database', 'a preview of the changes the tool will make before applying them', 'a list of employees on the operations team', 'C', 'An execution plan shows the actions a tool such as Terraform will take so teams can review and approve changes before they happen.', 'BEGINNER', 1, 'MCQ', 1),
(6008, 171, 'What is the advantage of treating infrastructure definitions as code?', 'they can only be read by senior engineers', 'they become unreadable and unmaintainable', 'they cannot be shared across teams', 'they can be tested, reviewed, and automatically validated like application code', 'D', 'Infrastructure definitions gain the same benefits as application code, including automated testing, review, and validation.', 'BEGINNER', 1, 'MCQ', 1),
(6009, 171, 'What is the purpose of a state file in IaC tools?', 'it records the current deployed resources so the tool can plan changes accurately', 'it stores only the billing history', 'it logs every employee login', 'it replaces the need for a cloud account', 'A', 'The state file tracks what has actually been deployed so the tool can compute the difference between real infrastructure and the desired configuration.', 'BEGINNER', 1, 'MCQ', 1),
(6010, 171, 'Which practice is commonly used with IaC to reduce differences between environments?', 'deploying only in production', 'using the same configuration modules across development, staging, and production', 'manually changing servers after deployment', 'keeping every environment definition separate with no reuse', 'B', 'Reusing shared configuration modules across environments reduces drift and keeps environments consistent with one another.', 'BEGINNER', 1, 'MCQ', 1),
(6011, 171, 'A developer manually edits a production server to fix a bug. What is the immediate concern with this practice?', 'the fix is automatically documented', 'the change will not be captured in version control and may be overwritten by the next IaC run', 'the server will reboot automatically', 'the change is applied to all environments at once', 'C', 'Manual server edits create configuration drift because they bypass the IaC definition, and a later apply may revert them.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6012, 171, 'Your team needs to provision 50 identical EC2 instances. Which IaC approach is most appropriate?', 'creating each instance manually through the console', 'writing a document describing how to create each one', 'rebuilding the network every time', 'using a single declarative configuration with a count or for_each construct', 'D', 'A declarative configuration with count or for_each expresses the full set of 50 instances in one place and provisions them consistently.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6013, 171, 'A change is rejected in review because it would recreate a database. What IaC feature could avoid this risk?', 'lifecycle rules that prevent destruction of the resource', 'changing the password every day', 'deleting the state file', 'running apply without a plan', 'A', 'Lifecycle rules such as prevent_destroy block destructive operations on critical resources like databases during a plan and apply.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6014, 171, 'After a manual change to a resource, Terraform apply reverts it. Why?', 'Terraform prefers manual changes', 'the configuration no longer matches the deployed state, so the tool corrects it', 'the state file was deleted', 'the cloud account has insufficient permissions', 'B', 'Terraform compares the configuration to the state and corrects any drift, which is why manual edits get reverted.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6015, 171, 'You store IaC definitions in git. What is the recommended workflow for a change?', 'commit directly to main and apply immediately', 'edit production files on the server', 'merge and delete the branch', 'make a branch, submit a pull request, review, then merge and apply', 'C', 'Branches, pull requests, and review make infrastructure changes auditable and let teams catch mistakes before applying.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6016, 171, 'A team wants to reuse a VPC definition in three projects. Which approach follows IaC best practices?', 'copying the block into each project', 'recreating it by hand each time', 'ignoring the duplication', 'refactoring it into a shared module with input parameters', 'D', 'Refactoring reusable pieces into a parameterized module reduces duplication and keeps the source of truth in one place.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6017, 171, 'During an IaC migration, the tool cannot delete a resource it no longer manages. What does this usually indicate?', 'the resource was created outside the tool and must be imported', 'the tool is broken', 'the cloud provider is down', 'the state file is too large', 'A', 'Resources created out of band need to be imported into the state so the tool can begin managing them properly.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6018, 171, 'Which team practice reduces the chance of destructive mistakes when using IaC?', 'running apply directly in production with no review', 'always planning and reviewing the diff before applying', 'deleting old state files often', 'using the same credentials everywhere', 'B', 'Reviewing the plan output before applying lets teams spot destructive or unwanted changes such as resource recreation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6019, 171, 'An environment is failing because it was built with an outdated module version. How could this have been avoided?', 'pin and upgrade module versions deliberately', 'always use the newest version instantly', 'never use modules', 'deploy only in production', 'C', 'Pinning module versions and upgrading them intentionally through review keeps environments reproducible and predictable.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6020, 171, 'What should you do when a teammate changed infrastructure directly in the cloud instead of editing the IaC code?', 'keep the manual change and update no files', 'delete the cloud account', 'ignore it completely', 'revert the manual change and represent it properly in the IaC definition', 'D', 'The manual change should be reconciled with the code, either by importing it or reverting it, so the code remains the source of truth.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6021, 171, 'Your IaC pipeline failed because a module fetched from a remote registry changed without notice. Which mitigation best addresses supply chain risk?', 'pin the module to an exact version and checksum, and review upgrades', 'disable the internet on build servers', 'recreate the state file daily', 'store all modules on a local desktop', 'A', 'Pinning exact versions and checksums protects against unexpected upstream changes and is a core IaC supply chain control.', 'ADVANCED', 3, 'MCQ', 1),
(6022, 171, 'A team needs different infrastructure in production versus development but shared logic. Which design is best?', 'write entirely separate definitions with copied logic', 'use a single module with variables that parameterize the differences', 'maintain two states with no shared code', 'deploy development using production settings', 'B', 'Parameterized modules let one source of truth serve multiple environments while variables express environment-specific values.', 'ADVANCED', 3, 'MCQ', 1),
(6023, 171, 'Applying IaC recreates your app instances during every deploy, causing downtime. Which strategy avoids this?', 'stop using IaC', 'delete the instance definitions', 'use rolling updates or blue-green deployment patterns', 'apply only at midnight', 'C', 'Rolling updates and blue-green patterns replace instances without a full cutover, keeping the service available during changes.', 'ADVANCED', 3, 'MCQ', 1),
(6024, 171, 'Your team stores state files in a local folder shared over email. What is the most important reason this is dangerous?', 'it makes plans slower', 'it uses too much disk', 'it is against cloud provider terms', 'state can become stale and corrupted without locking, and it may expose sensitive values', 'D', 'Shared state without locking causes corruption and data races, and state often contains sensitive values that need protected remote storage.', 'ADVANCED', 3, 'MCQ', 1),
(6025, 171, 'A senior engineer wants to codify security guardrails so developers cannot create publicly open buckets. Which IaC approach is most effective?', 'enforce policy as code with automated checks in the pipeline', 'ask developers politely to be careful', 'rotate the API keys weekly', 'review every bucket manually once a month', 'A', 'Policy as code runs automated checks against every change, blocking violations at merge time rather than relying on manual vigilance.', 'ADVANCED', 3, 'MCQ', 1),
(6026, 171, 'During a disaster recovery test, the team discovers recovery takes eight hours. How should IaC help improve this?', 'it cannot help with recovery', 'versioned, tested IaC definitions let teams rebuild infrastructure in minutes instead of manually', 'delete the disaster recovery plan', 'increase server RAM', 'B', 'Because environments are defined as code, teams can rebuild them quickly and consistently, drastically reducing recovery time.', 'ADVANCED', 3, 'MCQ', 1),
(6027, 171, 'Your IaC definition works in staging but fails in production because a resource name already exists globally. Which practice best prevents this class of error?', 'ignore the error', 'create resources manually in production', 'rename nothing', 'use deterministic, environment-scoped naming conventions and unique suffixes', 'C', 'Environment-scoped naming with unique suffixes avoids global collisions and makes environments identifiable.', 'ADVANCED', 3, 'MCQ', 1),
(6028, 171, 'Which change control approach gives the strongest assurance before applying IaC in production?', 'apply changes without review', 'ask two teammates after applying', 'apply and then check logs', 'run the plan in production and approve it in a change management process with the plan diff', 'D', 'Producing and reviewing the plan as part of change management makes the exact impact visible and approvable before anything runs.', 'ADVANCED', 3, 'MCQ', 1),
(6029, 171, 'The pipeline cannot apply IaC because the deployment credential has read-only permissions. What does this indicate about least privilege?', 'least privilege is correctly configured for normal operation but the deploy role needs the specific write permissions the automation requires', 'the credential is fine', 'permissions should never be granted', 'least privilege only applies to humans', 'A', 'Least privilege still allows automation to receive the specific write scopes it needs, and the credential was mis-scoped, not over-privileged.', 'ADVANCED', 3, 'MCQ', 1),
(6030, 171, 'A vendor drops an entire cloud region and your IaC is spread across three regions. Which reliability outcome does this design support?', 'everything fails together', 'workloads can fail over to other regions because infrastructure is reproducible there', 'backups are unnecessary', 'recovery is always instant', 'B', 'Multi-region, code-defined infrastructure lets teams rebuild or re-provision workloads in surviving regions during an outage.', 'ADVANCED', 3, 'MCQ', 1),
(6031, 172, 'Which tool is HashiCorp''s open-source Infrastructure as Code tool?', 'Terraform', 'Ansible', 'Puppet', 'CloudFormation', 'A', 'Terraform is HashiCorp''s IaC tool that provisions resources across many cloud and service providers.', 'BEGINNER', 1, 'MCQ', 1),
(6032, 172, 'What is the file extension of Terraform configuration files?', 'yaml', 'tf', 'json5', 'ini', 'B', 'Terraform configuration files use the .tf extension and are written in the HashiCorp Configuration Language.', 'BEGINNER', 1, 'MCQ', 1),
(6033, 172, 'Which AWS service provides infrastructure as code for AWS resources?', 'S3', 'Lambda', 'CloudFormation', 'Route 53', 'C', 'AWS CloudFormation is AWS''s native IaC service that models and provisions AWS resources from templates.', 'BEGINNER', 1, 'MCQ', 1),
(6034, 172, 'What are Terraform configuration files written in?', 'YAML', 'XML', 'JSON only', 'HashiCorp Configuration Language (HCL)', 'D', 'Terraform uses HCL, a declarative language purpose-built for describing infrastructure.', 'BEGINNER', 1, 'MCQ', 1),
(6035, 172, 'What does the terraform init command do?', 'initializes the working directory and downloads required providers', 'destroys all resources', 'deploys resources immediately', 'starts a web server', 'A', 'terraform init prepares the working directory by downloading the provider plugins the configuration needs.', 'BEGINNER', 1, 'MCQ', 1),
(6036, 172, 'What does the terraform plan command produce?', 'a summary of costs', 'an execution plan showing what will change', 'the IP addresses of servers', 'a list of users', 'B', 'terraform plan computes and displays an execution plan describing the exact changes apply would make.', 'BEGINNER', 1, 'MCQ', 1),
(6037, 172, 'Which command applies the changes described in a Terraform plan?', 'terraform init', 'terraform destroy', 'terraform apply', 'terraform fmt', 'C', 'terraform apply carries out the changes and provisions or updates the resources defined in the configuration.', 'BEGINNER', 1, 'MCQ', 1),
(6038, 172, 'In CloudFormation, what is a template?', 'a virtual machine image', 'a Python script', 'a database backup', 'a JSON or YAML document describing resources and their properties', 'D', 'A CloudFormation template is a JSON or YAML text file that declares the AWS resources and their configuration.', 'BEGINNER', 1, 'MCQ', 1),
(6039, 172, 'What is a Terraform provider?', 'a plugin that manages resources for a specific platform or cloud', 'a virtual machine', 'a type of network', 'a file format', 'A', 'Providers are plugins that translate Terraform''s generic requests into the API calls of a specific platform such as AWS, Azure, or GCP.', 'BEGINNER', 1, 'MCQ', 1),
(6040, 172, 'Which command removes the resources managed by a Terraform configuration?', 'terraform apply', 'terraform destroy', 'terraform validate', 'terraform graph', 'B', 'terraform destroy tears down all resources tracked in the current Terraform state and configuration.', 'BEGINNER', 1, 'MCQ', 1),
(6041, 172, 'Why must a team not delete the Terraform state file by accident?', 'state is only needed for billing', 'it stores log files', 'the state file records deployed resources, and losing it can make Terraform unable to manage them', 'it is the same as the configuration', 'C', 'The state file maps configuration to real resources, so losing it makes it difficult for Terraform to update or destroy what it manages.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6042, 172, 'What does the terraform state list command do?', 'deletes all resources', 'installs new providers', 'formats the code', 'shows the resources currently tracked in the state file', 'D', 'terraform state list prints the addresses of all resources tracked in the state so you can see what Terraform manages.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6043, 172, 'A resource already exists in AWS and you want Terraform to manage it. Which feature should you use?', 'terraform import', 'terraform destroy', 'terraform plan', 'terraform graph', 'A', 'terraform import brings an existing resource into Terraform''s state so it can be managed by the configuration.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6044, 172, 'Which command checks a Terraform configuration for syntax and internal consistency?', 'terraform init', 'terraform validate', 'terraform apply', 'terraform refresh', 'B', 'terraform validate checks configuration syntax and consistency without connecting to providers or making changes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6045, 172, 'In CloudFormation, what is a stack?', 'a collection of containers', 'a single EC2 instance', 'a collection of AWS resources that are created, updated, or deleted as a unit', 'a type of template editor', 'C', 'A CloudFormation stack is the set of resources created from a template, managed together as a single unit.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6046, 172, 'A resource in Terraform no longer exists in the configuration. What happens on the next apply?', 'nothing changes', 'the resource is kept forever', 'Terraform prints an error', 'Terraform plans to destroy the resource that is no longer defined', 'D', 'When a resource is removed from the configuration, Terraform plans to destroy it unless a lifecycle rule or moved block says otherwise.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6047, 172, 'You need to create slightly different VPCs for dev and prod from one Terraform module. What should the module accept?', 'input variables', 'new providers', 'extra state files', 'hard-coded CIDRs', 'A', 'Input variables let one module be reused with different values for different environments without copying the code.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6048, 172, 'Which command sets or updates the value of an input variable for a run?', 'terraform plan -var ''env=prod''', 'terraform apply -var ''env=prod''', 'terraform init -var ''env=prod''', 'terraform destroy -var ''env=prod''', 'B', 'The -var flag on terraform apply supplies or overrides input variable values for that run.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6049, 172, 'In CloudFormation, what happens when you update a stack''s template?', 'the stack is deleted', 'the stack is duplicated', 'CloudFormation computes a change set and applies resource updates', 'AWS stops the account', 'C', 'Updating a template lets CloudFormation create a change set describing resource updates, which can then be applied.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6050, 172, 'What is the purpose of Terraform remote state storage such as an S3 backend?', 'it speeds up apply', 'it removes the need for providers', 'it makes code prettier', 'it provides safe, shared, locked state storage for teams', 'D', 'A remote backend stores state centrally with locking so multiple engineers can apply changes safely without corrupting the state.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6051, 172, 'Your team accidentally corrupts the shared remote state. Which action is the safest recovery?', 'restore the state from the most recent healthy backup and investigate the cause before re-applying', 'run destroy immediately', 'delete the state and start over', 'keep applying until it works', 'A', 'A healthy backup of the state is the safest way to restore management, and root-cause analysis prevents the corruption from recurring.', 'ADVANCED', 3, 'MCQ', 1),
(6052, 172, 'How do you share outputs such as database endpoints between Terraform configurations?', 'copy values into emails', 'use remote state data sources or outputs from one state in another', 'rebuild the database in each config', 'hard-code the endpoint', 'B', 'Remote state data sources and outputs let one configuration read values such as endpoints from another''s stored state.', 'ADVANCED', 3, 'MCQ', 1),
(6053, 172, 'A production apply unexpectedly plans to replace a database instance. What is the most likely cause?', 'a variable was not used', 'too many providers', 'a change in an immutable attribute, forcing replacement', 'the state file is missing', 'C', 'Replacement happens when an immutable attribute changes, because the resource cannot be updated in place and must be recreated.', 'ADVANCED', 3, 'MCQ', 1),
(6054, 172, 'Which strategy best handles secrets needed by Terraform without storing them in the configuration?', 'paste them into .tf files', 'hard-code them in variables', 'share them in chat', 'reference secrets from a secret manager or environment variables', 'D', 'Referencing secrets from a vault or environment variables keeps them out of version-controlled configuration files.', 'ADVANCED', 3, 'MCQ', 1),
(6055, 172, 'A state file with the same resource is locked by two engineers. What does remote locking prevent?', 'two applies writing conflicting state at the same time', 'network downtime', 'billing overruns', 'slow plans', 'A', 'Remote locking prevents concurrent applies from corrupting state by ensuring only one write happens at a time.', 'ADVANCED', 3, 'MCQ', 1),
(6056, 172, 'Your configuration uses the same module for dev and prod but prod must never be destroyed by a stray destroy. What is the strongest guard?', 'keep prod resources in the same state as dev', 'add prevent_destroy lifecycle rules and protect the prod stack', 'delete the prod state', 'use only default values', 'B', 'prevent_destroy lifecycle rules and stack protection give hard guards against accidental destruction of critical environments.', 'ADVANCED', 3, 'MCQ', 1),
(6057, 172, 'Why do many teams generate CloudFormation templates with a tool rather than writing them by hand?', 'tools make them slower', 'AWS requires a tool', 'code-generation reduces verbosity and errors in large, complex templates', 'hand-written templates are illegal', 'C', 'Generating templates reduces the boilerplate and error rate of large CloudFormation documents and makes them easier to maintain.', 'ADVANCED', 3, 'MCQ', 1),
(6058, 172, 'During a migration, some resources in a CloudFormation stack must move to a new stack. What is the recommended approach?', 'delete everything and recreate', 'leave them in place forever', 'keep duplicate stacks running', 'use resource import and refactor the stacks carefully with change sets', 'D', 'Resource import plus careful change-set review lets teams move resources between stacks without disrupting them.', 'ADVANCED', 3, 'MCQ', 1),
(6059, 172, 'Which practice prevents different engineers from applying Terraform with divergent provider versions?', 'use version constraints and a lock file committed to the repository', 'let everyone install the latest provider', 'never pin versions', 'remove providers from the config', 'A', 'Version constraints plus a committed dependency lock file ensure every run uses the same provider versions.', 'ADVANCED', 3, 'MCQ', 1),
(6060, 172, 'Your terraform apply is slow because a huge module always rebuilds its resources. Which feature helps make this incremental?', 'running destroy first', 'refactoring to expose only changed inputs and using partial configuration changes', 'deleting the state', 'using more RAM', 'B', 'Smaller modules with fewer changed inputs let apply only touch what actually changed, keeping runs incremental and fast.', 'ADVANCED', 3, 'MCQ', 1),
(6061, 173, 'What is the main purpose of configuration management tools like Ansible and Puppet?', 'to keep systems in a desired, consistent state across many machines', 'to compile application code', 'to design user interfaces', 'to print logs', 'A', 'Configuration management tools enforce a declared desired state so servers stay consistent and reproducible.', 'BEGINNER', 1, 'MCQ', 1),
(6062, 173, 'Which of the following is a configuration management tool?', 'Photoshop', 'Ansible', 'Apache Kafka', 'Nginx', 'B', 'Ansible is a popular agentless configuration management and automation tool.', 'BEGINNER', 1, 'MCQ', 1),
(6063, 173, 'What is a playbook in Ansible?', 'a virtual machine', 'a compiled binary', 'a YAML file describing tasks and hosts to configure', 'a database schema', 'C', 'Ansible playbooks are YAML documents that define the hosts and tasks for a configuration run.', 'BEGINNER', 1, 'MCQ', 1),
(6064, 173, 'What does it mean for a configuration management tool to be idempotent?', 'it always changes files', 'it requires root access every run', 'it only works once', 'running the same play repeatedly produces the same end state', 'D', 'Idempotent operations only make the changes needed to reach the desired state, so repeated runs are safe and consistent.', 'BEGINNER', 1, 'MCQ', 1),
(6065, 173, 'Which file in an Ansible project lists the hosts that playbooks manage?', 'inventory', 'playbook', 'module', 'role', 'A', 'The Ansible inventory file defines the hosts and groups that playbooks target.', 'BEGINNER', 1, 'MCQ', 1),
(6066, 173, 'What does the ansible command with the -m flag specify?', 'the inventory file', 'the module to execute on the hosts', 'the playbook to run', 'the log directory', 'B', 'The -m flag selects which module ansible runs ad hoc against hosts.', 'BEGINNER', 1, 'MCQ', 1),
(6067, 173, 'In Puppet, what is a manifest?', 'a backup file', 'a network config', 'a file that declares the desired state of resources', 'a log file', 'C', 'Puppet manifests declare resources such as packages, files, and services and their desired state.', 'BEGINNER', 1, 'MCQ', 1),
(6068, 173, 'What is the default state that Ansible assumes when connecting to remote hosts?', 'reboot each host first', 'install a full agent', 'use only FTP', 'connect over SSH using the agentless model', 'D', 'Ansible is agentless by default, connecting over SSH to push and execute tasks on managed hosts.', 'BEGINNER', 1, 'MCQ', 1),
(6069, 173, 'What does the ping module do in Ansible?', 'it verifies that the managed host is reachable and responding', 'it checks network speed', 'it sends email', 'it deletes files', 'A', 'The ping module tests connectivity to a managed host, confirming it is reachable and able to run Ansible tasks.', 'BEGINNER', 1, 'MCQ', 1),
(6070, 173, 'What is the purpose of Ansible roles?', 'they slow down playbooks', 'they organize playbooks, handlers, templates, and variables into reusable structures', 'they replace the inventory', 'they encrypt all files', 'B', 'Roles package reusable configuration content so it can be shared and reused across many playbooks and projects.', 'BEGINNER', 1, 'MCQ', 1),
(6071, 173, 'A playbook fails on a task but the change was already partially applied. What best practice prevents this?', 'ignore the error', 'run tasks out of order', 'make tasks idempotent so re-running completes the work safely', 'delete the playbook', 'C', 'Idempotent tasks can simply be re-run, so a partial failure is recovered by running the playbook again to completion.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6072, 173, 'You must install a package only if a file exists on the host. Which Ansible feature selects this behavior?', 'handlers', 'facts', 'tags', 'conditions with when clauses', 'D', 'The when clause evaluates a condition so tasks only run when it is true.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6073, 173, 'What are Ansible handlers used for?', 'running actions only when a task reports a change, such as restarting a service', 'gathering facts', 'defining inventories', 'encrypting variables', 'A', 'Handlers run once at the end of the play only when a notifying task made a change, such as restarting a service.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6074, 173, 'What do Ansible facts describe?', 'the price of hosts', 'discovered details about a managed host such as OS and IP addresses', 'playbook history', 'user passwords', 'B', 'Facts are automatically gathered details about hosts, such as operating system and network addresses, usable in tasks and templates.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6075, 173, 'How do you keep secrets such as API keys safe inside an Ansible project?', 'write them in plain playbooks', 'store them in the inventory', 'use ansible-vault to encrypt them', 'email them to the team', 'C', 'ansible-vault encrypts sensitive variables and files so they are not readable as plain text in the repository.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6076, 173, 'Which module restarts a service on a managed host in Ansible?', 'ping', 'service', 'fetch', 'copy', 'D', 'The service module manages services, including starting, stopping, and restarting them.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6077, 173, 'You want to apply a playbook only to web servers in the inventory. What should you use?', 'a group name in the hosts line of the playbook', 'the ping module', 'a handler', 'ansible-vault', 'A', 'The hosts line can target a group, so the play only runs against hosts in that group.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6078, 173, 'What is configuration drift?', 'when hardware fails', 'when servers slowly deviate from their defined, documented configuration', 'when a network cable is unplugged', 'when billing changes', 'B', 'Drift is the gradual difference between a server''s actual state and the state defined in configuration management.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6079, 173, 'Which Ansible feature turns a static list of hosts into a dynamically discovered set?', 'handlers', 'dynamic inventory', 'facts', 'roles', 'C', 'Dynamic inventory plugins query cloud providers or other sources at runtime to build the host list.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6080, 173, 'What is the recommended way to test an Ansible playbook without touching real servers?', 'run it in production', 'skip testing', 'delete the playbook', 'run it against localhost in check mode or a disposable VM', 'D', 'Check mode and disposable environments let you test playbook behavior safely before applying it to production.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6081, 173, 'An engineer notices a managed server drifted from its defined state. What does a well-configured CM system do about it?', 'it detects drift and can automatically converge the server back to the desired state on the next run', 'it ignores the change forever', 'it deletes the server', 'it emails a monthly report', 'A', 'Continuous enforcement tools detect differences and bring servers back to the declared state on each scheduled run.', 'ADVANCED', 3, 'MCQ', 1),
(6082, 173, 'Which approach is best for configuring a fleet of 5,000 servers while keeping secrets secure and runs auditable?', 'store passwords in playbooks', 'use centralized secrets management, signed code review, and encrypted vaults in the CM pipeline', 'configure each server by hand', 'copy configs over FTP', 'B', 'Centralized secret handling, code review, and vault encryption keep a large automation fleet both secure and auditable.', 'ADVANCED', 3, 'MCQ', 1),
(6083, 173, 'A sensitive value appears in plain text in the Ansible logs. What is the best fix?', 'delete the logs', 'ignore it', 'make the playbook faster', 'mark the variable as a secret so values are masked in output and rotate the leaked secret', 'C', 'Marking sensitive variables as no_log and secret hides their values in output, and the leaked value must still be rotated.', 'ADVANCED', 3, 'MCQ', 1),
(6084, 173, 'How should configuration management handle a service whose package must differ between Red Hat and Ubuntu hosts?', 'install both packages everywhere', 'skip configuration', 'use a single manual process', 'write one task with platform conditions or separate role tasks per family', 'D', 'Conditionals or per-family role tasks let the same playbook choose the right package and service name for each OS.', 'ADVANCED', 3, 'MCQ', 1),
(6085, 173, 'Which practice is most important for reliability when a CM run partially fails mid-way through a large playbook?', 'design tasks to be idempotent and rerunnable so the run can simply be re-executed', 'rebuild the host from scratch', 'run the playbook only at midnight', 'disable the CM agent', 'A', 'Idempotent, rerunnable tasks make failed runs recoverable by simply re-running the playbook to completion.', 'ADVANCED', 3, 'MCQ', 1),
(6086, 173, 'Your team has 50 playbooks with duplicated logic. Which refactor improves maintainability the most?', 'keep the duplication', 'extract shared logic into reusable roles and shared task files', 'delete the extra playbooks', 'merge them into one giant playbook', 'B', 'Roles and shared task files remove duplication, making the configuration base consistent and easier to update.', 'ADVANCED', 3, 'MCQ', 1),
(6087, 173, 'An urgent security patch must go to all servers immediately. How should the CM system be used safely?', 'skip testing and apply everywhere', 'deploy the change directly by hand', 'roll it out through the CM pipeline in waves with monitoring after each wave', 'wait a month', 'C', 'Wave-based rollout with monitoring balances urgency with safety, catching failures before they reach the whole fleet.', 'ADVANCED', 3, 'MCQ', 1),
(6088, 173, 'What is the main reason to gather and use facts before running configuration tasks?', 'it looks impressive', 'it makes playbooks longer', 'it speeds up the network', 'it lets tasks adapt their behavior to each host''s characteristics such as OS and IP', 'D', 'Facts give playbooks per-host context so tasks can adapt to the actual environment instead of assuming it.', 'ADVANCED', 3, 'MCQ', 1),
(6089, 173, 'A compliance auditor requires proof that the fleet matches the declared state. What capability does your CM tool need?', 'reporting and drift detection that produce audit evidence', 'faster provisioning', 'fewer servers', 'manual sign-offs', 'A', 'Reporting and drift-detection outputs provide the concrete evidence auditors need that systems match policy.', 'ADVANCED', 3, 'MCQ', 1),
(6090, 173, 'Which design prevents one badly written playbook from breaking every server at once?', 'run everything at the same second', 'use a single global playbook', 'segment rollout with canary groups and staged environments before broad deployment', 'never use CM', 'B', 'Canaries and staged rollouts contain the blast radius of a bad change before it reaches the whole fleet.', 'ADVANCED', 3, 'MCQ', 1),
(6091, 174, 'What does CI stand for in CI/CD?', 'Continuous Integration', 'Continuous Index', 'Central Installation', 'Code Integrity', 'A', 'CI stands for Continuous Integration, the practice of frequently merging code changes into a shared branch with automated builds and tests.', 'BEGINNER', 1, 'MCQ', 1),
(6092, 174, 'What does CD stand for in CI/CD?', 'Code Development', 'Continuous Deployment', 'Central Deployment', 'Continuous Data', 'B', 'CD stands for Continuous Delivery or Continuous Deployment, automating the release of code to environments.', 'BEGINNER', 1, 'MCQ', 1),
(6093, 174, 'What is a CI/CD pipeline?', 'a physical network cable', 'a database query', 'an automated series of steps that build, test, and deploy code', 'a chat channel', 'C', 'A pipeline chains automated stages such as build, test, and deploy that run whenever code changes.', 'BEGINNER', 1, 'MCQ', 1),
(6094, 174, 'Which stage typically comes first in a CI/CD pipeline?', 'production deploy', 'deployment', 'deleting logs', 'building and testing the code', 'D', 'Building and testing are the early stages that validate the code before it can be deployed.', 'BEGINNER', 1, 'MCQ', 1),
(6095, 174, 'What is the main benefit of automated tests in CI?', 'catching bugs early before they reach production', 'making the code longer', 'reducing the need for tests', 'slowing the pipeline', 'A', 'Automated tests in CI catch regressions immediately after a merge, before the change can reach production.', 'BEGINNER', 1, 'MCQ', 1),
(6096, 174, 'What triggers a CI pipeline in most modern systems?', 'a scheduled coffee break', 'a push or pull request event on the repository', 'a manual reboot', 'a weekly backup', 'B', 'Webhooks on push or pull request events start the pipeline automatically whenever code changes.', 'BEGINNER', 1, 'MCQ', 1),
(6097, 174, 'Which of the following is an artifact in CI/CD?', 'the source code repository', 'the built application package produced by a pipeline stage', 'the team chat', 'the server room temperature', 'C', 'Artifacts are the outputs of pipeline stages, such as compiled binaries or container images, passed to later stages.', 'BEGINNER', 1, 'MCQ', 1),
(6098, 174, 'What is the purpose of a build stage in a pipeline?', 'to delete the repository', 'to send emails', 'to slow down releases', 'to compile source code into runnable artifacts', 'D', 'The build stage compiles and packages the source into an artifact that tests and deployments can use.', 'BEGINNER', 1, 'MCQ', 1),
(6099, 174, 'What is Continuous Delivery, in contrast to Continuous Deployment?', 'code is always in a releasable state but releases to production may require manual approval', 'every change goes to production with no tests', 'deployments are always manual forever', 'there are no pipelines', 'A', 'Continuous Delivery keeps every change releasable, with the final production release gated by an approval step.', 'BEGINNER', 1, 'MCQ', 1),
(6100, 174, 'Which tool is commonly used as a CI/CD server?', 'VLC Media Player', 'Jenkins', 'Microsoft Word', 'Adobe Photoshop', 'B', 'Jenkins is a widely used open-source CI/CD server that runs pipeline jobs.', 'BEGINNER', 1, 'MCQ', 1),
(6101, 174, 'A build is flaky and passes only sometimes. What is the best practice?', 'ignore it since it sometimes passes', 'rerun the pipeline until it passes', 'treat flaky tests as failures and fix the root cause', 'delete the test', 'C', 'Flaky tests destroy pipeline trust, so they must be fixed at the root cause rather than retried or ignored.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6102, 174, 'Which practice makes CI faster while still validating every change?', 'run all builds sequentially on one agent', 'skip tests', 'build only at the end of the month', 'cancel builds for outdated commits and use caching and parallelism', 'D', 'Cancelling superseded builds, caching dependencies, and running stages in parallel cut CI time without losing coverage.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6103, 174, 'Your pipeline deploys directly to production on every merge. What is missing before you can claim Continuous Delivery?', 'a manual approval gate and reliable release process', 'a bigger server', 'more commits', 'a faster network', 'A', 'Continuous Delivery includes a release gate, so production deployment is an approved step rather than automatic.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6104, 174, 'A change passes tests in CI but breaks production because environments differ. What fixes this?', 'deploy faster', 'use parity between environments, e.g., identical container images and configuration', 'skip staging', 'test only locally', 'B', 'Environment parity using identical images and config removes the differences that cause changes to pass in CI but fail in production.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6105, 174, 'Why should secrets be injected into pipeline jobs rather than committed to the repository?', 'they are faster that way', 'they are easier to type', 'committed secrets leak into version history and are accessible to anyone with repo access', 'the pipeline refuses to run', 'C', 'Storing secrets in the pipeline''s secret store keeps them out of version control and limits who can access them.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6106, 174, 'Which approach ensures a container image is safe to deploy?', 'skip scanning', 'deploy without review', 'use any public image', 'scan images for vulnerabilities in the pipeline before release', 'D', 'Scanning images in the pipeline catches known vulnerabilities before the image is ever deployed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6107, 174, 'A deployment succeeds but monitoring shows errors afterward. What is the correct next step?', 'automatically roll back to the last healthy version', 'ignore the errors', 'delete the logs', 'restart the whole cluster blindly', 'A', 'Automated rollback returns the service to the last known-good version when a release shows error spikes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6108, 174, 'Which feature lets a new version receive a fraction of traffic before full release?', 'a full cutover', 'canary release or progressive delivery', 'a rollback', 'a cache flush', 'B', 'Canary releases send a small fraction of traffic to the new version so problems surface before full rollout.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6109, 174, 'Why is it important that pipeline stages run in a clean, isolated environment?', 'it is cheaper', 'it looks professional', 'it prevents issues caused by leftover state or hidden dependencies on the runner', 'it makes logs shorter', 'C', 'Clean, isolated runners ensure builds are reproducible and not affected by stale state from previous jobs.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6110, 174, 'What is a build cache used for in a pipeline?', 'to hide build errors', 'to store old releases forever', 'to bypass security', 'to reuse unchanged dependencies and intermediate outputs so subsequent builds are faster', 'D', 'Caching unchanged dependencies and intermediates speeds up builds by avoiding redundant work.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6111, 174, 'A critical production release was deployed with no way to verify it worked. What is the most important capability to add?', 'deployment monitoring with health checks, metrics, and automated rollback', 'a larger team', 'more frequent commits', 'a faster build server', 'A', 'Monitoring and health checks provide the feedback loop that proves a release is working or triggers an automated rollback.', 'ADVANCED', 3, 'MCQ', 1),
(6112, 174, 'Your pipeline builds the same code twice with different results in different environments. Which practice fixes reproducibility?', 'run builds on developer laptops', 'use containerized, pinned build environments so every run is identical', 'build only at night', 'delete the lock file', 'B', 'Containerized build environments with pinned dependency versions make every pipeline run deterministic and reproducible.', 'ADVANCED', 3, 'MCQ', 1),
(6113, 174, 'Which approach safely allows frequent releases with zero-downtime for a database-backed application?', 'deploy the code and schema in one atomic step', 'stop the database during every release', 'use backward-compatible changes and expand-contract migrations that support rolling deploys', 'release only once a year', 'C', 'Backward-compatible schema changes and expand-contract migrations let old and new code run together during a rolling release.', 'ADVANCED', 3, 'MCQ', 1),
(6114, 174, 'A merge goes straight through CI to production because the pipeline has no security checks. Which control should be added first?', 'a faster runner', 'a prettier dashboard', 'more tests', 'a security gate such as SAST, dependency and image scanning blocking merges', 'D', 'Security gates block vulnerable code from reaching production by failing the pipeline during CI.', 'ADVANCED', 3, 'MCQ', 1),
(6115, 174, 'You must release a hotfix without skipping the CI quality gates. How should the pipeline be configured?', 'allow the hotfix branch to run the same required stages but with expedited review and a bypassable but audited approval', 'disable all tests for the hotfix', 'deploy directly with no tracking', 'merge without building', 'A', 'Fast-track hotfixes still run required checks, with expedited review, so speed does not sacrifice quality or auditability.', 'ADVANCED', 3, 'MCQ', 1),
(6116, 174, 'How does CI/CD reduce the risk of a large release failing?', 'it hides the changes', 'it ships small, frequent changes so failures are small, isolated, and quick to diagnose', 'it merges everything at once', 'it removes all tests', 'B', 'Small frequent releases reduce blast radius because each change is minimal and its failure easy to isolate and revert.', 'ADVANCED', 3, 'MCQ', 1),
(6117, 174, 'A compliance requirement says every production change must be traceable to a code change. How does a pipeline support this?', 'by deleting old builds', 'by speeding up builds', 'by capturing the commit, build, and artifact metadata for every deployment', 'by running builds only in production', 'C', 'Recording commit-to-artifact-to-deployment metadata gives full traceability for every production change.', 'ADVANCED', 3, 'MCQ', 1),
(6118, 174, 'What is the purpose of a deployment freeze during high-traffic periods?', 'to make developers work harder', 'to save money', 'to reduce network traffic', 'to reduce risk by avoiding changes when the cost of failure is highest', 'D', 'Freezes avoid risky changes during critical windows, shifting releases to lower-risk times.', 'ADVANCED', 3, 'MCQ', 1),
(6119, 174, 'How do you safely test a new feature against real users without exposing it to everyone?', 'use feature flags to enable the feature for a subset of users', 'release it to everyone', 'disable monitoring', 'delete the feature', 'A', 'Feature flags let teams toggle features per user or group, enabling gradual rollout and instant disablement.', 'ADVANCED', 3, 'MCQ', 1),
(6120, 174, 'A release broke the API and support could not identify the failing version quickly. Which improvement prevents this?', 'release less often', 'tag each deployment with its version and correlate errors to release versions', 'disable error logs', 'use a single long-running process', 'B', 'Version-tagged deployments and release correlation let teams instantly map an incident back to the release that caused it.', 'ADVANCED', 3, 'MCQ', 1),
(6121, 175, 'What does SLO stand for in SRE practice?', 'Service Level Objective', 'Service Logging Operation', 'System Level Output', 'Secure Login Operation', 'A', 'SLO stands for Service Level Objective, a target for a service''s availability or performance.', 'BEGINNER', 1, 'MCQ', 1),
(6122, 175, 'What is a Service Level Indicator (SLI)?', 'a type of firewall', 'a measurable metric that reflects a service''s performance or reliability', 'a backup policy', 'a team role', 'B', 'An SLI is a concrete, measurable metric such as request success rate or latency that indicates how the service is doing.', 'BEGINNER', 1, 'MCQ', 1),
(6123, 175, 'What is the difference between an SLA and an SLO?', 'they are the same thing', 'an SLA is internal only', 'an SLO is an internal target while an SLA is a contractual commitment with external consequences', 'an SLO is a budget', 'C', 'SLOs are internal engineering targets, whereas SLAs are contractual commitments to customers that may carry penalties.', 'BEGINNER', 1, 'MCQ', 1),
(6124, 175, 'What is an error budget?', 'the amount of money a company earns', 'the number of engineers on call', 'the time a service is down', 'the acceptable amount of unavailability a service may have within an SLO window', 'D', 'The error budget is the amount of unreliability allowed by an SLO, typically 100% minus the SLO percentage.', 'BEGINNER', 1, 'MCQ', 1),
(6125, 175, 'What does MTTR stand for?', 'Mean Time To Recovery', 'Maximum Time To Release', 'Minimum Time To Restart', 'Maintenance Time To Repair', 'A', 'MTTR is Mean Time To Recovery, the average time it takes to restore service after a failure.', 'BEGINNER', 1, 'MCQ', 1),
(6126, 175, 'What does MTBF measure?', 'the number of users', 'the average time between two consecutive failures', 'the size of the database', 'the cost of the service', 'B', 'MTBF is Mean Time Between Failures, the average uptime between failures of a system.', 'BEGINNER', 1, 'MCQ', 1),
(6127, 175, 'What is a runbook?', 'a financial report', 'a network diagram', 'a documented set of procedures for handling operations tasks or incidents', 'a user manual for end customers', 'C', 'Runbooks document the steps operators follow to handle common tasks and incidents consistently.', 'BEGINNER', 1, 'MCQ', 1),
(6128, 175, 'What is on-call rotation in SRE?', 'a daily meeting', 'a backup disk rotation', 'a load-balancing algorithm', 'a schedule where engineers take turns responding to alerts and incidents', 'D', 'On-call rotation assigns engineers to respond to alerts and incidents in shifts, so coverage exists around the clock.', 'BEGINNER', 1, 'MCQ', 1),
(6129, 175, 'What is a blameless postmortem?', 'a review of an incident that focuses on system and process improvements instead of blaming people', 'a report that fires an engineer', 'a way to hide mistakes', 'a list of user complaints', 'A', 'A blameless postmortem analyzes what happened and how to improve, recognizing that complex systems fail in complex ways.', 'BEGINNER', 1, 'MCQ', 1),
(6130, 175, 'What is the goal of redundancy in system design?', 'to slow the system down', 'to eliminate single points of failure so the system survives component failures', 'to increase latency', 'to reduce the number of servers', 'B', 'Redundancy provides backup components or paths so that a failure in one part does not take the whole system down.', 'BEGINNER', 1, 'MCQ', 1),
(6131, 175, 'A service has an SLO of 99.9% availability for one month. What is its error budget for that month?', '10 days', '1 day', 'about 43 minutes', 'about 8 hours', 'C', '0.1% of a 30-day month is roughly 43 minutes, which is the allowed downtime before the SLO is breached.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6132, 175, 'The team spends the entire month on feature work and uses up all its error budget. What should happen next?', 'ignore it and keep shipping', 'ship more features', 'delete the SLO', 'freeze risky changes and focus on reliability until the budget recovers', 'D', 'When the error budget is exhausted, SRE practice says to halt risky changes and invest in reliability to protect users.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6133, 175, 'Which alert is most useful for operators during an incident?', 'an alert with a clear title, severity, and runbook link', 'an alert with only a metric number', 'an alert sent to everyone in the company', 'an alert that fires on every tiny fluctuation', 'A', 'Actionable alerts include context such as severity and a runbook, so on-call engineers can respond quickly.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6134, 175, 'A system cannot reach its availability SLO because a single database is a single point of failure. What is the most direct fix?', 'keep the single database', 'add replication or failover so the database is no longer a single point of failure', 'reboot the database', 'reduce the SLO', 'B', 'Replication and failover remove the database as a single point of failure, improving achievable availability.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6135, 175, 'What is the purpose of load testing a service before a major release?', 'to make the release slower', 'to reduce costs', 'to verify the service can handle expected and peak traffic without failing', 'to make the team busier', 'C', 'Load testing confirms the service stays within its SLO under expected and peak load before users depend on it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6136, 175, 'What is a capacity plan in SRE?', 'a budget for servers', 'a list of engineers', 'a backup schedule', 'a process to ensure enough capacity exists to handle forecast demand while keeping costs reasonable', 'D', 'Capacity planning matches predicted demand to infrastructure so the service does not run out of resources.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6137, 175, 'Which metric best indicates whether users can successfully use a service?', 'the ratio of successful requests to total requests (success rate)', 'the total number of servers', 'the number of alerts', 'the size of the codebase', 'A', 'Success rate is a direct SLI of user experience, showing the fraction of requests that succeed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6138, 175, 'Why do SRE teams define SLOs instead of just aiming for 100% availability?', '100% is impossible to measure', '100% availability is impractical and extremely costly, while an SLO sets a realistic target and an error budget', 'customers always want less', 'SLOs make the team smaller', 'B', 'Realistic SLOs trade cost against reliability and give teams a defined target and error budget instead of chasing impossible perfection.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6139, 175, 'During an incident, what is the primary job of the incident commander?', 'to write the postmortem', 'to fix the code', 'to coordinate the response, assign tasks, and communicate status', 'to answer customer emails', 'C', 'The incident commander owns coordination, task assignment, and communication so responders can focus on fixing the issue.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6140, 175, 'A team measures only error rates but not latency. What part of reliability is missing from its SLIs?', 'cost', 'security', 'team size', 'performance, since slow responses are also user-facing failures', 'D', 'Latency is part of reliability because very slow responses are experienced by users as failures even if they succeed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6141, 175, 'A payment service has a 99.95% SLO. Which decision is most consistent with SRE practice?', 'spend error budget on controlled experiments and release velocity while protecting the SLO with gates', 'always aim for 100%', 'ignore the SLO during sales season', 'remove monitoring', 'A', 'The error budget allows deliberate risk-taking within the defined budget, balancing reliability against feature velocity.', 'ADVANCED', 3, 'MCQ', 1),
(6142, 175, 'During an incident, on-call engineers cannot identify the root cause because dashboards are disorganized. What investment addresses this?', 'more servers', 'improved observability with correlated metrics, logs, and traces', 'a bigger team', 'longer shifts', 'B', 'Correlated metrics, logs, and traces give engineers the signal needed to find root causes quickly during incidents.', 'ADVANCED', 3, 'MCQ', 1),
(6143, 175, 'Your on-call engineers are constantly woken by alerts that never need action. Which SLO-relevant practice fixes this?', 'turn off all alerts', 'add more alerts', 'review alert noise, silence or tune non-actionable alerts, and keep only those tied to SLOs', 'page the manager instead', 'C', 'Reducing alert noise by tuning or removing non-actionable alerts keeps on-call effective and alerts meaningful.', 'ADVANCED', 3, 'MCQ', 1),
(6144, 175, 'A multi-region service still fails a 99.99% SLO because failover is manual and slow. What automation improves this?', 'manual runbooks', 'weekly meetings', 'larger disks', 'automated failover and health-based traffic steering', 'D', 'Automated failover and traffic steering respond to failures in seconds rather than the minutes a manual process needs.', 'ADVANCED', 3, 'MCQ', 1),
(6145, 175, 'A team must choose metrics for a new service. Which set forms a good SLI hierarchy?', 'availability, latency, throughput, and durability for the critical user journeys', 'only server CPU usage', 'the number of commits', 'the size of the database', 'A', 'Good SLIs are based on the user''s critical journey, covering availability, latency, throughput, and durability where relevant.', 'ADVANCED', 3, 'MCQ', 1),
(6146, 175, 'Your SLO is breached every month in a recurring pattern. What is the most effective response?', 'delete the SLO', 'treat the root cause as a reliability investment with a dedicated improvement project', 'add more on-call shifts', 'accept it and move on', 'B', 'Recurring breaches show a systemic root cause that needs dedicated reliability work rather than more firefighting.', 'ADVANCED', 3, 'MCQ', 1),
(6147, 175, 'A new feature is risky but the team wants to ship it. How does the error budget inform this decision?', 'ship it no matter what', 'refuse everything', 'if the error budget is healthy, ship it while protecting the SLO; if exhausted, delay it', 'ask the CEO', 'C', 'A healthy error budget signals room for risk, so the feature can ship, while an exhausted budget says reliability first.', 'ADVANCED', 3, 'MCQ', 1),
(6148, 175, 'Which measure best indicates whether a change to the system is safe to roll out gradually?', 'releasing to everyone at once', 'checking disk space', 'waiting a day', 'comparing error rates and latency between the canary and baseline before widening the rollout', 'D', 'Canary comparison against baseline metrics proves the new version meets its SLO before traffic is widened.', 'ADVANCED', 3, 'MCQ', 1),
(6149, 175, 'After a major outage, the postmortem finds the incident was caused by a misconfigured change that bypassed review. Which follow-up is most in line with SRE?', 'add automated validation and a change review gate so the mistake cannot recur', 'blame the engineer who made the change', 'rewrite the runbook only', 'hold no meetings', 'A', 'Blameless follow-ups focus on automated controls and process changes that prevent the failure from recurring.', 'ADVANCED', 3, 'MCQ', 1),
(6150, 175, 'Your reliability budget is constant but the service grows tenfold in traffic. What must be revisited to keep SLOs meaningful?', 'the team''s office hours', 'capacity planning and SLO targets, since cost and risk scales with traffic', 'the chat tool', 'the company name', 'B', 'Growth in traffic changes the economics of reliability, so capacity plans and SLO trade-offs must be recalculated.', 'ADVANCED', 3, 'MCQ', 1);
INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(6151, 256, 'Which best describes the nature of a blockchain?', 'A distributed, append-only ledger of records stored across many nodes', 'A single spreadsheet held by one bank', 'A type of antivirus software', 'A web browser plugin', 'A', 'A blockchain is a shared, tamper-evident ledger maintained by a decentralised network of nodes.', 'BEGINNER', 1, 'MCQ', 1),
(6152, 256, 'Which term describes the linked structure of blocks in a blockchain?', 'Each block references the hash of the previous block', 'Blocks are random and unordered', 'Blocks are stored only on one server', 'Blocks cannot be verified', 'A', 'Chaining via the previous block''s hash gives the chain its name and links all history in order.', 'BEGINNER', 1, 'MCQ', 1),
(6153, 256, 'Which property describes that records on a blockchain cannot be easily altered once written?', 'Immutability', 'Volatility', 'Opacity', 'Reversibility', 'A', 'Immutability means confirmed blocks are practically impossible to change without redoing enormous work.', 'BEGINNER', 1, 'MCQ', 1),
(6154, 256, 'Which characteristic means no single authority controls a public blockchain?', 'Decentralisation', 'Centralisation', 'Monopolisation', 'Orchestration', 'A', 'Decentralisation spreads control and validation across many independent participants.', 'BEGINNER', 1, 'MCQ', 1),
(6155, 256, 'What is the main purpose of a transaction on a blockchain?', 'To transfer value or data from one party to another in a verifiable way', 'To delete previous records', 'To rename the chain', 'To speed up web pages', 'A', 'Transactions carry value or data between addresses and are recorded permanently on the ledger.', 'BEGINNER', 1, 'MCQ', 1),
(6156, 256, 'Which of the following is a public blockchain?', 'Bitcoin', 'A company''s private ledger in Excel', 'A password manager', 'A print spooler', 'A', 'Bitcoin is a well-known public blockchain open to anyone to read and participate in.', 'BEGINNER', 1, 'MCQ', 1),
(6157, 256, 'Which term describes a record of all confirmed transactions in a blockchain?', 'The distributed ledger', 'The API key', 'The boot sector', 'The cookie file', 'A', 'The ledger is the complete, replicated record of transactions shared across the network.', 'BEGINNER', 1, 'MCQ', 1),
(6158, 256, 'Which component lets users interact with a blockchain using a set of public and private keys?', 'A wallet', 'A compiler', 'A router', 'A printer driver', 'A', 'A wallet stores keys and manages addresses used to send and receive blockchain assets.', 'BEGINNER', 1, 'MCQ', 1),
(6159, 256, 'What is a node in a blockchain network?', 'A computer running software that validates and stores the ledger', 'A single transaction', 'A type of coin', 'A web page', 'A', 'Nodes are the participants that run blockchain software, maintain copies of the ledger and relay data.', 'BEGINNER', 1, 'MCQ', 1),
(6160, 256, 'Which of the following is an example of a permissioned blockchain?', 'Hyperledger Fabric deployed by a consortium', 'Bitcoin mainnet', 'Ethereum mainnet', 'Litecoin', 'A', 'Permissioned blockchains restrict participation to approved members, unlike open public networks.', 'BEGINNER', 1, 'MCQ', 1),
(6161, 256, 'Why does changing one block require recomputing all subsequent blocks in a chain?', 'Each block''s hash includes the previous block''s hash, propagating the change', 'Blocks are sorted alphabetically', 'Blocks store no data', 'Only the genesis block matters', 'A', 'Because each block commits to the previous hash, altering any block invalidates every later block.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6162, 256, 'Which problem does the distributed ledger solve compared with a single trusted database?', 'It removes reliance on one central authority for record keeping', 'It guarantees instant deletion', 'It removes the need for storage', 'It makes data invisible', 'A', 'A shared, verified ledger lets independent parties agree on records without trusting a single intermediary.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6163, 256, 'A bank wants its partners to share a ledger but only allow approved firms to join. Which blockchain type fits?', 'Permissioned/private blockchain', 'Public permissionless blockchain', 'No blockchain can help', 'A plain text file', 'A', 'Permissioned chains restrict membership and roles, suiting consortia that need controlled access.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6164, 256, 'Which mechanism makes a public blockchain ''trustless'' between strangers?', 'Cryptographic validation and consensus instead of personal trust', 'Legal contracts signed offline', 'Central bank guarantees', 'Shared passwords', 'A', 'Users rely on cryptography and consensus rules rather than on trusting any counterparty.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6165, 256, 'Which of these correctly identifies the genesis block?', 'The very first block in a blockchain', 'The latest confirmed block', 'A failed transaction', 'The block with the most transactions', 'A', 'The genesis block is block zero, the root from which all other blocks descend.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6166, 256, 'Which concept refers to the number of copies of the ledger across nodes?', 'Replication', 'Compression', 'Encryption only', 'Indexing', 'A', 'Each full node keeps its own copy of the ledger, and replication makes tampering detectable.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6167, 256, 'Why can a blockchain be described as ''append-only''?', 'New blocks are added to the end, but existing records are not removed or rewritten', 'Old records are deleted weekly', 'Only the start changes', 'Records expire automatically', 'A', 'The ledger only grows by appending new blocks; existing confirmed content stays put.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6168, 256, 'Which statement about a block''s contents is true?', 'A block contains a batch of transactions plus a header with hashes and metadata', 'A block contains only images', 'A block is one single transaction only', 'A block stores no data', 'A', 'Blocks bundle many transactions together with a header carrying the hash links and metadata.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6169, 256, 'What does it mean for a blockchain to be ''tamper-evident''?', 'Unauthorised changes break hash links and are detectable by any node', 'Changes are invisible to everyone', 'Only the owner can see changes', 'Changes erase the whole chain', 'A', 'Any alteration breaks the hash chain, so nodes immediately detect divergence from the agreed history.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6170, 256, 'Which scenario best explains why two nodes must agree on a single chain?', 'Otherwise the ledger would fork into conflicting versions of history', 'Otherwise the chain would delete itself', 'Otherwise coins would multiply infinitely', 'Otherwise the network slows the internet', 'A', 'Consensus keeps every honest node aligned on one canonical chain instead of competing histories.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6171, 256, 'A regulator demands the right to see and audit all transactions but not to approve them. Which design fits a permissioned network?', 'Give the regulator read-only access with cryptographic audit of the ledger', 'Give the regulator the private keys of all users', 'Let the regulator approve every transaction', 'Remove the regulator from the network', 'A', 'Role-based permissions in permissioned chains allow read-only oversight while preserving operational roles.', 'ADVANCED', 3, 'MCQ', 1),
(6172, 256, 'Why is the 51% attack dangerous for a public blockchain?', 'A majority of hashing power can reorder or censor transactions and double-spend', 'It reduces block rewards to zero', 'It reveals private keys instantly', 'It deletes the genesis block', 'A', 'Control of majority hash power lets an attacker rewrite recent history and spend the same coins twice.', 'ADVANCED', 3, 'MCQ', 1),
(6173, 256, 'Which property most directly limits the throughput of permissionless blockchains like Bitcoin?', 'Every full node must validate every transaction and block', 'Transactions are never validated', 'Nodes store only hashes', 'Blocks are unlimited in size', 'A', 'Requiring every node to verify everything caps throughput, trading scalability for decentralisation.', 'ADVANCED', 3, 'MCQ', 1),
(6174, 256, 'A consortium of banks needs privacy between members while sharing a common ledger. Which feature is essential?', 'Channel isolation or private data collections so only relevant members see records', 'Publishing all records to everyone', 'Storing data off-ledger without any audit', 'Sharing all private keys', 'A', 'Channels and private data collections restrict visibility to authorised members while keeping shared consensus.', 'ADVANCED', 3, 'MCQ', 1),
(6175, 256, 'Which trade-off does a larger block size typically introduce?', 'Higher throughput but greater centralisation pressure because full nodes need more resources', 'Lower throughput but better privacy', 'Guaranteed immutability forever', 'No effect on nodes', 'A', 'Bigger blocks increase throughput but raise storage and bandwidth needs, which can centralise validation.', 'ADVANCED', 3, 'MCQ', 1),
(6176, 256, 'Why might an enterprise choose a permissioned chain over a public one for GDPR compliance?', 'It can enforce access controls, data segregation and governance policies', 'Permissioned chains have no data', 'Public chains fully comply by default', 'GDPR only applies to cloud storage', 'A', 'Governance and access control in permissioned networks help satisfy regulatory obligations such as GDPR.', 'ADVANCED', 3, 'MCQ', 1),
(6177, 256, 'Which scenario most strongly threatens the long-term security of a proof-of-work chain?', 'One miner accumulating a majority of the total hashing power', 'Users holding coins in hardware wallets', 'A slow block time', 'A small transaction fee', 'A', 'A single actor controlling the majority of hash power can subvert consensus and rewrite history.', 'ADVANCED', 3, 'MCQ', 1),
(6178, 256, 'Which property best explains why public blockchains are considered more censorship-resistant than centralised ledgers?', 'No single authority can freeze or erase records without the network''s agreement', 'Governments cannot read them', 'They are invisible to search engines', 'They cannot be copied', 'A', 'Distributed control means censoring or altering records requires cooperation (or overwhelming power) across the network.', 'ADVANCED', 3, 'MCQ', 1),
(6179, 256, 'A firm must prove a document existed at a given time. Which blockchain technique records the proof cheaply?', 'Timestamping a hash of the document into a transaction', 'Storing the entire document on every node', 'Encrypting the document with the miner''s key', 'Printing the document on paper', 'A', 'Committing a hash anchors the document''s existence without revealing or duplicating its full content.', 'ADVANCED', 3, 'MCQ', 1),
(6180, 256, 'What is the primary reason a blockchain node verifies the full history before trusting new blocks?', 'To ensure the new block extends a valid chain and spends only valid outputs', 'To speed up the internet', 'To collect transaction fees twice', 'To match the logo colour', 'A', 'Full validation checks that transactions follow the rules and that history is consistent, preventing double spending.', 'ADVANCED', 3, 'MCQ', 1),
(6181, 257, 'Which branch of mathematics underpins most blockchain cryptography?', 'Number theory and discrete logarithms', 'Geometry', 'Probability of weather', 'Statistics of heights', 'A', 'Blockchain relies on number-theoretic problems such as discrete logarithms for digital signatures.', 'BEGINNER', 1, 'MCQ', 1),
(6182, 257, 'What is the primary purpose of a hash function?', 'A function that maps arbitrary input to a fixed-size output', 'A sorting algorithm', 'A compression tool for videos', 'A database index', 'A', 'A hash function takes input of any length and produces a fixed-length digest.', 'BEGINNER', 1, 'MCQ', 1),
(6183, 257, 'Which property of a good hash function means different inputs should give different outputs?', 'Collision resistance', 'Linearity', 'Reversibility', 'Idempotence', 'A', 'Collision resistance makes it computationally infeasible to find two distinct inputs with the same hash.', 'BEGINNER', 1, 'MCQ', 1),
(6184, 257, 'Which hash function is famously used by Bitcoin?', 'SHA-256', 'MD5', 'CRC-32', 'BASE64', 'A', 'Bitcoin uses SHA-256 for proof-of-work and address generation.', 'BEGINNER', 1, 'MCQ', 1),
(6185, 257, 'Which algorithm is commonly used to create a digital signature in blockchain?', 'ECDSA (Elliptic Curve Digital Signature Algorithm)', 'AES in CBC mode', 'ZIP compression', 'XOR encryption', 'A', 'ECDSA is used by Bitcoin and many chains to sign transactions with a private key.', 'BEGINNER', 1, 'MCQ', 1),
(6186, 257, 'Which key must be kept secret by its owner?', 'The private key', 'The public key', 'The block hash', 'The genesis timestamp', 'A', 'The private key signs transactions, so its secrecy is essential; loss means loss of control.', 'BEGINNER', 1, 'MCQ', 1),
(6187, 257, 'Which of the following can anyone safely share?', 'The public key or address', 'The private key', 'The mnemonic seed phrase', 'The wallet password', 'A', 'Public keys and addresses are meant to be shared so others can send to you and verify signatures.', 'BEGINNER', 1, 'MCQ', 1),
(6188, 257, 'What does ''hashing the previous block'' provide in a chain?', 'A link that ties every block to its predecessor', 'A way to compress blocks', 'A method to mine faster', 'An encryption of the coin', 'A', 'The previous block''s hash in each header creates the immutable link between blocks.', 'BEGINNER', 1, 'MCQ', 1),
(6189, 257, 'Which term describes converting plain text into cipher text?', 'Encryption', 'Printing', 'Formatting', 'Indexing', 'A', 'Encryption transforms readable data into an unreadable form using a key.', 'BEGINNER', 1, 'MCQ', 1),
(6190, 257, 'Which concept guarantees that a signed message could only have come from the holder of the private key?', 'Non-repudiation', 'Bandwidth', 'Caching', 'Compression', 'A', 'Non-repudiation means the signer cannot deny having signed, since only they possess the private key.', 'BEGINNER', 1, 'MCQ', 1),
(6191, 257, 'Why can a password not be recovered by reversing a stored hash?', 'Hash functions are one-way, so reversing them is computationally infeasible', 'Hashes are always random letters', 'Passwords are stored in plain text', 'Hashes lose their length', 'A', 'One-way functions make preimage attacks impractical, which is why systems store password hashes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6192, 257, 'An attacker finds two distinct documents with the same hash. Which security property is broken?', 'Collision resistance', 'Confidentiality', 'Availability', 'Ordering', 'A', 'Two colliding inputs violate collision resistance, undermining integrity guarantees.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6193, 257, 'How does adding a random ''nonce'' to input affect a hash?', 'It produces an unpredictable different digest each time, used in mining', 'It makes hashing impossible', 'It shortens the digest', 'It encrypts the output', 'A', 'Varying the nonce changes the hash unpredictably, which is how miners search for a valid proof of work.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6194, 257, 'Which pair of operations do asymmetric keys perform?', 'The private key signs; the public key verifies', 'Both keys encrypt', 'Both keys hash', 'The public key signs; the private key verifies', 'A', 'In signing, the private key creates the signature and the public key verifies it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6195, 257, 'What is a digital signature mainly used for in a transaction?', 'Proving the sender authorised the transfer of funds', 'Hiding the amount', 'Speeding up blocks', 'Adding interest', 'A', 'A valid signature proves the holder of the private key authorised the transaction.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6196, 257, 'Which operation creates an address commonly shown to receive funds?', 'Hashing the public key into a shorter address', 'Encrypting the private key', 'Multiplying two hashes', 'Concatenating block times', 'A', 'Most chains hash the public key to derive a shorter, human-friendly address.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6197, 257, 'Why is SHA-256 preferred over MD5 for new blockchain designs?', 'SHA-256 has much stronger collision resistance and security margins', 'MD5 produces longer hashes', 'MD5 is a symmetric cipher', 'SHA-256 is faster to reverse', 'A', 'MD5''s collisions are practical to find, so modern systems choose the stronger SHA-256.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6198, 257, 'Which statement about public-key cryptography is correct?', 'It uses a mathematically related key pair, one public and one private', 'It uses the same key to encrypt and decrypt', 'It has no keys at all', 'It relies on a shared password', 'A', 'Asymmetric cryptography pairs a public key for verification and a private key for signing.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6199, 257, 'What does the integrity property of a hash detect?', 'Any change to the input, no matter how small, alters the digest', 'The length of the input', 'The age of the data', 'The file''s owner', 'A', 'Even a single flipped bit changes the digest, so tampering is immediately detectable.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6200, 257, 'Which term describes an attacker trying every possible input to guess a hash''s preimage?', 'Brute force attack', 'Fishing trip', 'Rebooting the node', 'Compiling the chain', 'A', 'Brute force exhaustively searches inputs, which strong hashes make impractical.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6201, 257, 'Why is ECDSA preferred over older RSA for many blockchains?', 'Elliptic curves give equivalent security with much shorter keys, saving space', 'RSA cannot sign messages', 'ECDSA is a hash function', 'RSA keys never expire', 'A', 'Shorter ECDSA keys offer equal or better security, which matters on space-constrained ledgers.', 'ADVANCED', 3, 'MCQ', 1),
(6202, 257, 'What is the main weakness of a weak random number generator when creating a private key?', 'Two users may derive the same or predictable keys, compromising funds', 'Keys become too long', 'Hashes get shorter', 'The wallet cannot encrypt', 'A', 'Predictable randomness lets attackers reproduce keys, a known cause of stolen cryptocurrency.', 'ADVANCED', 3, 'MCQ', 1),
(6203, 257, 'How does a Merkle tree reduce the data a light client must download?', 'It lets clients verify one transaction using only a few hashes instead of the whole block', 'It deletes old blocks', 'It compresses all coins into one', 'It removes signatures', 'A', 'Merkle proofs authenticate a single leaf with a short path of hashes, enabling light verification.', 'ADVANCED', 3, 'MCQ', 1),
(6204, 257, 'Which attack does a timestamp or randomness from a future block mitigate in hash-based schemes?', 'Front-running or manipulation of order by validators', 'Collision of public keys', 'Shorter addresses', 'Mining speed variance', 'A', 'Committing to a future, unpredictable value blinds validators from manipulating outcome order.', 'ADVANCED', 3, 'MCQ', 1),
(6205, 257, 'Why must blockchain nodes verify that a signature''s r and s values are in valid ranges?', 'To avoid malleability where a third party can alter the transaction''s signature representation', 'To shorten the signature', 'To speed up mining', 'To hide the sender', 'A', 'Malleability lets attackers change the signature encoding without invalidating it, which can break higher-level logic.', 'ADVANCED', 3, 'MCQ', 1),
(6206, 257, 'What cryptographic property is threatened if an attacker can perform a chosen-prefix collision?', 'Trusted setups and commitments can be forged, breaking consensus assumptions', 'The chain becomes faster', 'Addresses become longer', 'Fees double', 'A', 'Chosen-prefix collisions enable crafted duplicates that break commitment and identity schemes.', 'ADVANCED', 3, 'MCQ', 1),
(6207, 257, 'Which design decision reduces the risk of quantum attacks on public-key signatures?', 'Planning for post-quantum signature schemes or adding them as a transition path', 'Reusing the same key forever', 'Using only symmetric keys', 'Storing keys in plain text', 'A', 'Quantum computers threaten classical signatures, so post-quantum algorithms are the forward-looking mitigation.', 'ADVANCED', 3, 'MCQ', 1),
(6208, 257, 'Why is iterating a hash many times (key stretching) valuable for wallet encryption?', 'It makes brute-force guessing far slower for an attacker', 'It produces longer keys', 'It makes the hash reversible', 'It removes the salt', 'A', 'Repeated hashing multiplies the cost of each password guess, deterring offline attacks.', 'ADVANCED', 3, 'MCQ', 1),
(6209, 257, 'What is the role of a cryptographic commitment in a fair coin-flip on-chain?', 'It hides a choice until all parties commit, then reveals it verifiably', 'It doubles the coins', 'It encrypts the block reward', 'It deletes the previous block', 'A', 'Commitments hide values first and reveal them later, preventing one party from learning and changing the outcome.', 'ADVANCED', 3, 'MCQ', 1),
(6210, 257, 'Which property is required for a hash function used in proof-of-work mining?', 'Finding a valid preimage must require effort but verifying it must be cheap', 'The output must be reversible', 'The output must equal the input', 'Mining must need no randomness', 'A', 'Proof of work relies on asymmetry: hard to find, trivial to verify.', 'ADVANCED', 3, 'MCQ', 1),
(6211, 258, 'What is the purpose of a consensus mechanism in a blockchain?', 'To make distributed nodes agree on one valid version of the ledger', 'To encrypt transactions', 'To shorten the chain', 'To delete old blocks', 'A', 'Consensus lets independent nodes settle on a single canonical history.', 'BEGINNER', 1, 'MCQ', 1),
(6212, 258, 'Which consensus mechanism uses computational work to secure the network?', 'Proof of Work', 'Proof of Trust', 'Proof of Favour', 'Proof of Speed', 'A', 'Proof of Work requires miners to solve a costly computational puzzle to add blocks.', 'BEGINNER', 1, 'MCQ', 1),
(6213, 258, 'Which consensus mechanism requires validators to lock up coins as collateral?', 'Proof of Stake', 'Proof of Work', 'Proof of Ownership', 'Proof of Time', 'A', 'In Proof of Stake, validators stake cryptocurrency and risk losing it if they misbehave.', 'BEGINNER', 1, 'MCQ', 1),
(6214, 258, 'Which of the following is a classic proof-of-work blockchain?', 'Bitcoin', 'A school gradebook', 'A paper ledger', 'A chat server', 'A', 'Bitcoin is the canonical example of a proof-of-work blockchain.', 'BEGINNER', 1, 'MCQ', 1),
(6215, 258, 'What does ''mining'' refer to in proof-of-work blockchains?', 'Finding a valid block by solving a cryptographic puzzle', 'Digging for physical gold', 'Compiling application code', 'Deleting old transactions', 'A', 'Miners race to find a hash below the target difficulty to earn the right to add a block.', 'BEGINNER', 1, 'MCQ', 1),
(6216, 258, 'Which term describes how hard it is to find a valid proof-of-work block?', 'Difficulty', 'Latency', 'Bandwidth', 'Ping', 'A', 'Difficulty adjusts the puzzle so block production stays near a target average time.', 'BEGINNER', 1, 'MCQ', 1),
(6217, 258, 'Which token do validators typically receive as an incentive in proof of work?', 'New coins and transaction fees', 'Free electricity', 'Discount vouchers', 'Stock options', 'A', 'Successful miners earn the block subsidy plus fees, motivating honest participation.', 'BEGINNER', 1, 'MCQ', 1),
(6218, 258, 'What is a blockchain fork?', 'A divergence into two competing chains or versions of history', 'A software update to a wallet', 'A coin being split into cents', 'A copy of the codebase', 'A', 'A fork occurs when nodes disagree about which blocks are valid, splitting the chain.', 'BEGINNER', 1, 'MCQ', 1),
(6219, 258, 'Which consensus mechanism is generally far more energy-efficient than proof of work?', 'Proof of Stake', 'Proof of Work', 'Proof of Burn only', 'Proof of Compute', 'A', 'Proof of Stake replaces wasteful computation with staked capital, cutting energy use dramatically.', 'BEGINNER', 1, 'MCQ', 1),
(6220, 258, 'Which of the following is an example of a proof-of-stake network?', 'Ethereum after the merge', 'Bitcoin', 'Litecoin', 'Monero', 'A', 'Ethereum moved to proof of stake in the Merge, becoming its flagship example.', 'BEGINNER', 1, 'MCQ', 1),
(6221, 258, 'Why does proof of work discourage double-spending by an attacker?', 'Rewriting history requires redoing the costly work for every later block', 'Blocks are free to create', 'Only banks can double-spend', 'The chain is hidden', 'A', 'The cost of re-mining all blocks after a fork makes deep reorganisations economically punishing.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6222, 258, 'Which problem do both PoW and PoS address?', 'Sybil attacks where a user creates many fake identities to dominate voting', 'Slow internet connections', 'Small block sizes', 'High transaction fees only', 'A', 'Both mechanisms tie power to scarce resources (work or stake), defeating identity spam.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6223, 258, 'In proof of stake, what happens to a validator who proposes an invalid block?', 'Their stake can be slashed as a penalty', 'They win more rewards', 'Their keys are copied', 'They are given extra blocks', 'A', 'Slashing burns part of the misbehaving validator''s stake to punish dishonest behaviour.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6224, 258, 'Which statement best describes ''difficulty adjustment''?', 'It retargets the puzzle so blocks arrive at a stable average interval', 'It lowers transaction fees', 'It deletes old blocks', 'It reduces the number of miners', 'A', 'Adjustment keeps block time steady as hashing power grows or shrinks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6225, 258, 'Why do competing blockchain consensus algorithms exist?', 'Each trades off security, speed, energy and decentralisation differently', 'There is only one perfect algorithm', 'Algorithms are interchangeable', 'Consensus is not needed', 'A', 'Different designs balance throughput, finality, cost and resilience for varied use cases.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6226, 258, 'Which term describes a chain division caused by a permanent change in the rules?', 'A hard fork', 'A soft reboot', 'A cache flush', 'A DNS lookup', 'A', 'A hard fork changes the protocol so nodes following old rules can no longer agree with new ones.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6227, 258, 'In PoS, which factor most directly determines a validator''s voting weight?', 'The amount of cryptocurrency they have staked', 'Their computer''s clock speed', 'Their location', 'Their internet provider', 'A', 'Voting influence scales with staked amount and often the duration of the stake.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6228, 258, 'What is the main advantage of a delegated proof of stake design?', 'Voters elect a small set of block producers, giving speed at the cost of some decentralisation', 'It needs no stake', 'It is purely proof of work', 'It has no validators', 'A', 'DPoS uses elected delegates to produce blocks quickly while token holders retain voting power.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6229, 258, 'Which consensus property means once a block is confirmed it will never be reverted?', 'Finality', 'Reversibility', 'Volatility', 'Redundancy', 'A', 'Finality guarantees that confirmed blocks cannot be undone without exceptional conditions.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6230, 258, 'Why can a very short block time hurt a PoW chain?', 'It increases the chance of simultaneous blocks and wasted orphaning', 'It always improves security', 'It lowers difficulty', 'It deletes transactions', 'A', 'Tiny block intervals raise orphan rates as miners race and produce competing blocks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6231, 258, 'Which attack involves a miner mining blocks in secret to later release a longer chain?', 'A selfish mining attack that can outperform honest miners', 'A DDoS on the mempool only', 'A phishing email', 'A dictionary attack', 'A', 'Selfish mining withholds blocks strategically to gain extra reward and occasionally rewrite history.', 'ADVANCED', 3, 'MCQ', 1),
(6232, 258, 'Under which condition can a proof-of-work attacker reliably double-spend?', 'When they control a majority of the total hash power for longer than the merchant waits', 'When they use a hardware wallet', 'When fees are zero', 'When the chain is private', 'A', 'Majority hash power lets an attacker outpace honest miners and rewrite recent history.', 'ADVANCED', 3, 'MCQ', 1),
(6233, 258, 'Why is ''nothing at stake'' a concern in some proof-of-stake designs?', 'Validators have no cost to vote on every fork, creating instability', 'Validators can never be penalised', 'Staking always fails', 'Blocks produce themselves', 'A', 'Without slashing, validators lose nothing by supporting multiple forks, threatening consensus.', 'ADVANCED', 3, 'MCQ', 1),
(6234, 258, 'Which mechanism prevents proof-of-stake ''grinding'' where a validator influences future randomness?', 'Using unpredictable randomness from later blocks or VRF (verifiable random functions)', 'Letting validators choose random numbers freely', 'Disabling randomness', 'Using only the block height', 'A', 'VRFs and delayed randomness stop validators from manipulating which of them is selected.', 'ADVANCED', 3, 'MCQ', 1),
(6235, 258, 'What is the primary economic argument that slashing penalties secure a PoS network?', 'The potential loss of stake outweighs any profit from attacking', 'Penalties are always zero', 'Attackers are immune to loss', 'Fines are paid in fiat', 'A', 'Rationally, a validator will not risk losing more than they could ever gain from an attack.', 'ADVANCED', 3, 'MCQ', 1),
(6236, 258, 'Which property distinguishes BFT-style consensus such as Tendermint or HotStuff?', 'It requires a fixed set of validators and reaches deterministic finality quickly', 'It works with no validators', 'It needs heavy computation', 'It is a proof-of-work puzzle', 'A', 'PBFT-family algorithms reach fast, deterministic agreement among known validators.', 'ADVANCED', 3, 'MCQ', 1),
(6237, 258, 'Which trade-off does increasing the number of consensus validators introduce?', 'More decentralisation but slower agreement due to more communication', 'Faster agreement always', 'Less security', 'No effect on latency', 'A', 'Agreement messages grow with validator count, so larger sets are slower but harder to capture.', 'ADVANCED', 3, 'MCQ', 1),
(6238, 258, 'Why would an attacker prefer a reorg that is deep but short enough to avoid detection?', 'Shallow reorgs are cheap but visible, so the depth is a cost-versus-detection trade-off', 'Deep reorgs always succeed', 'Reorgs need no hash power', 'Detection is impossible', 'A', 'Longer rewrites cost more work and are easier to notice, so attackers balance cost and stealth.', 'ADVANCED', 3, 'MCQ', 1),
(6239, 258, 'Which consensus scenario creates an irreversible social dispute that requires a hard fork?', 'A security flaw or community disagreement that old-rule nodes will not accept as fixed', 'A change in transaction fees', 'A new block hash', 'A longer block time', 'A', 'When the network cannot agree on fixing a flaw or changing rules, the chain splits permanently.', 'ADVANCED', 3, 'MCQ', 1),
(6240, 258, 'What is the purpose of a finality gadget attached to a longest-chain PoW protocol?', 'It adds deterministic finality so honest nodes agree a block cannot be reverted', 'It removes block rewards', 'It doubles the difficulty', 'It encrypts the ledger', 'A', 'Finality gadgets like Casper FFG layer irreversible checkpoints onto probabilistic chains.', 'ADVANCED', 3, 'MCQ', 1),
(6241, 259, 'Which statement best defines a smart contract?', 'A program that executes automatically when predefined conditions are met', 'A paper legal agreement', 'A type of antivirus', 'A database index', 'A', 'Smart contracts are self-executing code stored and run on a blockchain.', 'BEGINNER', 1, 'MCQ', 1),
(6242, 259, 'Which blockchain platform is best known for general-purpose smart contracts?', 'Ethereum', 'Bitcoin', 'Dogecoin', 'Litecoin', 'A', 'Ethereum popularised programmable smart contracts with the Ethereum Virtual Machine.', 'BEGINNER', 1, 'MCQ', 1),
(6243, 259, 'Which programming language is most commonly used to write Ethereum smart contracts?', 'Solidity', 'COBOL', 'Prolog', 'Fortran', 'A', 'Solidity is the primary language for Ethereum smart contracts.', 'BEGINNER', 1, 'MCQ', 1),
(6244, 259, 'Where does smart contract code actually execute?', 'On the blockchain nodes via a virtual machine', 'On the user''s web browser', 'On a single central server', 'On the accountant''s spreadsheet', 'A', 'Smart contracts run deterministically on the network''s nodes through the EVM or similar VM.', 'BEGINNER', 1, 'MCQ', 1),
(6245, 259, 'What does ''gas'' measure in Ethereum?', 'The computational cost of executing operations', 'The physical fuel of servers', 'The chain''s bandwidth', 'The number of nodes', 'A', 'Gas prices execution effort, with users paying fees in the network''s native token.', 'BEGINNER', 1, 'MCQ', 1),
(6246, 259, 'Which term describes a program running on a blockchain that is visible to all?', 'A DApp (decentralised application)', 'A compiled binary hidden on disk', 'A proprietary API', 'A firewall rule', 'A', 'DApps are applications whose logic runs on-chain and is publicly verifiable.', 'BEGINNER', 1, 'MCQ', 1),
(6247, 259, 'Which EVM concept is a persistent piece of data stored by a contract?', 'State variables', 'CPU registers', 'Browser cookies', 'DNS records', 'A', 'State variables persist contract data on-chain between transactions.', 'BEGINNER', 1, 'MCQ', 1),
(6248, 259, 'What happens when a smart contract function is called with insufficient gas?', 'The transaction reverts and gas is consumed', 'The contract still runs', 'The chain restarts', 'The fee is refunded in full', 'A', 'Out-of-gas transactions revert their effects but the spent gas is not refunded.', 'BEGINNER', 1, 'MCQ', 1),
(6249, 259, 'Which component describes the account that owns and can deploy a contract?', 'The deploying address, often the contract owner', 'The mempool', 'The blockchain explorer', 'The genesis block', 'A', 'Deployment is done from an address that typically retains special ownership privileges.', 'BEGINNER', 1, 'MCQ', 1),
(6250, 259, 'Which of the following is a blockchain platform focused on smart contracts?', 'Ethereum', 'WordPress', 'Apache', 'MySQL', 'A', 'Ethereum is a leading smart-contract platform, alongside others like Solana and Cardano.', 'BEGINNER', 1, 'MCQ', 1),
(6251, 259, 'Why is determinism critical for smart contract execution?', 'Every node must compute the identical result for consensus to hold', 'Results can differ per node', 'Randomness is required', 'Nodes skip verification', 'A', 'If nodes produced different results, they could not agree on the same state.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6252, 259, 'Which design problem does a reentrancy attack exploit?', 'A contract calling an external contract before updating its own state', 'A contract with no state', 'A very large block size', 'A slow internet connection', 'A', 'Reentrancy happens when external calls re-enter the contract before state is updated, enabling repeated withdrawals.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6253, 259, 'Which pattern prevents reentrancy in a token contract?', 'Updating balances before making the external transfer (checks-effects-interactions)', 'Making all external calls first', 'Using more gas', 'Disabling logs', 'A', 'Finishing all state changes before interacting externally blocks recursive re-entry.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6254, 259, 'What is the main purpose of the checks-effects-interactions pattern?', 'To prevent state corruption and reentrancy by ordering operations safely', 'To make contracts faster', 'To hide the contract bytecode', 'To reduce block rewards', 'A', 'Updating state before external calls prevents contracts from being exploited mid-execution.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6255, 259, 'Which unit is the smallest denomination of Ether?', 'Wei', 'Ether', 'Gwei', 'Shard', 'A', 'Wei is 10^-18 Ether, the base integer unit used internally.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6256, 259, 'How does a contract typically send tokens to another address?', 'By calling a transfer or a transferFrom function on the token contract', 'By printing a cheque', 'By emailing a password', 'By copying the address', 'A', 'Token movement happens through the token contract''s transfer functions, not raw coin sends.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6257, 259, 'Which standard defines a common interface for fungible tokens such as ERC-20?', 'ERC-20', 'ERC-721', 'ERC-1155', 'ERC-999', 'A', 'ERC-20 specifies the fungible token interface adopted by most Ethereum tokens.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6258, 259, 'Which standard defines non-fungible tokens (NFTs)?', 'ERC-721', 'ERC-20', 'ERC-404', 'ERC-1', 'A', 'ERC-721 defines unique, non-fungible tokens, each identified by its own token ID.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6259, 259, 'Which mechanism limits how much gas a transaction can consume and protects the network?', 'The gas limit set by the sender', 'The block timestamp', 'The token name', 'The node''s CPU count', 'A', 'Senders set a gas limit so runaway loops cannot drain their funds or stall nodes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6260, 259, 'Why do smart contracts need to be thoroughly audited before deployment?', 'Deployed bytecode is immutable and bugs cannot be patched without redeploying', 'Audits speed up mining', 'Audits add randomness', 'Audits delete old code', 'A', 'Because deployed contracts cannot be changed, vulnerabilities can permanently trap or lose funds.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6261, 259, 'Which upgrade pattern allows a contract''s logic to be changed after deployment?', 'A proxy contract that delegates calls to a swappable implementation', 'Editing the bytecode directly', 'Restarting the blockchain', 'Deleting and recreating the address', 'A', 'Proxy contracts keep storage in one place and delegate logic to an addressable implementation that can be updated.', 'ADVANCED', 3, 'MCQ', 1),
(6262, 259, 'Why must upgradeable proxies carefully manage storage slot layout?', 'Delegated calls share the same storage, so slot mismatches corrupt state', 'Storage is temporary', 'Slots hold no data', 'Proxies cannot store data', 'A', 'Because delegatecall runs implementation logic on the proxy''s storage, conflicting layouts overwrite critical state.', 'ADVANCED', 3, 'MCQ', 1),
(6263, 259, 'Which Oracle problem do price-feeding contracts face?', 'Off-chain data must be trusted or manipulated without a single source of truth', 'On-chain data is always wrong', 'Oracles are free', 'Prices never change', 'A', 'Contracts cannot fetch off-chain prices themselves, so they rely on trusted oracles that can be gamed.', 'ADVANCED', 3, 'MCQ', 1),
(6264, 259, 'Which approach best mitigates price-manipulation risk in a lending protocol?', 'Using time-weighted average prices (TWAP) instead of a single spot price', 'Taking the latest trade price instantly', 'Letting users set their own prices', 'Disabling oracles', 'A', 'TWAP averages out flash crashes and manipulation spikes, stabilising collateral valuations.', 'ADVANCED', 3, 'MCQ', 1),
(6265, 259, 'What is the purpose of a timelock in a governance contract?', 'To delay execution so users can review and react to dangerous proposals', 'To speed up voting', 'To hide proposals', 'To add interest to funds', 'A', 'Timelocks give the community a window to intervene before a risky change takes effect.', 'ADVANCED', 3, 'MCQ', 1),
(6266, 259, 'Why can a ''create2'' address be a problem for fund recovery?', 'Contracts deployed via create2 can later be re-deployed at the same address, potentially with different logic', 'create2 addresses are random', 'create2 has no addresses', 'create2 deletes the chain', 'A', 'Create2 lets the same address host different code later, which can surprise protocols holding funds at that address.', 'ADVANCED', 3, 'MCQ', 1),
(6267, 259, 'Which scenario best describes a ''rug pull'' vulnerability in a DApp?', 'Developers retain a backdoor that lets them drain user funds at any time', 'The app is too slow', 'The token name is long', 'Users pay high gas', 'A', 'Hidden admin powers in contracts let creators withdraw funds, a common scam pattern.', 'ADVANCED', 3, 'MCQ', 1),
(6268, 259, 'What does a flash loan attack exploit to manipulate price oracles?', 'Massive uncollateralised borrowing within one transaction to move market prices', 'Long-term staking', 'High withdrawal fees', 'Slow block times', 'A', 'Flash loans concentrate enormous capital in one transaction, letting attackers distort prices before normalising them.', 'ADVANCED', 3, 'MCQ', 1),
(6269, 259, 'Which property of the EVM makes cross-chain contracts hard to port?', 'Different VMs and storage models between chains', 'All chains use identical EVMs', 'Contracts run on laptops', 'Chains share one VM', 'A', 'Different chains have distinct execution environments, so contracts must be adapted or bridged.', 'ADVANCED', 3, 'MCQ', 1),
(6270, 259, 'Why do protocols often pause or ''circuit-break'' during an attack?', 'Halting withdrawals contains the damage until the vulnerability is fixed', 'Pausing speeds up mining', 'Pausing deletes attacker funds', 'Pausing increases token price', 'A', 'An emergency pause freezes funds and buys time, limiting exploit losses.', 'ADVANCED', 3, 'MCQ', 1),
(6271, 260, 'Which option best defines a cryptocurrency?', 'A digital asset that uses cryptography and blockchain to work as money', 'A type of paper bond', 'A loyalty card', 'A stock certificate', 'A', 'Cryptocurrencies are digital currencies secured by cryptography and recorded on distributed ledgers.', 'BEGINNER', 1, 'MCQ', 1),
(6272, 260, 'Which of the following is the first and most well-known cryptocurrency?', 'Bitcoin', 'Litecoin', 'Ethereum', 'Tether', 'A', 'Bitcoin launched in 2009 as the first decentralised cryptocurrency.', 'BEGINNER', 1, 'MCQ', 1),
(6273, 260, 'What is a wallet seed phrase used for?', 'Recovering wallet keys if the device is lost', 'Speeding up transactions', 'Buying more coins', 'Encrypting the blockchain', 'A', 'The seed phrase regenerates all wallet keys, so it must be stored safely.', 'BEGINNER', 1, 'MCQ', 1),
(6274, 260, 'What is a DApp?', 'A decentralised application running on a blockchain', 'A desktop word processor', 'A database backup', 'A domain name', 'A', 'DApps run their logic on-chain through smart contracts instead of a central server.', 'BEGINNER', 1, 'MCQ', 1),
(6275, 260, 'Which term describes sending cryptocurrency from one wallet to another?', 'A transaction', 'A recompile', 'A defragmentation', 'A reboot', 'A', 'Transactions move value between blockchain addresses and are recorded on the ledger.', 'BEGINNER', 1, 'MCQ', 1),
(6276, 260, 'What is a transaction fee primarily for?', 'Paying network participants who process and secure the transaction', 'Buying insurance', 'Purchasing tokens', 'Funding a website', 'A', 'Fees compensate miners or validators for including transactions in blocks.', 'BEGINNER', 1, 'MCQ', 1),
(6277, 260, 'Which of the following is a popular tool for viewing blockchain transactions?', 'A block explorer', 'A text editor', 'A calculator', 'A media player', 'A', 'Block explorers index and display blocks, transactions and balances on-chain.', 'BEGINNER', 1, 'MCQ', 1),
(6278, 260, 'What does a stablecoin aim to do?', 'Maintain a stable value, usually pegged to a fiat currency', 'Grow 100% every day', 'Disappear after use', 'Pay dividends in shares', 'A', 'Stablecoins peg their value to assets like the US dollar to reduce volatility.', 'BEGINNER', 1, 'MCQ', 1),
(6279, 260, 'Which action is most important for keeping cryptocurrency safe?', 'Never sharing your private key or seed phrase', 'Posting keys in a group chat', 'Writing the password on the wall', 'Emailing the seed to support', 'A', 'Anyone with the private key controls the funds, so secrecy is essential.', 'BEGINNER', 1, 'MCQ', 1),
(6280, 260, 'Which of the following describes the total number of bitcoins that will ever exist?', 'Capped at 21 million', 'Unlimited', 'One trillion', 'No limit applies', 'A', 'Bitcoin''s supply is hard-capped at 21 million, enforced by its protocol.', 'BEGINNER', 1, 'MCQ', 1),
(6281, 260, 'Which scenario best describes how a cryptocurrency wallet sends a payment?', 'It signs a transaction with the private key and broadcasts it to the network', 'It emails the recipient the coins', 'It edits the ledger directly', 'It calls the bank', 'A', 'Wallets create and sign transactions, which miners or validators then confirm into blocks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6282, 260, 'Why do transaction confirmation times vary on a congested network?', 'Miners prioritise transactions paying higher fees when blocks are full', 'Confirmations are random', 'Nodes delete waiting transactions', 'Fees are fixed', 'A', 'When the mempool is full, higher-fee transactions get included first, lengthening waits for low fees.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6283, 260, 'Which factor makes Bitcoin''s supply predictable and disinflationary?', 'The block reward halves roughly every four years', 'Mining costs nothing', 'New coins are minted on demand', 'The supply resets yearly', 'A', 'Halvings cut the new-coin issuance in half periodically, approaching the 21 million cap.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6284, 260, 'Which category does Bitcoin''s UTXO model belong to?', 'Unspent transaction outputs that act as discrete coins', 'A single shared account balance', 'A central ledger of IOUs', 'A points system', 'A', 'Bitcoin tracks unspent outputs that a new transaction consumes, unlike account-balance models.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6285, 260, 'Which mechanism lets users interact with a smart-contract DApp without running a full node?', 'A wallet that signs transactions and talks to an RPC provider', 'A full node on every phone', 'Editing the ledger directly', 'Using a block explorer only', 'A', 'Light wallets sign locally and send signed transactions through RPC endpoints.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6286, 260, 'Why are custodial exchanges considered risky for long-term storage?', 'The exchange controls the keys, so user funds can be lost if it fails', 'Exchanges always double balances', 'Exchanges are offline', 'Custodial storage is free', 'A', 'Custodians hold users'' private keys, creating counterparty risk from hacks or insolvency.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6287, 260, 'Which term describes moving tokens between a main chain and a second layer?', 'Bridging or layer-2 transfer', 'Defragmentation', 'Mining', 'Compiling', 'A', 'Bridges lock or wrap assets so they can be used across chains and layers.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6288, 260, 'Which concept lets users verify a transaction without downloading the entire blockchain?', 'Merkle proofs and light client verification', 'Full sync only', 'Guesswork', 'Printing the chain', 'A', 'Light clients use Merkle proofs to verify data against block headers alone.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6289, 260, 'Which popular crypto application lets users borrow and lend without a bank?', 'Decentralised finance (DeFi) protocols', 'A local savings club', 'A stockbroker', 'A payroll system', 'A', 'DeFi platforms automate lending, borrowing and trading through smart contracts.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6290, 260, 'Which practice best protects against losing funds to a fake website?', 'Double-checking the exact URL and verifying signatures before signing', 'Typing the seed into any popup', 'Trusting links in emails', 'Sharing the key with support', 'A', 'Phishing sites steal keys, so verifying domains and rejecting unsolicited key requests is vital.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6291, 260, 'Which economic consequence does a ''token burn'' typically produce?', 'A reduction in circulating supply, often raising scarcity', 'A doubling of supply', 'A permanent price cap', 'A deletion of the chain', 'A', 'Burning removes tokens from circulation, increasing scarcity under otherwise constant demand.', 'ADVANCED', 3, 'MCQ', 1),
(6292, 260, 'Which risk does a decentralised exchange (DEX) reduce compared with a centralised one?', 'Counterparty risk because users keep custody of funds in their own wallets', 'Network latency', 'Gas costs', 'Wallet addresses', 'A', 'DEXs let users trade directly from self-custodied wallets, avoiding exchange custody risk.', 'ADVANCED', 3, 'MCQ', 1),
(6293, 260, 'Why are governance tokens valuable beyond speculation?', 'They grant holders voting power over protocol decisions and fee settings', 'They are always backed by gold', 'They control node hardware', 'They replace fiat cash', 'A', 'Governance tokens give holders a voice in protocol parameter and policy changes.', 'ADVANCED', 3, 'MCQ', 1),
(6294, 260, 'Which vulnerability can a malicious token contract exploit in an integration?', 'Returning false or misreporting balances to trick automated logic', 'Increasing block time', 'Lowering gas', 'Shortening addresses', 'A', 'Non-compliant tokens can lie about balances or transfers, breaking integrations that assume ERC-20 behaviour.', 'ADVANCED', 3, 'MCQ', 1),
(6295, 260, 'What is the main purpose of a hardware wallet?', 'Keeping private keys offline so malware and hacks cannot extract them', 'Mining faster', 'Boosting transaction speed', 'Storing keys in plain text', 'A', 'Hardware wallets isolate keys in secure elements, dramatically reducing remote theft risk.', 'ADVANCED', 3, 'MCQ', 1),
(6296, 260, 'Which trade-off do users accept when choosing a very low transaction fee?', 'Long confirmation wait or being dropped during congestion', 'Immediate finality', 'Guaranteed inclusion', 'Higher rewards', 'A', 'Low-fee transactions wait longer in the mempool and may be left out of blocks entirely.', 'ADVANCED', 3, 'MCQ', 1),
(6297, 260, 'Why does a rollup-based layer 2 improve scalability?', 'It executes transactions off-chain and posts compressed proofs to the main chain', 'It deletes main-chain data', 'It needs no consensus', 'It disables transactions', 'A', 'Rollups batch computations off-chain and settle minimal proof data on-chain, easing congestion.', 'ADVANCED', 3, 'MCQ', 1),
(6298, 260, 'Which scenario best describes a ''dust'' attack?', 'Sending tiny amounts to many addresses to cluster and trace their owners', 'Deleting the chain', 'Doubling a token supply', 'Rewriting the genesis block', 'A', 'Dust attacks de-anonymise users by linking their addresses through microscopic transfers.', 'ADVANCED', 3, 'MCQ', 1),
(6299, 260, 'Why should users rotate addresses rather than reuse one for all payments?', 'Address reuse links transactions and erodes pseudonymity', 'Addresses expire monthly', 'Rotation doubles balances', 'Reuse speeds up mining', 'A', 'Fresh addresses keep transaction histories separate, preserving more privacy.', 'ADVANCED', 3, 'MCQ', 1),
(6300, 260, 'Which combination best describes a robust self-custody setup?', 'Hardware wallet plus paper backup of the seed stored securely', 'Keys kept only in a browser password manager', 'Seed stored in an email draft', 'One password for all exchanges', 'A', 'Cold storage with a physical backup balances security and recovery if devices fail.', 'ADVANCED', 3, 'MCQ', 1),
(6301, 261, 'What is digital evidence?', 'Information stored or transmitted digitally that is relevant to an investigation', 'A printed document', 'A witness statement', 'A physical fingerprint', 'A', 'Digital evidence is data stored or transmitted in digital form used in investigations.', 'BEGINNER', 1, 'MCQ', 1),
(6302, 261, 'What is the chain of custody?', 'Documentation of who handled evidence and when', 'A type of firewall', 'An encryption key', 'A forensic tool', 'A', 'Chain of custody records every transfer of evidence to preserve its integrity.', 'BEGINNER', 1, 'MCQ', 1),
(6303, 261, 'Why is preserving evidence integrity important?', 'To ensure evidence is admissible and trustworthy in court', 'To speed up analysis', 'To reduce file sizes', 'To hide data', 'A', 'Integrity guarantees evidence has not been altered since collection.', 'BEGINNER', 1, 'MCQ', 1),
(6304, 261, 'What is a forensic image?', 'An exact bit-for-bit copy of a storage device', 'A screenshot', 'A compressed archive', 'A backup report', 'A', 'A forensic image duplicates every bit so analysis does not alter the original.', 'BEGINNER', 1, 'MCQ', 1),
(6305, 261, 'What is the first step in handling digital evidence?', 'Identification and preservation', 'Deleting files', 'Formatting the drive', 'Sending an email', 'A', 'Investigators first identify and preserve the evidence safely.', 'BEGINNER', 1, 'MCQ', 1),
(6306, 261, 'What is hashing used for in forensics?', 'To verify evidence integrity with a unique fingerprint', 'To compress evidence', 'To hide evidence', 'To delete files', 'A', 'Hash values such as MD5 or SHA-256 prove files remain unchanged.', 'BEGINNER', 1, 'MCQ', 1),
(6307, 261, 'What does ''write blocker'' do?', 'Prevents writes to an evidence drive during acquisition', 'Encrypts the drive', 'Deletes data', 'Formats the drive', 'A', 'Write blockers ensure acquisition does not modify the original medium.', 'BEGINNER', 1, 'MCQ', 1),
(6308, 261, 'What is metadata?', 'Data that describes other data, such as file timestamps', 'The file content', 'The operating system', 'A network packet', 'A', 'Metadata provides context like creation time, author, and location.', 'BEGINNER', 1, 'MCQ', 1),
(6309, 261, 'What does ''examination'' mean in digital forensics?', 'Analyzing evidence to extract relevant information', 'Deleting evidence', 'Backing up the drive', 'Formatting storage', 'A', 'Examination processes the preserved evidence for relevant data.', 'BEGINNER', 1, 'MCQ', 1),
(6310, 261, 'What is the purpose of forensic documentation?', 'To record findings for reporting and legal defense', 'To delete logs', 'To encrypt data', 'To compress evidence', 'A', 'Documentation creates an auditable record of the investigation.', 'BEGINNER', 1, 'MCQ', 1),
(6311, 261, 'Which hash algorithm is commonly used to verify forensic images?', 'SHA-256', 'Base64', 'AES', 'RSA', 'A', 'SHA-256 produces a strong fingerprint for integrity verification.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6312, 261, 'What is the correct order of the digital forensics process?', 'Identify, preserve, collect, examine, analyze, report', 'Analyze, delete, preserve, report', 'Report, collect, delete', 'Preserve, delete, analyze', 'A', 'The standard process moves from identification through preservation and analysis to reporting.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6313, 261, 'Why must the original evidence medium never be analyzed directly?', 'Analysis can alter the evidence', 'It is slower', 'It is illegal always', 'It wastes space', 'A', 'Working on copies protects the original from accidental modification.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6314, 261, 'What does a hash match between original and copy confirm?', 'The copy is bit-for-bit identical to the original', 'The copy is smaller', 'The copy is encrypted', 'The original is deleted', 'A', 'Matching hashes verify the forensic image is faithful.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6315, 261, 'What is the purpose of time-stamping in evidence collection?', 'To record when evidence was collected', 'To slow the process', 'To encrypt the drive', 'To compress files', 'A', 'Time-stamps establish a timeline for the evidence''s history.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6316, 261, 'Which of the following is a type of digital evidence?', 'Deleted files recovered from a drive', 'A paper receipt', 'A physical key', 'A chalk mark', 'A', 'Recovered digital artifacts are core digital evidence.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6317, 261, 'What does the principle of ''locard''s exchange'' imply digitally?', 'Interacting with digital systems leaves traces', 'Evidence is always deleted', 'Systems leave no traces', 'No data survives', 'A', 'Digital activities leave residual traces that can be examined.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6318, 261, 'What should an investigator do when encountering encrypted evidence?', 'Document it and seek lawful means to decrypt', 'Delete it', 'Ignore it', 'Format the drive', 'A', 'Encrypted data is documented and addressed through legal and technical means.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6319, 261, 'What is the main risk of using the original device for normal activity?', 'It alters evidence and breaks chain of custody', 'It is too fast', 'It uses memory', 'It produces reports', 'A', 'Continuing normal use modifies evidence and invalidates custody.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6320, 261, 'Which document authorizes forensic collection in legal cases?', 'A search warrant or court order', 'An email', 'A sales invoice', 'A meeting note', 'A', 'Legal authorization ensures the collection is lawful.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6321, 261, 'Why is cryptographic hashing alone insufficient to prove authenticity?', 'It proves integrity but not the identity of the creator', 'Hashes are always broken', 'It encrypts evidence', 'It deletes metadata', 'A', 'Hashes verify content is unchanged, not who created it; digital signatures help with authenticity.', 'ADVANCED', 3, 'MCQ', 1),
(6322, 261, 'What is a forensic hash set?', 'A curated database of known-file hashes used to filter benign files', 'A hardware write blocker', 'An encryption key', 'A report template', 'A', 'Hash sets such as the NSRL help triage by identifying known files.', 'ADVANCED', 3, 'MCQ', 1),
(6323, 261, 'Which consideration affects the admissibility of digital evidence?', 'Reliability of the tool and validation of the process', 'The file size', 'The brand of the computer', 'The number of files', 'A', 'Courts require that forensic methods and tools are validated and reliable.', 'ADVANCED', 3, 'MCQ', 1),
(6324, 261, 'What is the purpose of evidence packaging and labeling?', 'To preserve and uniquely identify each piece of evidence', 'To delete evidence', 'To compress evidence', 'To speed analysis', 'A', 'Labeling and packaging maintain custody and prevent tampering.', 'ADVANCED', 3, 'MCQ', 1),
(6325, 261, 'How do timestamps help establish a digital timeline?', 'They correlate file events to a chronological sequence', 'They hide activities', 'They encrypt data', 'They delete logs', 'A', 'Timelines reconstruct the sequence of digital activity.', 'ADVANCED', 3, 'MCQ', 1),
(6326, 261, 'What does the term ''anti-forensics'' describe?', 'Techniques used to hinder forensic investigation', 'A forensic certification', 'A type of write blocker', 'A hash algorithm', 'A', 'Anti-forensics includes data hiding, wiping, and obfuscation.', 'ADVANCED', 3, 'MCQ', 1),
(6327, 261, 'Which data type might reveal that files were deliberately deleted?', 'Slack space and unallocated clusters', 'The desktop wallpaper', 'The monitor resolution', 'The keyboard layout', 'A', 'Residual data in slack space and unallocated areas indicates prior file presence.', 'ADVANCED', 3, 'MCQ', 1),
(6328, 261, 'What is the role of an expert witness in digital forensics?', 'To explain technical findings to a court', 'To delete evidence', 'To encrypt drives', 'To write software', 'A', 'Expert witnesses translate forensic findings into understandable testimony.', 'ADVANCED', 3, 'MCQ', 1),
(6329, 261, 'Why is it critical to document the forensic tool version used?', 'Tool versions affect reproducibility and validity of results', 'It increases file size', 'It hides evidence', 'It is not important', 'A', 'Documenting versions supports reproducibility and legal scrutiny.', 'ADVANCED', 3, 'MCQ', 1),
(6330, 261, 'What does ''volatile evidence'' refer to?', 'Evidence lost when power is removed, such as RAM contents', 'Evidence stored on hard drives', 'Printed documents', 'Cloud backups', 'A', 'Volatile data like running processes must be captured before shutdown.', 'ADVANCED', 3, 'MCQ', 1),
(6331, 262, 'What is the first step in disk forensics?', 'Creating a forensic image of the disk', 'Deleting files', 'Formatting the disk', 'Rebooting the system', 'A', 'Imaging preserves the disk''s state for analysis.', 'BEGINNER', 1, 'MCQ', 1),
(6332, 262, 'What is a filesystem?', 'The structure that organizes files on a storage device', 'A type of malware', 'A network protocol', 'A display driver', 'A', 'Filesystems manage how files are stored and retrieved on disks.', 'BEGINNER', 1, 'MCQ', 1),
(6333, 262, 'What is unallocated space?', 'Disk space no longer assigned to any file', 'The operating system', 'The boot sector', 'Encrypted data', 'A', 'Unallocated space may hold remnants of deleted files.', 'BEGINNER', 1, 'MCQ', 1),
(6334, 262, 'What is file slack?', 'The unused space between the end of a file and the end of its last cluster', 'A compressed file', 'A hidden folder', 'A deleted partition', 'A', 'Slack space can contain residual data from previous files.', 'BEGINNER', 1, 'MCQ', 1),
(6335, 262, 'What happens to a deleted file on a typical filesystem?', 'Its directory entry is marked but data may remain', 'It is erased immediately', 'It is encrypted', 'It moves to the cloud', 'A', 'Deletion usually removes the reference while data persists until overwritten.', 'BEGINNER', 1, 'MCQ', 1),
(6336, 262, 'What is the master boot record (MBR)?', 'The first sector that holds partition and boot information', 'A file type', 'A password store', 'A network card', 'A', 'The MBR contains the partition table and bootstrap code.', 'BEGINNER', 1, 'MCQ', 1),
(6337, 262, 'Which tool creates a forensic disk image?', 'Forensic imaging tools like dd or FTK Imager', 'A web browser', 'A text editor', 'A media player', 'A', 'Tools such as dd and FTK Imager produce bit-for-bit images.', 'BEGINNER', 1, 'MCQ', 1),
(6338, 262, 'What is file carving?', 'Recovering files by scanning raw data without filesystem metadata', 'Deleting files', 'Formatting drives', 'Encrypting files', 'A', 'Carving finds file signatures in raw disk data to recover content.', 'BEGINNER', 1, 'MCQ', 1),
(6339, 262, 'What is the NTFS filesystem''s central metadata file?', 'The Master File Table (MFT)', 'The boot loader', 'The page file', 'The registry', 'A', 'NTFS uses the MFT to record every file and directory.', 'BEGINNER', 1, 'MCQ', 1),
(6340, 262, 'What does a partition table describe?', 'How the disk is divided into partitions', 'The file contents', 'The network settings', 'The hardware specs', 'A', 'Partition tables map the logical divisions of a disk.', 'BEGINNER', 1, 'MCQ', 1),
(6341, 262, 'Why is it useful to recover deleted files?', 'Deleted files often contain relevant evidence', 'It increases disk space', 'It speeds the computer', 'It improves security', 'A', 'Recovered deletions frequently hold key investigative artifacts.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6342, 262, 'What does a hash of the original and image prove?', 'The image is an exact copy of the original', 'The files are compressed', 'The disk is encrypted', 'The system is booted', 'A', 'Matching hashes demonstrate the acquisition was faithful.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6343, 262, 'What is the ''$LogFile'' in NTFS used for?', 'Recovering filesystem metadata changes', 'Storing passwords', 'Booting the system', 'Storing graphics', 'A', 'NTFS journals transactions in $LogFile for recovery.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6344, 262, 'What does the term ''data hiding'' in filesystems include?', 'Using alternate data streams and slack space', 'Deleting files', 'Formatting partitions', 'Compressing drives', 'A', 'Attackers hide data in streams, slack, and unused areas.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6345, 262, 'Which filesystem is native to Windows and supports journaling?', 'NTFS', 'FAT32', 'ext4', 'HFS+', 'A', 'NTFS is the primary Windows filesystem with journaling.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6346, 262, 'What is the purpose of the page file in forensics?', 'It may contain remnants of swapped application data', 'It boots the OS', 'It stores the MFT', 'It caches web pages', 'A', 'The page file can preserve memory content swapped to disk.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6347, 262, 'What is a sparse file?', 'A file with regions not stored on disk', 'A compressed archive', 'A hidden file', 'A system log', 'A', 'Sparse files contain logical zeros that are not physically stored.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6348, 262, 'What is the role of file signatures (magic numbers)?', 'To identify file types during carving and analysis', 'To encrypt files', 'To delete files', 'To index drives', 'A', 'Magic bytes at file headers identify formats even without metadata.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6349, 262, 'Which partition scheme replaces MBR and supports larger disks?', 'GPT (GUID Partition Table)', 'FAT12', 'RAW', 'Swap', 'A', 'GPT supports large disks and redundant partition tables.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6350, 262, 'What does a timeline analysis of a disk reveal?', 'The sequence of file and system events', 'The disk capacity', 'The CPU model', 'The network speed', 'A', 'Timelines correlate timestamps to reconstruct activity.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6351, 262, 'What is the challenge of analyzing an SSD instead of an HDD?', 'TRIM and wear leveling erase deleted data quickly', 'SSDs store no data', 'SSDs are encrypted', 'SSDs have no partitions', 'A', 'SSD controllers actively erase free space, destroying remnants.', 'ADVANCED', 3, 'MCQ', 1),
(6352, 262, 'What does carving risk when files are fragmented?', 'Recovered files may be incomplete or corrupted', 'Files are always complete', 'Files get larger', 'Files disappear', 'A', 'Fragmentation splits files across clusters, complicating carving.', 'ADVANCED', 3, 'MCQ', 1),
(6353, 262, 'What is the significance of the $MFT entry sequence numbers?', 'They help identify file versions and deletions', 'They store passwords', 'They boot the system', 'They encrypt data', 'A', 'MFT sequence numbers reveal file reuse and deletion history.', 'ADVANCED', 3, 'MCQ', 1),
(6354, 262, 'Which technique recovers data from damaged filesystems?', 'Filesystem reconstruction and raw carving', 'Deleting partitions', 'Formatting the drive', 'Rebooting the system', 'A', 'Reconstruction rebuilds metadata from remaining structures.', 'ADVANCED', 3, 'MCQ', 1),
(6355, 262, 'What is an alternate data stream (ADS) in NTFS?', 'A hidden data stream attached to a file', 'A network stream', 'A boot sector', 'A partition type', 'A', 'ADS allows hiding data within a legitimate file.', 'ADVANCED', 3, 'MCQ', 1),
(6356, 262, 'Why might an investigator preserve a full disk image rather than selected files?', 'To retain deleted data, metadata, and context', 'To reduce storage', 'To speed analysis', 'To avoid evidence', 'A', 'Full images preserve everything needed for thorough analysis.', 'ADVANCED', 3, 'MCQ', 1),
(6357, 262, 'What does the term ''wipe'' mean in relation to data?', 'Overwriting data so it cannot be recovered', 'Encrypting data', 'Compressing data', 'Moving data', 'A', 'Wiping deliberately overwrites data to prevent recovery.', 'ADVANCED', 3, 'MCQ', 1),
(6358, 262, 'How can slack space contain evidence from older files?', 'Old file remnants remain between the logical end and cluster boundary', 'Slack is always empty', 'Slack is encrypted', 'Slack stores no data', 'A', 'When files shrink, remnants persist in the slack region.', 'ADVANCED', 3, 'MCQ', 1),
(6359, 262, 'What is the forensic value of examining the $Recycle.Bin?', 'It preserves metadata about deleted files', 'It stores the OS', 'It holds the MFT', 'It caches passwords', 'A', 'The recycle bin records original paths and deletion times.', 'ADVANCED', 3, 'MCQ', 1),
(6360, 262, 'Which tool can parse the NTFS MFT for file timeline data?', 'Forensic analysis suites such as Autopsy or EnCase', 'A web browser', 'A text editor', 'A media player', 'A', 'Forensic suites parse NTFS structures for analysis.', 'ADVANCED', 3, 'MCQ', 1),
(6361, 263, 'What does network forensics analyze?', 'Network traffic and logs to investigate activity', 'Hard disk contents', 'Keyboard inputs', 'Monitor colors', 'A', 'Network forensics examines packets, flows, and logs.', 'BEGINNER', 1, 'MCQ', 1),
(6362, 263, 'What is a packet capture?', 'Recording network packets for analysis', 'A firewall rule', 'An encryption key', 'A DNS record', 'A', 'Packet capture stores network traffic for examination.', 'BEGINNER', 1, 'MCQ', 1),
(6363, 263, 'What is memory forensics?', 'Analyzing RAM contents for evidence', 'Scanning the hard disk', 'Formatting storage', 'Encrypting files', 'A', 'Memory forensics investigates volatile data in RAM.', 'BEGINNER', 1, 'MCQ', 1),
(6364, 263, 'What is a process in memory forensics?', 'A running program that can leave evidence', 'A file on disk', 'A network cable', 'A boot sector', 'A', 'Processes in memory reveal running software and artifacts.', 'BEGINNER', 1, 'MCQ', 1),
(6365, 263, 'Which tool captures network packets?', 'Wireshark', 'Notepad', 'Calculator', 'Paint', 'A', 'Wireshark is a popular packet capture and analysis tool.', 'BEGINNER', 1, 'MCQ', 1),
(6366, 263, 'What is a network log?', 'A record of network events and connections', 'A type of cable', 'A password', 'A disk partition', 'A', 'Logs document connection events for review.', 'BEGINNER', 1, 'MCQ', 1),
(6367, 263, 'What is volatile data?', 'Data lost when power is removed', 'Data stored on hard disks', 'Printed evidence', 'Cloud backups', 'A', 'RAM content vanishes when the system powers off.', 'BEGINNER', 1, 'MCQ', 1),
(6368, 263, 'What does a RAM dump capture?', 'The contents of physical memory', 'The disk partition table', 'The network packets', 'The BIOS', 'A', 'A memory dump preserves RAM for analysis.', 'BEGINNER', 1, 'MCQ', 1),
(6369, 263, 'What is an IP address in network forensics?', 'The address identifying a device on a network', 'A file type', 'A password', 'A process ID', 'A', 'IP addresses help trace communication between systems.', 'BEGINNER', 1, 'MCQ', 1),
(6370, 263, 'What is the purpose of examining browser history in an investigation?', 'To reveal websites visited by the user', 'To encrypt data', 'To delete files', 'To format drives', 'A', 'Browser history provides leads about user activity.', 'BEGINNER', 1, 'MCQ', 1),
(6371, 263, 'Why must memory be acquired before shutting down a machine?', 'RAM contents are lost on shutdown', 'It saves disk space', 'It is faster', 'It avoids encryption', 'A', 'Shutting down destroys volatile evidence in memory.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6372, 263, 'Which memory artifact reveals programs that ran?', 'Process lists and open file handles', 'The desktop icons', 'The wallpaper', 'The BIOS version', 'A', 'Process listings document executed software.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6373, 263, 'What can packet analysis reveal about an attack?', 'The source, target, and method of the attack', 'The hard disk size', 'The CPU speed', 'The monitor resolution', 'A', 'Packets detail communication patterns used in attacks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6374, 263, 'What is a port scan in network forensics?', 'A sequence of connection attempts to many ports', 'A file deletion', 'A memory dump', 'A password change', 'A', 'Port scans often precede exploitation and leave traces.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6375, 263, 'Which tool analyzes memory dumps for artifacts?', 'Volatility', 'Wireshark', 'Notepad', 'Excel', 'A', 'Volatility is a leading memory forensics framework.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6376, 263, 'What is the role of DNS logs in an investigation?', 'They reveal which domains were resolved', 'They store passwords', 'They boot the system', 'They format disks', 'A', 'DNS queries link devices to domains contacted.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6377, 263, 'What does a conversation reconstruction from packets show?', 'The exchange of data between hosts', 'The disk contents', 'The RAM size', 'The OS version', 'A', 'Reassembling streams reveals the actual communication.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6378, 263, 'What is live forensics?', 'Collecting volatile data while the system is running', 'Analyzing hard drives only', 'Formatting disks', 'Deleting logs', 'A', 'Live acquisition captures RAM and active processes before shutdown.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6379, 263, 'Which data in memory can reveal credentials?', 'Cleartext data in process memory', 'The boot sector', 'The partition table', 'The file size', 'A', 'Sensitive data can remain in RAM during processing.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6380, 263, 'What is the purpose of correlating timestamps across sources?', 'To build a timeline of the incident', 'To encrypt evidence', 'To compress logs', 'To delete records', 'A', 'Timestamp correlation reconstructs event sequences.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6381, 263, 'What is the main challenge of memory acquisition from running systems?', 'System changes during acquisition can alter volatile data', 'RAM is always empty', 'Memory is encrypted', 'Acquisition is instant', 'A', 'Live acquisition can disturb the very data being captured.', 'ADVANCED', 3, 'MCQ', 1),
(6382, 263, 'Which memory structure contains network connection details?', 'Kernel socket structures', 'The desktop', 'The BIOS', 'The wallpaper', 'A', 'Socket structures in kernel memory reveal active connections.', 'ADVANCED', 3, 'MCQ', 1),
(6383, 263, 'What does ''malware unpacking'' in memory analysis reveal?', 'The decrypted payload of packed malware', 'The disk size', 'The network speed', 'The browser history', 'A', 'In-memory analysis exposes malware that hides on disk.', 'ADVANCED', 3, 'MCQ', 1),
(6384, 263, 'Which technique identifies hidden processes in memory?', 'Cross-referencing process structures with kernel lists', 'Checking the desktop', 'Scanning the BIOS', 'Reading the monitor', 'A', 'Comparing structures exposes processes hidden from normal APIs.', 'ADVANCED', 3, 'MCQ', 1),
(6385, 263, 'What is the challenge of encrypted network traffic analysis?', 'Content is unreadable without keys or decryption', 'Traffic is always readable', 'Packets disappear', 'Logs are absent', 'A', 'Encryption obscures payload content in captured traffic.', 'ADVANCED', 3, 'MCQ', 1),
(6386, 263, 'Which memory artifact captures the command lines of processes?', 'Process environment and command-line structures', 'The boot loader', 'The partition table', 'The keyboard layout', 'A', 'Command-line arguments in memory reveal executed commands.', 'ADVANCED', 3, 'MCQ', 1),
(6387, 263, 'What does a network flow record summarize?', 'Aggregated metadata of communication sessions', 'File contents', 'Disk errors', 'Memory addresses', 'A', 'Flow records condense connection metadata for analysis.', 'ADVANCED', 3, 'MCQ', 1),
(6388, 263, 'Why is memory forensics valuable for detecting fileless malware?', 'Fileless malware lives only in memory', 'It is stored on disk', 'It cannot run', 'It uses no processes', 'A', 'Fileless threats operate in RAM, invisible to disk scans.', 'ADVANCED', 3, 'MCQ', 1),
(6389, 263, 'What does process injection leave in memory?', 'Evidence of code loaded into another process', 'Deleted files', 'New partitions', 'Empty sectors', 'A', 'Injection artifacts remain in the target process memory.', 'ADVANCED', 3, 'MCQ', 1),
(6390, 263, 'Which tool reconstructs TCP streams from packet captures?', 'Wireshark or tcpflow', 'A text editor', 'A media player', 'A disk imager', 'A', 'Stream reconstruction reassembles application data from packets.', 'ADVANCED', 3, 'MCQ', 1),
(6391, 264, 'What is a forensic tool?', 'Software used to collect and analyze digital evidence', 'A firewall', 'An antivirus', 'A web browser', 'A', 'Forensic tools support evidence acquisition and analysis.', 'BEGINNER', 1, 'MCQ', 1),
(6392, 264, 'Which tool is a popular disk forensics suite?', 'Autopsy', 'Notepad', 'Calculator', 'Paint', 'A', 'Autopsy is an open-source digital forensics platform.', 'BEGINNER', 1, 'MCQ', 1),
(6393, 264, 'What does FTK Imager do?', 'Creates forensic images and previews evidence', 'Sends emails', 'Plays videos', 'Compiles code', 'A', 'FTK Imager acquires disk images for forensic analysis.', 'BEGINNER', 1, 'MCQ', 1),
(6394, 264, 'Which tool is used for network packet analysis?', 'Wireshark', 'Excel', 'Word', 'PowerPoint', 'A', 'Wireshark captures and inspects network traffic.', 'BEGINNER', 1, 'MCQ', 1),
(6395, 264, 'What is a forensic report?', 'A documented summary of findings and methods', 'A backup file', 'An email', 'A spreadsheet', 'A', 'Reports present the evidence, analysis, and conclusions.', 'BEGINNER', 1, 'MCQ', 1),
(6396, 264, 'Which tool analyzes memory images?', 'Volatility', 'Wireshark', 'Excel', 'Photoshop', 'A', 'Volatility extracts artifacts from memory dumps.', 'BEGINNER', 1, 'MCQ', 1),
(6397, 264, 'What does ''triage'' mean in digital forensics?', 'Quickly prioritizing which evidence to examine first', 'Deleting evidence', 'Encrypting evidence', 'Formatting drives', 'A', 'Triage focuses effort on the most relevant evidence.', 'BEGINNER', 1, 'MCQ', 1),
(6398, 264, 'What is a hash database used for?', 'Filtering known files by comparing hashes', 'Storing passwords', 'Booting systems', 'Printing reports', 'A', 'Hash databases identify known benign or malicious files.', 'BEGINNER', 1, 'MCQ', 1),
(6399, 264, 'What is the purpose of carving tools?', 'To recover files without filesystem metadata', 'To format drives', 'To encrypt data', 'To delete files', 'A', 'Carving tools recover data from raw disk content.', 'BEGINNER', 1, 'MCQ', 1),
(6400, 264, 'Which of the following is an evidence collection tool?', 'A write-blocker and imaging tool', 'A media player', 'A web browser', 'A game', 'A', 'Imaging and write-blocking tools support safe collection.', 'BEGINNER', 1, 'MCQ', 1);
INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(6401, 264, 'Which feature of a forensic tool helps reproduce findings?', 'Logging the exact steps performed', 'Deleting evidence', 'Compressing files', 'Hiding artifacts', 'A', 'Reproducibility depends on detailed process logging.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6402, 264, 'What does a forensic timeline show?', 'Events ordered by time across evidence sources', 'The disk capacity', 'The CPU usage', 'The network speed', 'A', 'Timelines correlate activities chronologically.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6403, 264, 'Which tool parses browser artifacts?', 'Browser history analyzers built into forensic suites', 'A text editor', 'A media player', 'A calculator', 'A', 'Forensic suites extract browsing data for analysis.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6404, 264, 'What is the purpose of keyword searching in analysis?', 'To find relevant strings across evidence', 'To compress files', 'To delete records', 'To boot the system', 'A', 'Keyword search locates pertinent terms in evidence.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6405, 264, 'Which tool is used for registry analysis on Windows?', 'Registry parsing tools in forensic suites', 'A web browser', 'A game', 'A media player', 'A', 'Registry analysis reveals configuration and user activity.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6406, 264, 'What does ''artifact extraction'' produce?', 'Specific evidence items such as emails or logs', 'Deleted partitions', 'New users', 'Empty drives', 'A', 'Artifact extraction isolates targeted evidence.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6407, 264, 'Which analysis identifies encrypted containers?', 'Signature scanning and entropy analysis', 'Deleting files', 'Formatting disks', 'Rebooting systems', 'A', 'High entropy and signatures reveal encrypted data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6408, 264, 'What is the role of an evidence database?', 'To store and organize collected evidence for analysis', 'To delete evidence', 'To format drives', 'To send emails', 'A', 'Evidence databases manage case data and artifacts.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6409, 264, 'Which tool can recover deleted partitions?', 'Partition recovery and data carving tools', 'A web browser', 'A media player', 'A calculator', 'A', 'Partition recovery tools reconstruct lost partitions.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6410, 264, 'What does validating a forensic tool involve?', 'Testing that it produces correct, reliable results', 'Deleting evidence', 'Formatting drives', 'Hiding findings', 'A', 'Tool validation ensures defensible results.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6411, 264, 'What is the purpose of a forensic write blocker validation?', 'Confirming the blocker truly prevents writes', 'Speeding the imaging', 'Encrypting the drive', 'Compressing the image', 'A', 'Validated blockers guarantee the evidence is unmodified.', 'ADVANCED', 3, 'MCQ', 1),
(6412, 264, 'Which tool automates timeline creation from multiple sources?', 'Timeline analysis tools such as Plaso', 'A text editor', 'A media player', 'A calculator', 'A', 'Plaso automates event correlation into timelines.', 'ADVANCED', 3, 'MCQ', 1),
(6413, 264, 'What does the NSRL hash set help investigators do?', 'Filter out known legitimate files quickly', 'Encrypt evidence', 'Delete logs', 'Format drives', 'A', 'NSRL (National Software Reference Library) reduces triage noise.', 'ADVANCED', 3, 'MCQ', 1),
(6414, 264, 'Which challenge does analyzing encrypted evidence present?', 'Content cannot be read without lawful decryption keys', 'Files are always readable', 'Data is empty', 'Drives are too small', 'A', 'Encryption obstructs content examination.', 'ADVANCED', 3, 'MCQ', 1),
(6415, 264, 'What is the purpose of entropy analysis in forensics?', 'To detect encrypted or compressed data', 'To delete files', 'To format drives', 'To boot systems', 'A', 'High entropy flags likely encrypted content.', 'ADVANCED', 3, 'MCQ', 1),
(6416, 264, 'Which technique reconstructs a picture of user activity from multiple artifacts?', 'Cross-artifact correlation', 'Deleting files', 'Formatting disks', 'Encrypting data', 'A', 'Correlating artifacts builds a cohesive user activity picture.', 'ADVANCED', 3, 'MCQ', 1),
(6417, 264, 'What does a ''super timeline'' include?', 'Events from many sources merged into one chronological list', 'Only disk errors', 'Only passwords', 'Only IP addresses', 'A', 'Super timelines unify data from filesystem, logs, and memory.', 'ADVANCED', 3, 'MCQ', 1),
(6418, 264, 'Which approach verifies that a tool''s output is reproducible?', 'Running the analysis on a copy and comparing results', 'Deleting evidence', 'Formatting drives', 'Hiding logs', 'A', 'Reproducibility checks confirm consistent tool behavior.', 'ADVANCED', 3, 'MCQ', 1),
(6419, 264, 'What is the purpose of a forensic pre-analysis plan?', 'To define the scope and methods before examining evidence', 'To delete evidence', 'To encrypt drives', 'To format storage', 'A', 'Planning documents the intended analysis approach.', 'ADVANCED', 3, 'MCQ', 1),
(6420, 264, 'Which artifact helps determine when a USB device was connected?', 'Windows USB history in the registry', 'The desktop wallpaper', 'The monitor size', 'The keyboard layout', 'A', 'Registry USB artifacts record device connection history.', 'ADVANCED', 3, 'MCQ', 1),
(6421, 265, 'What is an incident?', 'An event that threatens the security of systems or data', 'A scheduled backup', 'A normal login', 'A system update', 'A', 'Incidents are security events that harm or threaten the organization.', 'BEGINNER', 1, 'MCQ', 1),
(6422, 265, 'What is incident response?', 'The process of detecting, containing, and recovering from incidents', 'Installing software', 'Formatting disks', 'Writing reports', 'A', 'Incident response manages security incidents from detection to recovery.', 'BEGINNER', 1, 'MCQ', 1),
(6423, 265, 'Which phase comes first in incident response?', 'Detection and preparation', 'Recovery', 'Containment', 'Post-incident review', 'A', 'Preparation and detection occur before handling the incident.', 'BEGINNER', 1, 'MCQ', 1),
(6424, 265, 'What is containment?', 'Isolating the incident to prevent further damage', 'Deleting all data', 'Rebooting the server', 'Sending emails', 'A', 'Containment stops the incident from spreading.', 'BEGINNER', 1, 'MCQ', 1),
(6425, 265, 'What is eradication?', 'Removing the root cause of the incident', 'Hiding the evidence', 'Formatting the disk', 'Shutting down', 'A', 'Eradication eliminates malware and the cause of the incident.', 'BEGINNER', 1, 'MCQ', 1),
(6426, 265, 'What is recovery in incident response?', 'Restoring systems to normal operation', 'Deleting backups', 'Ignoring the incident', 'Selling hardware', 'A', 'Recovery brings systems back to a working, verified state.', 'BEGINNER', 1, 'MCQ', 1),
(6427, 265, 'What is a lesson learned review?', 'Analyzing the incident to improve future response', 'Deleting evidence', 'Rewarding attackers', 'Formatting drives', 'A', 'Post-incident reviews improve processes and prevent recurrence.', 'BEGINNER', 1, 'MCQ', 1),
(6428, 265, 'What is an incident report?', 'A document summarizing the incident and response', 'A backup file', 'A network diagram', 'A password list', 'A', 'Reports capture what happened and what was done.', 'BEGINNER', 1, 'MCQ', 1),
(6429, 265, 'What is the first thing to do when a breach is suspected?', 'Preserve evidence and follow the response plan', 'Delete logs', 'Format the drive', 'Ignore it', 'A', 'Preservation and procedure prevent evidence loss.', 'BEGINNER', 1, 'MCQ', 1),
(6430, 265, 'What does an incident response plan define?', 'Roles, procedures, and steps for handling incidents', 'The company''s marketing', 'The office layout', 'The salary structure', 'A', 'The plan guides consistent, effective response.', 'BEGINNER', 1, 'MCQ', 1),
(6431, 265, 'Which phase involves analyzing logs and alerts to confirm an incident?', 'Detection and analysis', 'Recovery', 'Eradication', 'Preparation', 'A', 'Analysis verifies alerts and identifies the scope.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6432, 265, 'What is the difference between an event and an incident?', 'An event is observable activity; an incident is a security-impacting event', 'They are identical', 'Events are always attacks', 'Incidents are scheduled', 'A', 'Not every event is an incident, only those with security impact.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6433, 265, 'Which containment strategy preserves evidence while stopping spread?', 'Disconnecting affected systems from the network', 'Deleting all files', 'Rebooting immediately', 'Formatting drives', 'A', 'Isolation stops propagation without destroying evidence.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6434, 265, 'What is the role of the incident response team?', 'To coordinate and execute the response', 'To delete evidence', 'To hide incidents', 'To format drives', 'A', 'A trained team handles incidents efficiently.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6435, 265, 'Which activity helps detect incidents early?', 'Monitoring logs and alerts continuously', 'Deleting logs', 'Disabling monitoring', 'Ignoring alerts', 'A', 'Continuous monitoring catches incidents early.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6436, 265, 'What is a compromise indicator?', 'A sign that a system has been breached', 'A backup file', 'A login form', 'A firewall rule', 'A', 'Indicators of compromise reveal intrusion activity.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6437, 265, 'Which phase determines the scope of affected systems?', 'Analysis', 'Recovery', 'Preparation', 'Review', 'A', 'Analysis establishes how far the incident spread.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6438, 265, 'What is a containment strategy called when limiting spread without full shutdown?', 'Short-term containment', 'Long-term isolation', 'Immediate wipe', 'Eradication', 'A', 'Short-term containment limits damage quickly before full remediation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6439, 265, 'What should be done before reconnecting a recovered system?', 'Verify it is clean and patched', 'Reconnect immediately', 'Delete its backups', 'Ignore the incident', 'A', 'Verification prevents re-infection.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6440, 265, 'What does a security incident timeline document?', 'The chronological sequence of incident events', 'The disk size', 'The CPU model', 'The network speed', 'A', 'Timelines reconstruct what happened and when.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6441, 265, 'What is the main goal of a post-incident review?', 'Improving the security posture and response process', 'Deleting evidence', 'Formatting drives', 'Hiding failures', 'A', 'Reviews turn incidents into improvements.', 'ADVANCED', 3, 'MCQ', 1),
(6442, 265, 'Which practice helps quantify the impact of an incident?', 'Assessing data loss, downtime, and financial cost', 'Deleting logs', 'Formatting drives', 'Ignoring metrics', 'A', 'Impact assessment supports prioritization and reporting.', 'ADVANCED', 3, 'MCQ', 1),
(6443, 265, 'What is the challenge of cloud incident response?', 'Shared responsibility complicates access and forensics', 'Clouds store no data', 'Clouds cannot be breached', 'No logs exist', 'A', 'Cloud forensics must respect provider boundaries.', 'ADVANCED', 3, 'MCQ', 1),
(6444, 265, 'What does the ''SANS PICERL'' model include?', 'Preparation, identification, containment, eradication, recovery, lessons', 'Only detection', 'Only recovery', 'Only reporting', 'A', 'PICERL is a widely used incident response lifecycle.', 'ADVANCED', 3, 'MCQ', 1),
(6445, 265, 'Why is a ''dry run'' of the incident response plan valuable?', 'It tests readiness before a real incident', 'It deletes evidence', 'It formats drives', 'It hides incidents', 'A', 'Exercises reveal gaps in the plan and skills.', 'ADVANCED', 3, 'MCQ', 1),
(6446, 265, 'Which metric indicates how quickly an incident was contained?', 'Time to contain', 'Disk size', 'CPU speed', 'Report length', 'A', 'Containment time measures response effectiveness.', 'ADVANCED', 3, 'MCQ', 1),
(6447, 265, 'What is the purpose of an external incident response partner?', 'To provide specialized expertise and independent analysis', 'To delete evidence', 'To format drives', 'To hide incidents', 'A', 'External experts bring skill and impartiality.', 'ADVANCED', 3, 'MCQ', 1),
(6448, 265, 'Which document records specific technical actions taken during response?', 'An incident log with timestamps and actions', 'A sales report', 'A marketing plan', 'A salary sheet', 'A', 'Detailed logs support review and legal defense.', 'ADVANCED', 3, 'MCQ', 1),
(6449, 265, 'What is the key legal consideration during incident handling?', 'Preserving evidence for potential prosecution', 'Deleting all data', 'Ignoring regulations', 'Formatting drives', 'A', 'Evidence preservation maintains legal viability.', 'ADVANCED', 3, 'MCQ', 1),
(6450, 265, 'Which measure reduces the impact of future incidents?', 'Implementing lessons learned and improved controls', 'Deleting logs', 'Formatting drives', 'Ignoring incidents', 'A', 'Continuous improvement strengthens defenses.', 'ADVANCED', 3, 'MCQ', 1),
(6451, 286, 'In cloud computing, what does the shared responsibility model describe?', 'How security duties are divided between the provider and the customer', 'How to share a single server', 'How cloud bills are split', 'How office space is divided', 'A', 'The shared responsibility model clarifies which security controls the provider owns and which the customer owns.', 'BEGINNER', 1, 'MCQ', 1),
(6452, 286, 'In IaaS, which security aspect is typically the customer''s responsibility?', 'Securing the operating system and applications they run', 'Securing the physical data center', 'Cooling the servers', 'Repairing the network cables', 'B', 'Under IaaS the provider secures the physical layer while the customer secures the OS, apps and data.', 'BEGINNER', 1, 'MCQ', 1),
(6453, 286, 'In SaaS, which layer is usually the provider''s responsibility?', 'The customer''s office network', 'The application, runtime and underlying infrastructure', 'The customer''s laptops', 'The customer''s user accounts', 'B', 'With SaaS, the provider manages the application and stack while the customer manages usage and data access.', 'BEGINNER', 1, 'MCQ', 1),
(6454, 286, 'Which of the following is generally the CUSTOMER''s responsibility in all cloud models?', 'Patching the provider''s servers', 'Securing the cloud region building', 'Managing their own data and user access', 'Maintaining the hypervisor', 'C', 'Customers are always responsible for their data, identities and access configurations.', 'BEGINNER', 1, 'MCQ', 1),
(6455, 286, 'Which layer is almost always the cloud PROVIDER''s responsibility?', 'The customer''s application code', 'The customer''s firewall rules', 'The customer''s encryption keys', 'Physical infrastructure such as servers and data centers', 'D', 'The provider owns the physical data center, hardware and global network.', 'BEGINNER', 1, 'MCQ', 1),
(6456, 286, 'In PaaS, which component does the customer typically manage?', 'The physical racks', 'The electricity supply', 'The application code and its configuration', 'The cooling systems', 'C', 'With PaaS the provider manages the runtime and platform while the customer manages the application and data.', 'BEGINNER', 1, 'MCQ', 1),
(6457, 286, 'What is the main reason the shared responsibility model matters to security teams?', 'It removes ambiguity about who must fix or configure which controls', 'It reduces all cloud costs', 'It deletes the firewall', 'It removes the need for passwords', 'A', 'Clear division of duties prevents security controls from being assumed covered by the other party.', 'BEGINNER', 1, 'MCQ', 1),
(6458, 286, 'Which of the following is the customer responsible for when using a managed database service?', 'Patching the database engine automatically', 'Access control over who can read the data in the database', 'Hardware redundancy', 'The data center cooling', 'B', 'Even with a managed DB, the customer controls access and permissions over their data.', 'BEGINNER', 1, 'MCQ', 1),
(6459, 286, 'What is the ''security of the cloud'' versus ''security in the cloud'' distinction?', 'Provider-managed protection versus customer-managed protection of their workloads', 'Free versus paid security', 'Hardware versus software only', 'Internal versus external networks', 'A', 'Security of the cloud is the provider''s protection of infrastructure; security in the cloud is the customer''s responsibility for workloads.', 'BEGINNER', 1, 'MCQ', 1),
(6460, 286, 'Which cloud deployment model gives the customer the most control over security configuration?', 'A fully managed SaaS app', 'A serverless function', 'A managed email service', 'IaaS on dedicated or private infrastructure', 'D', 'IaaS exposes compute and network layers that the customer configures directly, offering the most control.', 'BEGINNER', 1, 'MCQ', 1),
(6461, 286, 'A customer deploys a VM in IaaS and leaves the default admin password unchanged. Whose responsibility is the resulting breach?', 'The provider, because they built the VM', 'The customer, because securing the OS and accounts is their duty under IaaS', 'The network vendor', 'No one', 'B', 'Under IaaS the customer owns OS and account security, so weak credentials are the customer''s failure.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6462, 286, 'Which scenario is an example of a provider-side responsibility failure?', 'A customer misconfigured storage bucket', 'A customer shares a password', 'A provider''s hypervisor vulnerability that lets tenants escape their VM boundaries', 'A customer opens a firewall port', 'C', 'Hypervisor isolation is provider-owned, so a tenant-escape flaw is the provider''s responsibility.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6463, 286, 'A customer uses a managed Kubernetes service. Which task remains the customer''s?', 'Patching the control-plane nodes', 'Securing the workloads, namespaces and RBAC policies they define', 'Repairing the cluster''s physical hosts', 'Managing the hypervisor', 'B', 'Managed Kubernetes handles the control plane while customers secure their workloads, namespaces and access policies.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6464, 286, 'Which statement correctly maps responsibility for encryption?', 'The provider offers encryption options, but enabling and managing keys is largely the customer''s duty', 'The provider automatically encrypts and owns all keys', 'Encryption is optional everywhere', 'Customers cannot encrypt in the cloud', 'A', 'Providers supply encryption features, but customers must enable them and manage their keys and scope.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6465, 286, 'A customer finds a public storage bucket holding sensitive files. Which best explains the root cause?', 'A provider data-center outage', 'A provider network upgrade', 'A hypervisor patch', 'A misconfiguration on the customer''s side of the shared responsibility boundary', 'D', 'Access-control misconfiguration of customer-owned resources is a customer-side responsibility failure.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6466, 286, 'Which responsibility is shared between provider and customer in most cloud models?', 'The physical building security', 'The electricity grid', 'Network and access-layer controls such as firewall and identity configuration', 'The storage media destruction', 'C', 'Network and identity controls sit at the boundary and are jointly managed by both parties.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6467, 286, 'Which of the following should a customer do to meet its part of the model for a serverless app?', 'Patch the serverless runtime', 'Harden the function code and validate its inputs', 'Replace the function''s physical host', 'Cool the server room', 'B', 'With serverless, the provider runs the platform but the customer must secure code, inputs and dependencies.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6468, 286, 'When a customer builds a VPC, which aspect is within the provider''s responsibility?', 'The subnets and routing tables', 'The security groups', 'The VPC peering decisions', 'The underlying physical network infrastructure', 'D', 'The provider owns physical networking; logical constructs like subnets and security groups are customer-managed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6469, 286, 'Which practice best demonstrates a customer understanding the shared model?', 'Assuming the provider secures everything', 'Mapping each control to the responsible party in a responsibility matrix', 'Disabling all provider security features', 'Ignoring the model entirely', 'B', 'A documented responsibility matrix makes coverage explicit and auditable.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6470, 286, 'In a hybrid cloud, which layer is unambiguously the customer''s responsibility on-premises?', 'The cloud region''s cooling', 'The provider''s global backbone', 'The cloud console', 'The on-premises physical and application layers', 'D', 'The customer owns everything in its own data center, while the cloud parts follow provider boundaries.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6471, 286, 'Which configuration error most commonly causes customer-side cloud breaches?', 'The provider patching servers', 'Overly permissive storage or identity policies left public by default', 'The provider upgrading DNS', 'The customer buying more RAM', 'B', 'Excessive permissions and public exposure of customer-managed resources are the leading causes of cloud breaches.', 'ADVANCED', 3, 'MCQ', 1),
(6472, 286, 'Which audit finding would correctly be blamed on the PROVIDER under the shared model?', 'A customer''s open database port', 'A customer''s lost key', 'A documented failure of the provider''s stated multi-tenant isolation guarantee', 'A customer''s outdated SDK', 'C', 'Provider failures occur where the provider owns the control, such as multi-tenant isolation guarantees.', 'ADVANCED', 3, 'MCQ', 1),
(6473, 286, 'A compliance team must prove the customer fulfilled its side of the model. Which evidence is most relevant?', 'The provider''s marketing pages', 'Configuration baselines, access reviews and patching records for customer-managed resources', 'The provider''s facility photos', 'The provider''s stock price', 'B', 'Evidence of customer-managed controls proves compliance where the customer owns the duty.', 'ADVANCED', 3, 'MCQ', 1),
(6474, 286, 'Which strategy best reduces risk in the ''shared'' boundary of network controls?', 'Relying only on the provider''s default firewall', 'Disabling all network controls', 'Using flat unsegmented networks', 'Defense-in-depth combining provider-native controls with customer-defined network policies', 'D', 'Layered controls at the shared network boundary cover gaps each party might otherwise leave open.', 'ADVANCED', 3, 'MCQ', 1),
(6475, 286, 'A customer stores encryption keys in the provider''s KMS. How does the model apply if the provider is breached?', 'The customer is always fully to blame', 'If the provider''s KMS was the agreed control, the provider bears the failure, but the customer still chose that control', 'The provider is never involved', 'Keys are irrelevant', 'B', 'Using a provider-managed key service shifts key custody to the provider while the customer remains responsible for choosing the right control.', 'ADVANCED', 3, 'MCQ', 1),
(6476, 286, 'Which approach most effectively closes responsibility gaps in a large multi-cloud estate?', 'Different teams inventing rules per cloud', 'No documentation', 'A cloud security governance team with a unified control framework across all providers', 'Relying on a single vendor', 'C', 'A central governance team with one framework prevents each cloud from having different, overlapping or missing controls.', 'ADVANCED', 3, 'MCQ', 1),
(6477, 286, 'Why is it dangerous to assume the provider''s default security settings are sufficient?', 'Defaults are always perfect', 'Providers never change defaults', 'Customers have no settings', 'Defaults prioritise availability and usability, not the customer''s specific risk posture', 'D', 'Default settings are generic; customers must align them with their own threat model and compliance needs.', 'ADVANCED', 3, 'MCQ', 1),
(6478, 286, 'Which statement about customer data in the shared model is correct?', 'The provider owns customer data', 'Data is exempt from the model', 'The customer retains responsibility for their data regardless of provider infrastructure duties', 'Only the provider can delete data', 'C', 'Data ownership and protection duties always stay with the customer under every cloud model.', 'ADVANCED', 3, 'MCQ', 1),
(6479, 286, 'A regulated customer runs workloads on shared public cloud infrastructure. Which control is most important to demonstrate?', 'A bigger monitor', 'Faster internet', 'More users', 'Strong tenant isolation, encryption and compliance evidence at both responsibility layers', 'D', 'Regulated customers must prove isolation and protection across both provider and customer-controlled layers.', 'ADVANCED', 3, 'MCQ', 1),
(6480, 286, 'Which governance practice most improves accountability under the shared responsibility model?', 'Assigning no owners', 'Verbal handovers', 'Deleting control documents', 'Documenting RACI-style ownership of every security control and reviewing it regularly', 'D', 'Explicit control ownership with regular reviews ensures every duty has an accountable party.', 'ADVANCED', 3, 'MCQ', 1),
(6481, 287, 'What does IAM stand for in cloud security?', 'Internet and Application Model', 'Identity and Access Management', 'Integrated Account Maintenance', 'Infrastructure Automation Module', 'B', 'IAM governs digital identities and the access they are granted to resources.', 'BEGINNER', 1, 'MCQ', 1),
(6482, 287, 'Which cloud IAM component defines what actions an identity may perform on which resources?', 'A policy', 'A password reset', 'A reboot', 'A backup', 'A', 'IAM policies grant permissions, specifying allowed actions on specific resources.', 'BEGINNER', 1, 'MCQ', 1),
(6483, 287, 'What does MFA add to a login?', 'A faster connection', 'More disk space', 'An extra verification factor beyond the password', 'A new colour theme', 'C', 'Multi-factor authentication requires two or more independent credentials to verify identity.', 'BEGINNER', 1, 'MCQ', 1),
(6484, 287, 'Which principle states users should get only the minimum permissions they need?', 'Principle of least privilege', 'Principle of maximum access', 'Principle of open doors', 'Principle of shared accounts', 'A', 'Least privilege grants the minimal permissions required for a role to function.', 'BEGINNER', 1, 'MCQ', 1),
(6485, 287, 'What is a role in RBAC?', 'A physical badge', 'A named collection of permissions assignable to users', 'A password', 'A firewall rule', 'B', 'Roles bundle permissions so they can be assigned consistently to users or groups.', 'BEGINNER', 1, 'MCQ', 1),
(6486, 287, 'Which mechanism lets a user sign in once and access multiple services?', 'Single sign-on (SSO)', 'Rebooting twice', 'Multiple passwords', 'Guest accounts', 'A', 'SSO authenticates the user once and shares the session with connected services.', 'BEGINNER', 1, 'MCQ', 1),
(6487, 287, 'What does a service principal or service account represent?', 'An identity used by an application rather than a human', 'A human employee', 'A conference room', 'A network cable', 'A', 'Service principals give applications their own identity and permissions in the cloud.', 'BEGINNER', 1, 'MCQ', 1),
(6488, 287, 'Which of the following is an example of an authentication factor?', 'Something you know such as a password', 'The office address', 'The company name', 'The building floor', 'A', 'Knowledge factors such as passwords are one class of authentication credential.', 'BEGINNER', 1, 'MCQ', 1),
(6489, 287, 'What is federation in identity management?', 'Trusting identities issued by another organisation''s identity provider', 'Combining two databases', 'Joining two cables', 'Merging two VMs', 'A', 'Federation lets organisations accept identities authenticated by trusted external providers.', 'BEGINNER', 1, 'MCQ', 1),
(6490, 287, 'Which IAM action grants a user access to a specific cloud resource?', 'Deleting the resource', 'Attaching a policy that allows the needed action', 'Restarting the resource', 'Renaming the resource', 'B', 'Policies define the allowed actions, so attaching the right policy grants access.', 'BEGINNER', 1, 'MCQ', 1),
(6491, 287, 'A developer needs read access to one bucket but is granted admin to the whole account. Which IAM principle is violated?', 'The principle of least privilege', 'The principle of high availability', 'The principle of portability', 'The principle of elasticity', 'A', 'Granting far more access than needed violates least privilege and expands the blast radius.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6492, 287, 'Which scenario is the strongest argument for enforcing MFA?', 'A single compromised password then gives full access to the account', 'MFA slows the login slightly', 'MFA costs extra disk', 'MFA changes the UI', 'A', 'MFA blocks attackers who obtain only one credential, so a stolen password alone is insufficient.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6493, 287, 'A contractor leaves the company. Which IAM task is most urgent?', 'Updating their profile photo', 'Revoking their credentials and removing their access', 'Renaming their account', 'Copying their files', 'B', 'Revoking access immediately prevents a departed user from still reaching resources.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6494, 287, 'Which identity setup best lets employees use their corporate account to log into cloud apps?', 'Separate passwords for every app', 'A shared guest password', 'SSO with a federated identity provider', 'Posting credentials on the wall', 'C', 'Federated SSO reuses the corporate identity, simplifying login and centralising control.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6495, 287, 'Which practice prevents a single leaked key from exposing an entire application?', 'Giving every component its own narrowly scoped service principal', 'Sharing one admin key across all services', 'Storing keys in the repository', 'Disabling logging', 'A', 'Narrowly scoped, per-service identities limit what a leaked credential can access.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6496, 287, 'A user is in two groups with conflicting policies, one allowing and one denying an action. What happens in most cloud IAM systems?', 'The deny overrides the allow', 'The allow overrides the deny', 'The action is randomly chosen', 'The account is locked', 'A', 'Explicit denies take precedence over allows in most cloud IAM evaluation models.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6497, 287, 'Which of the following best protects service account credentials at runtime?', 'Hard-coding them in source', 'Storing them in a managed secrets service and rotating them', 'Emailing them to the team', 'Putting them in public docs', 'B', 'Managed secret stores plus rotation reduce the risk that long-lived static keys leak.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6498, 287, 'Why are access reviews important for a growing organisation?', 'Permissions accumulate over time and stale access becomes a risk', 'Reviews slow everyone down', 'Reviews change the UI', 'Reviews increase costs only', 'A', 'Regular access reviews prune stale or excessive permissions that accumulate as people change roles.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6499, 287, 'Which condition-based policy example is a common cloud IAM control?', 'Allowing access only from a corporate IP range', 'Allowing access from anywhere', 'Allowing access only after 2 AM', 'Allowing all users', 'A', 'Conditional policies can restrict access by network, time or device context.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6500, 287, 'What is the main risk of a root or admin account being used for daily work?', 'It cannot be revoked for that user', 'Every action it takes has maximum privilege and impact', 'It is slow', 'It is read-only', 'B', 'Using a full-privilege account for routine work means any compromise yields total control.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6501, 287, 'Which control most directly limits the damage of a stolen short-term credential?', 'Short credential lifetime plus continuous re-authentication and anomaly detection', 'Never rotating keys', 'Long-lived static passwords', 'Ignoring session activity', 'A', 'Short-lived credentials shrink the window in which a stolen token is usable.', 'ADVANCED', 3, 'MCQ', 1),
(6502, 287, 'An organisation must give a partner team temporary access to one project. Which IAM pattern fits best?', 'A scoped role with a time-bound trust relationship and audit trail', 'Adding them to the root group', 'Sharing the admin password', 'Giving them a permanent admin key', 'A', 'Time-bound, scoped, auditable access grants the partner exactly what is needed without permanent exposure.', 'ADVANCED', 3, 'MCQ', 1),
(6503, 287, 'Which design best reduces the impact of an over-privileged service account in a microservice mesh?', 'Each service using its own identity with mesh-native policy enforcement', 'All services sharing one account', 'Root access for every pod', 'No authentication between services', 'A', 'Per-service identities with granular policy enforcement contain any single compromised service.', 'ADVANCED', 3, 'MCQ', 1),
(6504, 287, 'Why is just-in-time (JIT) access useful for highly privileged roles?', 'It grants elevated privileges only when needed and for a limited window', 'It grants permanent admin to everyone', 'It removes all authentication', 'It disables all audits', 'A', 'JIT elevation reduces the standing privilege that attackers could otherwise exploit.', 'ADVANCED', 3, 'MCQ', 1),
(6505, 287, 'Which measure best detects a credential being used from an unexpected location?', 'Anomaly detection and conditional access that challenge unusual sign-ins', 'Ignoring geography', 'Accepting all logins', 'Disabling alerts', 'A', 'Risk-based conditional access flags and blocks sign-ins that deviate from normal behaviour.', 'ADVANCED', 3, 'MCQ', 1),
(6506, 287, 'A security review finds hundreds of unused users with admin rights. Which remediation is most appropriate?', 'A phased deprovisioning that disables stale admin accounts and documents the review', 'Leaving them as they are', 'Granting everyone more rights', 'Deleting all users', 'A', 'Phased, documented deprovisioning removes risky accounts without breaking legitimate workflows.', 'ADVANCED', 3, 'MCQ', 1),
(6507, 287, 'Which IAM architecture best supports an organisation using multiple cloud providers?', 'A central identity provider federated into each cloud', 'Separate password books per cloud', 'One root account per cloud shared by all', 'No central directory', 'A', 'A federated central identity provider gives consistent control across all clouds.', 'ADVANCED', 3, 'MCQ', 1),
(6508, 287, 'Which practice is most effective against credential-stuffing attacks?', 'MFA combined with breach-password screening and rate limiting', 'Longer usernames', 'More screen readers', 'Disabled password policies', 'A', 'MFA, screening against known-breached passwords and rate limiting defeat reused-credential attacks.', 'ADVANCED', 3, 'MCQ', 1),
(6509, 287, 'What does an identity ''blast radius'' analysis help an organisation decide?', 'How much damage each identity could cause if compromised, guiding least privilege', 'Which colour scheme to use', 'How many meetings to schedule', 'Which region to pick for latency', 'A', 'Blast radius analysis quantifies compromise impact so permissions can be trimmed accordingly.', 'ADVANCED', 3, 'MCQ', 1),
(6510, 287, 'Which audit evidence best demonstrates proper IAM governance?', 'Current access reviews, policy change logs and approved role assignments', 'A list of passwords', 'Screenshots of dashboards', 'The number of logins per day', 'A', 'Documented reviews and change logs prove access was governed, not merely granted.', 'ADVANCED', 3, 'MCQ', 1),
(6511, 288, 'What is compliance in a cloud context?', 'Following laws, regulations and standards that apply to your data and workloads', 'Compiling code faster', 'Reducing storage cost', 'Choosing a cloud region', 'A', 'Compliance means meeting the legal and regulatory requirements applicable to the organisation.', 'BEGINNER', 1, 'MCQ', 1),
(6512, 288, 'Which of the following is a widely used information security management standard?', 'A cooking recipe', 'A bus timetable', 'ISO/IEC 27001', 'A football league table', 'C', 'ISO/IEC 27001 specifies requirements for an information security management system.', 'BEGINNER', 1, 'MCQ', 1),
(6513, 288, 'What is an audit trail?', 'A record of who did what and when on the systems', 'A list of fire extinguishers', 'A backup schedule', 'A network diagram', 'A', 'Audit trails log actions and events, enabling review and accountability.', 'BEGINNER', 1, 'MCQ', 1),
(6514, 288, 'Which cloud compliance concern is most relevant for health data in the United States?', 'The periodic table', 'A cooking standard', 'A road sign', 'HIPAA', 'D', 'HIPAA governs the protection of health information in the US.', 'BEGINNER', 1, 'MCQ', 1),
(6515, 288, 'What is the purpose of a compliance report such as SOC 2?', 'Proof of delivery speed', 'Independent verification that a provider meets security and availability criteria', 'A tax receipt', 'A licence to sell food', 'B', 'SOC 2 reports independently attest to a provider''s security, availability and related controls.', 'BEGINNER', 1, 'MCQ', 1),
(6516, 288, 'Which activity helps an organisation verify it actually follows its security policies?', 'Internal audits', 'Renaming folders', 'Buying more monitors', 'Holding fewer meetings', 'A', 'Audits compare actual practice against stated policies and controls.', 'BEGINNER', 1, 'MCQ', 1),
(6517, 288, 'What does a control gap mean?', 'A gap between two buildings', 'A missing cable', 'A requirement that has no compensating control in place', 'A short meeting', 'C', 'A control gap is a missing or ineffective control that leaves a requirement unmet.', 'BEGINNER', 1, 'MCQ', 1),
(6518, 288, 'Which term describes the process of proving to a third party that controls are in place?', 'Compilation', 'Serialization', 'Compression', 'Attestation', 'D', 'Attestation is an independent party''s formal confirmation that controls meet criteria.', 'BEGINNER', 1, 'MCQ', 1),
(6519, 288, 'What is the main purpose of logging configuration changes in the cloud?', 'To slow down the system', 'To fill disk space', 'To detect unauthorised modifications and support investigations', 'To increase costs', 'C', 'Change logs reveal unauthorised or erroneous modifications and feed audits and forensics.', 'BEGINNER', 1, 'MCQ', 1),
(6520, 288, 'Which principle requires that duties such as approving and executing be split across people?', 'Load balancing', 'Separation of duties', 'Data sharding', 'Auto scaling', 'B', 'Separation of duties prevents one person from having unchecked power over a process.', 'BEGINNER', 1, 'MCQ', 1),
(6521, 288, 'A customer using a compliant cloud provider still gets fined for a data breach. Which is the most likely reason?', 'The provider''s certificate expired', 'The customer did not implement its own compliance controls on the workloads', 'The cloud was too fast', 'The region was too small', 'B', 'Provider compliance does not cover the customer''s own responsibilities; fines can still result from customer-side failures.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6522, 288, 'Which activity best prepares an organisation for a third-party audit?', 'Deleting old logs', 'Denying access to auditors', 'Postponing all reviews', 'Gathering evidence of implemented controls ahead of the audit window', 'D', 'Preparing control evidence in advance makes the audit smoother and more accurate.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6523, 288, 'Which cloud practice supports the auditability of a compliance requirement?', 'Disabling all logging', 'Rotating logs daily with no archive', 'Centralised, immutable logging with access to the logs preserved', 'Logging only in memory', 'C', 'Immutable, centralised logs preserve evidence that auditors can rely on.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6524, 288, 'A security team must prove that encryption was enabled on all storage. Which evidence is most useful?', 'A verbal promise', 'Configuration reports and scans showing encryption flags on every resource', 'A single screenshot', 'The provider''s homepage', 'B', 'Automated configuration scanning yields verifiable proof across the whole estate.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6525, 288, 'Which approach best detects drift from a compliant configuration baseline?', 'Checking once a year', 'Trusting developers to follow rules', 'Ignoring configuration', 'Continuously scanning and alerting when resources deviate from the baseline', 'D', 'Continuous monitoring catches drift promptly instead of discovering it at the next audit.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6526, 288, 'Which of the following is an example of a compensating control?', 'Removing all controls', 'Ignoring a missing control', 'Strong MFA where the original control was physically impossible', 'Hiring more accountants', 'C', 'Compensating controls substitute an equivalent protection when a direct control cannot be implemented.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6527, 288, 'Why do cloud providers share compliance reports with customers?', 'To advertise discounts', 'So customers can reuse provider attestations for their own audits', 'To replace their own controls', 'To increase bandwidth', 'B', 'Customer-side auditors can leverage provider attestations to cover the provider-owned layer.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6528, 288, 'Which scenario indicates an access-control compliance failure?', 'An intern holding administrator rights for a year with no review', 'A quarterly access review', 'RBAC in place', 'MFA enabled', 'A', 'Standing, unreviewed admin access for a low-privilege role violates least-privilege expectations.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6529, 288, 'What is the main value of a cloud ''security posture'' score?', 'It measures internet speed', 'It tracks uptime only', 'It counts users', 'It quantifies how well the cloud estate matches best-practice baselines', 'D', 'Posture scores summarise configuration and compliance health so teams can prioritise fixes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6530, 288, 'Which step is essential when a control deficiency is found during an audit?', 'Wait for the next audit', 'Hide the finding', 'Delete the evidence', 'Create a corrective action plan with owners and deadlines', 'D', 'A tracked remediation plan closes the gap and demonstrates accountability.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6531, 288, 'Which combination best sustains compliance in a continuously changing cloud environment?', 'Annual manual reviews', 'Written policies only', 'Infrastructure-as-code baselines with automated policy enforcement and drift detection', 'A single audit per year', 'C', 'IaC and automated enforcement keep the live estate aligned with compliant baselines at all times.', 'ADVANCED', 3, 'MCQ', 1),
(6532, 288, 'An auditor requests evidence for a control that spans several teams. Which practice makes this easy?', 'Scattered emails', 'Verbal recollections', 'No documentation', 'A control ownership matrix with evidence stored in one place', 'D', 'Centralised control ownership and evidence reduces audit effort and ambiguity.', 'ADVANCED', 3, 'MCQ', 1),
(6533, 288, 'Which data would an auditor most value for proving segregation of duties?', 'The number of employees', 'Role assignments that show no single user can both approve and execute a critical action', 'The office floor plan', 'The payroll size', 'B', 'Role-assignment evidence demonstrates that conflicting duties are separated.', 'ADVANCED', 3, 'MCQ', 1),
(6534, 288, 'Why is it dangerous for a compliance team to rely solely on the provider''s compliance certifications?', 'Certifications are always fake', 'Providers never change', 'Certifications cover the provider layer, not the customer''s configurations and data handling', 'Compliance does not matter', 'C', 'The customer must still satisfy the portion of requirements that fall on its own side.', 'ADVANCED', 3, 'MCQ', 1),
(6535, 288, 'Which design best supports a forensic audit after an insider incident?', 'Mutable logs anyone can edit', 'No logs at all', 'Logs stored with the attacker', 'Immutable audit logs with strict access controls and tamper detection', 'D', 'Immutable, access-controlled logs preserve trustworthy evidence for investigation.', 'ADVANCED', 3, 'MCQ', 1),
(6536, 288, 'Which approach most effectively maps cloud controls to regulatory requirements?', 'A marketing brochure', 'A generic list of buzzwords', 'A control framework mapping each regulation to specific technical controls', 'Word-of-mouth advice', 'C', 'Explicit mappings let teams see exactly which control satisfies which requirement.', 'ADVANCED', 3, 'MCQ', 1),
(6537, 288, 'An auditor finds a finding from last year still open. What does this indicate about governance?', 'Remediation tracking and accountability are weak', 'The finding was minor', 'The auditor is wrong', 'Nothing', 'A', 'Unresolved audit findings signal a failure to close gaps, undermining the compliance programme.', 'ADVANCED', 3, 'MCQ', 1),
(6538, 288, 'Which evidence best demonstrates continuous compliance rather than audit-time compliance?', 'A single annual snapshot', 'Continuous monitoring dashboards and automated policy checks with historical records', 'A screenshot taken on audit day', 'A promise to be compliant', 'B', 'Continuous, automated evidence proves controls hold between audits, not just during them.', 'ADVANCED', 3, 'MCQ', 1),
(6539, 288, 'Which trade-off must a compliance team manage when enabling verbose logging?', 'The colour of the dashboard', 'The office size', 'Cost and storage growth versus the investigative value of detailed logs', 'The number of coffee machines', 'C', 'Verbose logging improves forensics but raises storage cost, so teams must balance both.', 'ADVANCED', 3, 'MCQ', 1),
(6540, 288, 'Which technology most reduces the chance that a non-compliant resource silently drifts into production?', 'Automated guardrails and policy-as-code that block non-compliant deploys', 'Trusting developers to self-review', 'A weekly email reminder', 'A poster on the wall', 'A', 'Automated guardrails reject non-compliant infrastructure before it ever reaches production.', 'ADVANCED', 3, 'MCQ', 1),
(6541, 289, 'What is the core assumption of a zero trust security model?', 'That no user or device is trusted by default, even inside the network', 'That everything inside the network is safe', 'That passwords are enough', 'That firewalls are obsolete', 'A', 'Zero trust assumes every access request must be verified regardless of where it originates.', 'BEGINNER', 1, 'MCQ', 1),
(6542, 289, 'Which principle means granting access only after verifying identity and context?', 'Default-deny and verify explicitly', 'Default-allow inside the LAN', 'Trust by location', 'Open access for staff', 'A', 'Zero trust verifies each request explicitly instead of trusting based on network location.', 'BEGINNER', 1, 'MCQ', 1),
(6543, 289, 'What is micro-segmentation?', 'Splitting the network into small isolated zones with their own policies', 'Making one big flat network', 'Segmenting the code into functions', 'Splitting storage into volumes', 'A', 'Micro-segmentation isolates workloads into small segments so a compromise cannot spread laterally.', 'BEGINNER', 1, 'MCQ', 1),
(6544, 289, 'What does ''least privilege'' mean in a zero trust context?', 'Giving users only the access required for their tasks', 'Giving everyone admin rights', 'Giving no one any access', 'Giving access based on friendship', 'A', 'Least privilege limits each identity to the minimal access necessary, shrinking attack surface.', 'BEGINNER', 1, 'MCQ', 1),
(6545, 289, 'Which of the following is a zero trust access decision factor?', 'Device health, user identity and context', 'The colour of the office walls', 'The day of the week only', 'The building address', 'A', 'Zero trust evaluates identity, device posture and context before granting access.', 'BEGINNER', 1, 'MCQ', 1),
(6546, 289, 'What is the role of a device trust score in zero trust?', 'It reflects how secure and compliant a device appears before granting access', 'It measures screen brightness', 'It ranks games', 'It counts installed apps only', 'A', 'Device posture signals such as patching and encryption feed the access decision.', 'BEGINNER', 1, 'MCQ', 1),
(6547, 289, 'Which network security device filters traffic based on rules at the network boundary?', 'A firewall', 'A printer', 'A monitor', 'A router only', 'A', 'Firewalls enforce boundary policies by filtering traffic according to defined rules.', 'BEGINNER', 1, 'MCQ', 1),
(6548, 289, 'What does lateral movement refer to in an attack?', 'An attacker moving across systems within the network after initial entry', 'Moving data to the cloud', 'Changing office desks', 'Upgrading the network cables', 'A', 'Lateral movement is how attackers extend from an initial foothold to other systems.', 'BEGINNER', 1, 'MCQ', 1),
(6549, 289, 'Which of the following is an example of a zero trust network control?', 'Identity-aware access policies applied per request', 'Trusting all internal IP addresses', 'Open VPN for everyone', 'No authentication', 'A', 'Identity-aware, per-request policy is a hallmark of zero trust enforcement.', 'BEGINNER', 1, 'MCQ', 1),
(6550, 289, 'What is the main goal of network segmentation in security?', 'To contain a breach to a small zone instead of the whole network', 'To make the network faster', 'To reduce the number of routers', 'To simplify cabling', 'A', 'Segmentation contains attackers by blocking movement between zones.', 'BEGINNER', 1, 'MCQ', 1),
(6551, 289, 'A company adopts zero trust but keeps a full VPN that grants LAN-wide access. Which gap remains?', 'The VPN bypasses per-request verification once a user is connected', 'The VPN is too slow', 'The VPN changes the IP address', 'The VPN is free', 'A', 'Traditional full-tunnel VPNs hand out broad network access, contradicting zero trust''s per-request model.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6552, 289, 'Which scenario best illustrates a zero trust access decision?', 'A request is allowed only if identity, device and risk signals all pass', 'Any user with a valid password is allowed from any device', 'All staff are trusted inside the office', 'IP-based allow rules grant access', 'A', 'Zero trust evaluates multiple signals together instead of trusting a single factor.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6553, 289, 'How does micro-segmentation help stop ransomware spread?', 'It blocks the lateral movement ransomware needs to reach many hosts', 'It makes backups faster', 'It encrypts the network', 'It deletes all files', 'A', 'By isolating segments, micro-segmentation cuts off the paths ransomware uses to propagate.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6554, 289, 'Which control most directly verifies a device''s security posture before access?', 'Endpoint compliance checks that require patching and encryption', 'A longer password', 'A bigger monitor', 'More bandwidth', 'A', 'Endpoint posture checks gate access to devices that fail minimum security requirements.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6555, 289, 'A finance app should be reachable only by finance staff from managed laptops. Which zero trust mechanism fits?', 'A conditional access policy combining group membership and device compliance', 'A public URL with no auth', 'Opening the port to everyone', 'Trusting all laptops', 'A', 'Conditional access enforces multiple conditions, matching zero trust''s verify-every-request approach.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6556, 289, 'Which practice reduces the trust placed in a single compromised workstation?', 'Device health checks and per-device credentials that limit what a stolen laptop can do', 'Giving every laptop admin rights', 'Trusting the office Wi-Fi', 'Disabling endpoint agents', 'B', 'Per-device controls ensure a single compromised machine cannot roam the network freely.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6557, 289, 'Why are identity-centric policies better than pure IP-based allow lists?', 'Identities and context are far harder to spoof than IP addresses', 'IP addresses are never spoofed', 'Identity policies are simpler to write', 'IP lists are impossible to maintain', 'C', 'IP addresses can be spoofed and change frequently, while identity and context are stronger signals.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6558, 289, 'Which of the following best describes the ''verify explicitly'' zero trust principle?', 'Denying access unless every required signal is positively verified', 'Allowing access until something fails', 'Trusting all known devices', 'Checking only the password', 'B', 'Zero trust defaults to deny and explicitly verifies signals before allowing each request.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6559, 289, 'Which network architecture most reduces the risk of a compromised internal server reaching others?', 'Flat network with one trust zone', 'Micro-segmented zones with per-zone policies', 'No network at all', 'One giant VLAN for everything', 'D', 'Micro-segmentation confines compromise to the zone where it starts, blocking broader reach.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6560, 289, 'Which design best implements zero trust for a cloud application without a legacy VPN?', 'An identity-aware proxy that brokers every connection with granular policies', 'A site-to-site VPN granting full network access', 'Open security groups', 'Public databases', 'C', 'Identity-aware proxies apply per-request policy at the application layer, a modern zero trust pattern.', 'ADVANCED', 3, 'MCQ', 1),
(6561, 289, 'A legacy system cannot enforce MFA. Which compensating control best reduces its zero trust exposure?', 'Network isolation, strict allow lists and monitoring around that system', 'Trusting it because it is old', 'Giving it public access', 'Disabling its logging', 'D', 'Isolating and tightly monitoring legacy systems limits the risk their weak auth creates.', 'ADVANCED', 3, 'MCQ', 1),
(6562, 289, 'Which metric best indicates that micro-segmentation is working?', 'Measured reduction in east-west traffic between workloads that should not communicate', 'Total bandwidth increase', 'Fewer users', 'More firewalls installed', 'B', 'Fewer unexpected east-west flows shows that segmentation is blocking lateral movement.', 'ADVANCED', 3, 'MCQ', 1),
(6563, 289, 'Why is device posture verification important even for users who already passed MFA?', 'A compromised device can abuse the user''s valid session to spread attack', 'Posture checks speed the network', 'Posture checks replace identity', 'MFA is never bypassed', 'C', 'A trusted user''s session is dangerous on an untrusted device, so posture is verified too.', 'ADVANCED', 3, 'MCQ', 1),
(6564, 289, 'Which implementation detail most often breaks a zero trust rollout?', 'Legacy applications that assume direct network reachability', 'Too many users', 'Fast networks', 'Small teams', 'D', 'Legacy apps that rely on direct network paths resist the broker model zero trust introduces.', 'ADVANCED', 3, 'MCQ', 1),
(6565, 289, 'Which control best prevents an attacker from using a stolen session token from a foreign location?', 'Risk-based conditional access that challenges unusual sessions', 'Longer token strings', 'More logging', 'Rebooting the server', 'C', 'Risk-based access flags and blocks anomalous session usage, limiting stolen-token abuse.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6566, 289, 'What is the primary benefit of replacing network trust with identity and context trust?', 'Security no longer depends on where the user connects from', 'Passwords become optional', 'The network becomes invisible', 'Latency always drops', 'D', 'Identity-centric security keeps working even when the network perimeter dissolves, such as in the cloud.', 'ADVANCED', 3, 'MCQ', 1),
(6567, 289, 'Which architecture most effectively contains a cloud misconfiguration that exposes one service?', 'Service-to-service policy enforcement with per-application credentials', 'One shared service account', 'Public service endpoints', 'No identity between services', 'B', 'Per-application identities and policy enforcement contain the blast radius of a single exposed service.', 'ADVANCED', 3, 'MCQ', 1),
(6568, 289, 'How does zero trust change how a security team treats a compromised internal device?', 'It is treated as already compromised, so all its requests are still verified', 'It is given more trust', 'It is ignored', 'It is removed from logging', 'C', 'Zero trust never assumes an internal device is safe, so compromise of one device cannot be assumed clean.', 'ADVANCED', 3, 'MCQ', 1),
(6569, 289, 'Which practice best aligns network policy with zero trust during a migration?', 'Defining access by identity and workload labels rather than by IP subnets', 'Keep trusting subnets', 'Using only static IP rules', 'Removing all policies', 'D', 'Identity- and label-based policy migrates the estate toward zero trust without the brittle IP assumptions.', 'ADVANCED', 3, 'MCQ', 1),
(6570, 289, 'Which outcome proves a zero trust programme reduced real risk rather than just passing an audit?', 'Fewer successful lateral movements and faster containment in incident exercises', 'More compliance certificates', 'More VPN users', 'Longer passwords', 'A', 'Measured improvements in lateral-movement resistance and containment demonstrate genuine risk reduction.', 'ADVANCED', 3, 'MCQ', 1),
(6571, 290, 'What is an incident response plan?', 'A documented procedure for detecting and responding to security incidents', 'A backup schedule', 'A marketing plan', 'A password list', 'A', 'An IR plan defines roles, steps and communication for handling security incidents.', 'BEGINNER', 1, 'MCQ', 1),
(6572, 290, 'Which phase comes first in a typical incident response lifecycle?', 'Preparation', 'Recovery', 'Lessons learned', 'Eradication', 'A', 'Preparation builds the team, tools and procedures before incidents happen.', 'BEGINNER', 1, 'MCQ', 1),
(6573, 290, 'What is the purpose of detection in incident response?', 'To identify that a security incident has occurred', 'To delete all files', 'To restart servers', 'To upgrade the network', 'A', 'Detection activities such as monitoring and alerts uncover incidents early.', 'BEGINNER', 1, 'MCQ', 1),
(6574, 290, 'Which term describes keeping evidence intact and properly documented for legal use?', 'Chain of custody', 'Load balancing', 'Auto scaling', 'Failover', 'A', 'Chain of custody records who handled evidence and when, preserving its integrity.', 'BEGINNER', 1, 'MCQ', 1),
(6575, 290, 'What does containment mean in incident response?', 'Limiting the damage and stopping the attacker from spreading', 'Deleting all backups', 'Increasing permissions', 'Opening more ports', 'A', 'Containment isolates the affected systems to prevent the incident from expanding.', 'BEGINNER', 1, 'MCQ', 1),
(6576, 290, 'Which cloud resource is most useful for capturing forensic images of a compromised VM?', 'Snapshots and volume copies', 'A load balancer', 'A CDN', 'A domain name', 'A', 'Snapshots and volume copies preserve the VM state for analysis without disturbing the live system.', 'BEGINNER', 1, 'MCQ', 1),
(6577, 290, 'What is the main value of cloud audit logs during an incident?', 'They record the actions and events that reveal how the incident occurred', 'They speed up the CPU', 'They reduce storage cost', 'They replace backups', 'A', 'Audit logs reconstruct the timeline of actions that led to and followed the incident.', 'BEGINNER', 1, 'MCQ', 1),
(6578, 290, 'Which step comes AFTER containment in the IR lifecycle?', 'Eradication and recovery', 'Preparation', 'First detection', 'Writing the plan', 'A', 'After containing, teams eradicate the root cause and then recover systems to normal operation.', 'BEGINNER', 1, 'MCQ', 1),
(6579, 290, 'What is the purpose of a lessons-learned review?', 'To improve the response process for future incidents', 'To blame someone', 'To delete the logs', 'To close the case silently', 'A', 'Lessons learned turn every incident into process improvement.', 'BEGINNER', 1, 'MCQ', 1),
(6580, 290, 'Which of the following is a cloud-native detection signal?', 'Anomalous API call volumes from an identity', 'The weather', 'The time zone', 'The building floor', 'A', 'Unusual API activity and sign-in anomalies are prime cloud detection signals.', 'BEGINNER', 1, 'MCQ', 1),
(6581, 290, 'A compromised key starts launching many compute instances. Which containment action is most appropriate first?', 'Disable the key and revoke the identity''s permissions immediately', 'Wait for the bill to arrive', 'Delete the whole account', 'Ignore the instances', 'A', 'Revoking the credential stops the attacker''s control at its source before other steps.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6582, 290, 'Which evidence is most important to preserve before taking a compromised cloud instance offline?', 'Memory and disk evidence captured while the instance still runs', 'A screenshot of the dashboard', 'The instance name', 'The billing amount', 'A', 'Volatile evidence such as memory is lost on shutdown, so capture it before powering down.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6583, 290, 'Which cloud feature best supports rapid containment of a misbehaving deployment?', 'Automated rollback to a known-good configuration', 'Rebooting the office router', 'Buying more instances', 'Disabling logging', 'A', 'Automated rollback quickly restores a safe state, containing the incident''s impact.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6584, 290, 'How does a security team distinguish a real incident from a false alarm?', 'Correlating multiple signals and validating against known-good baselines', 'Assuming every alert is real', 'Ignoring alerts', 'Asking the developer', 'A', 'Correlating signals and validating against baselines separates genuine incidents from noise.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6585, 290, 'Which of the following is a containment advantage of infrastructure-as-code?', 'Environments can be rebuilt exactly and safely after an incident', 'It hides incidents', 'It makes rollback impossible', 'It removes the need for logs', 'A', 'IaC lets teams rebuild clean environments quickly, aiding containment and recovery.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6586, 290, 'Which detection tool helps identify misconfigurations that often precede cloud incidents?', 'Continuous security posture scanning of cloud resources', 'A manual walk-through', 'Annual audits', 'Screenshots', 'A', 'Posture scanning catches risky configurations before attackers exploit them.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6587, 290, 'Which action is part of eradication rather than containment?', 'Removing the attacker''s persistence mechanisms such as backdoor accounts', 'Isolating the affected subnet', 'Notifying users', 'Backing up evidence', 'A', 'Eradication removes the root cause and attacker foothold after containment.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6588, 290, 'Why must cloud forensic evidence include timestamps from a consistent time source?', 'To build an accurate, defensible timeline across many services', 'To make logs longer', 'To reduce storage', 'To hide anomalies', 'A', 'Consistent timestamps let investigators reconstruct the incident sequence reliably.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6589, 290, 'Which cloud practice makes recovery faster after a ransomware incident?', 'Immutable, versioned backups with tested restore procedures', 'Deleting old backups', 'Storing backups on the same disk', 'Never testing restores', 'A', 'Immutable, tested backups restore data even when production systems are encrypted.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6590, 290, 'A defender must prove which identity performed a destructive action. Which evidence set is decisive?', 'Cloud audit logs correlating the API call with the authenticated identity and IP', 'The instance hostname', 'The billing account name', 'A support ticket', 'A', 'Audit trails linking each API action to an identity are the decisive evidence for attribution.', 'INTERMEDIATE', 2, 'MCQ', 1),
(6591, 290, 'Which design most limits the impact of a single stolen cloud key?', 'Short-lived credentials with scoped permissions and rapid rotation', 'Long-lived admin keys', 'Shared root keys', 'Keys stored in source code', 'A', 'Short-lived, scoped credentials shrink both the chance of theft and its blast radius.', 'ADVANCED', 3, 'MCQ', 1),
(6592, 290, 'Why is memory forensics valuable for cloud workloads even though disks are often ephemeral?', 'Memory reveals running processes, injected code and live attacker activity', 'Memory is easier to copy', 'Memory lasts longer than disk', 'Memory stores the whole database', 'A', 'Volatile memory captures live attacker behaviour that disk-only analysis misses.', 'ADVANCED', 3, 'MCQ', 1),
(6593, 290, 'Which procedure best preserves forensic value when rebuilding a compromised environment?', 'Snapshot the old environment and lock it before rebuilding with IaC', 'Overwrite the old disks immediately', 'Delete the evidence', 'Rebuild without documenting', 'A', 'Preserving and locking the old state lets investigators analyse it after the rebuild.', 'ADVANCED', 3, 'MCQ', 1),
(6594, 290, 'Which issue most complicates attribution in cloud forensics?', 'Attackers often operate through stolen credentials, proxies and shared infrastructure', 'Clouds have no logs', 'There is only one attacker', 'Evidence is never volatile', 'A', 'Stolen credentials and anonymising layers make identifying the true actor difficult.', 'ADVANCED', 3, 'MCQ', 1),
(6595, 290, 'Which integration most improves mean time to detect a cloud incident?', 'Automated alert correlation and threat intelligence feeds into a SIEM', 'Manual log review once a week', 'Checking the console occasionally', 'Ignoring alerts', 'A', 'Automated correlation and intelligence cut detection time by surfacing real threats fast.', 'ADVANCED', 3, 'MCQ', 1),
(6596, 290, 'Which containment decision is most appropriate for a service hosting customer data during an active breach?', 'Isolate the service while preserving forensic evidence, then notify affected users', 'Keep it running with no action', 'Delete the customer data', 'Disable all logging', 'A', 'Isolation preserves evidence and stops damage while notification meets legal duties.', 'ADVANCED', 3, 'MCQ', 1),
(6597, 290, 'What is the main reason a cloud IR team tests incident response playbooks regularly?', 'To ensure the documented steps work in the real environment before a crisis', 'To fill time', 'To increase log volume', 'To reduce the team''s workload', 'A', 'Regular exercises validate that playbooks work and the team knows its roles.', 'ADVANCED', 3, 'MCQ', 1),
(6598, 290, 'Which evidence preservation practice is most important when an incident spans multiple cloud accounts?', 'Preserving logs and snapshots from every affected account with a central index', 'Saving logs from only one account', 'Deleting shared evidence', 'Preserving only billing records', 'A', 'A centralised, complete evidence index supports a coherent investigation across accounts.', 'ADVANCED', 3, 'MCQ', 1),
(6599, 290, 'Which outcome best demonstrates that a cloud incident was truly resolved?', 'Root cause eliminated, affected systems restored and validation shows no remaining foothold', 'The alert stopped firing', 'A month passed without changes', 'The attacker apologised', 'A', 'Resolution requires eradicated root cause, restored systems and validated cleanup, not just quiet alerts.', 'ADVANCED', 3, 'MCQ', 1),
(6600, 290, 'Which approach best preserves forensic evidence when a cloud incident also involves a data deletion event?', 'Enable object versioning and point-in-time recovery before incidents so deleted data can be restored and examined', 'Rely on the attacker''s logs', 'Disable versioning to save cost', 'Recreate the data from memory', 'A', 'Versioning and point-in-time recovery preserve deleted objects so investigators can analyse them after the fact.', 'ADVANCED', 3, 'MCQ', 1);
